	const contentWidth = filterBar ? filterBar.scrollWidth : track.scrollWidth;
	const maxScrollLeft = Math.max(0, contentWidth - track.clientWidth);
	if (track.scrollLeft > maxScrollLeft) track.scrollLeft = maxScrollLeft;
	const nextScrollLeft = Math.max(0, Math.min(maxScrollLeft, track.scrollLeft + delta));
	if (Math.abs(nextScrollLeft - track.scrollLeft) <= 1) return false;
