async function prepareMapRegionBoundaryRemoteSelection(city, dong)
{
	const normalizedCity = normalizeJejuCityName(city || "제주시");
	const normalizedDong = normalizeRegionDongName(dong || "");
	if (!normalizedDong) {
		clearMapRegionBoundaryListState();
		return null;
	}
	try {
		const boundaryType = /리$/.test(normalizedDong) ? "lio" : "emd";
		const data = await loadAdminBoundaryGeoJson(boundaryType);
		const cityCode = normalizedCity === "서귀포시" ? "50130" : "50110";
		const aliases = new Set(
			getMapRegionDongAliases(normalizedCity, normalizedDong)
				.map(normalizeRegionDongName)
				.filter(Boolean)
		);
		aliases.add(normalizedDong);
		const feature = (data?.features || []).find((candidate) => {
			const code = getAdminBoundaryFeatureCodeValue(candidate);
			const name = normalizeRegionDongName(getAdminBoundaryFeatureName(candidate));
			return (!code || code.startsWith(cityCode)) && aliases.has(name);
		}) || null;
		if (!feature) {
			clearMapRegionBoundaryListState();
			return null;
		}
		// 4.925: 상단 위치 선택도 현재 지도에 남은 격자 대표 행을 세지 않는다.
		// 선택한 법정구역의 서버 집계와 첫 30건을 하단 지역 버튼과 같은 경로로 준비한다.
		const stats = await loadPropertyScaleFeatureStats(feature);
		await setMapRegionBoundaryListStateFromAdminFeature(feature, stats.listingCount);
		await loadMapRegionBoundaryRemotePage({ reset: true });
		return getMapRegionBoundaryListState();
	} catch (error) {
		clearMapRegionBoundaryListState();
		console.warn("상단 지역 매물 30건 조회 실패:", error?.message || error);
		return null;
	}
}

function updateMapRegionSort(action)
{
	if (action === "price") {
		mapRegionFilterState.sort = mapRegionFilterState.sort === "price-asc" ? "price-desc" : "price-asc";
	} else if (action === "area") {
		mapRegionFilterState.sort = mapRegionFilterState.sort === "area-asc" ? "area-desc" : "area-asc";
	} else if (action === "popular") {
		mapRegionFilterState.sort = "popular";
	} else {
		mapRegionFilterState.sort = "latest";
	}
	const boundaryState = getMapRegionBoundaryListState();
	if (boundaryState && boundaryState.regionCode) {
		// 4.925: 지역 목록 정렬도 현재 30개만 브라우저에서 재정렬하지 않고
		// 서버에 새 정렬을 전달해 첫 페이지부터 다시 받는다.
		void loadMapRegionBoundaryRemotePage({ reset: true })
			.then(() => {
				if (getMapRegionBoundaryListState() === boundaryState) renderMapRegionFilterMenu();
			})
			.catch((error) => console.warn("지역 매물 정렬 조회 실패:", error));
		return;
	}
	renderMapRegionFilterMenu();
}

