async function openMapRegionComplexDetail(index, regionDropdown, regionTrigger)
{
	const groupIndex = Number(index);
	if (!Number.isInteger(groupIndex) || groupIndex < 0) return;
	const group = mapRegionComplexDetailGroups[groupIndex];
	const item = group && (group.first || (Array.isArray(group.items) && group.items[0]));
	if (!item) return;
	clearMapRegionDetailPanelNextToMenu();
	if (regionDropdown) {
		regionDropdown.classList.remove("open");
		if (regionTrigger) regionTrigger.setAttribute("aria-expanded", "false");
	}
	const boundaryState = typeof getMapRegionBoundaryListState === "function"
		? getMapRegionBoundaryListState()
		: null;
	if (boundaryState && boundaryState.feature && typeof openPropertyRegionCountListPanel === "function") {
		await openPropertyRegionCountListPanel(
			boundaryState.feature,
			Math.max(boundaryState.items?.length || 0, Number(boundaryState.totalCount) || Number(boundaryState.count) || 0)
		);
	} else {
		const regionItems = [];
		const seenIds = new Set();
		mapRegionComplexDetailGroups.forEach((entryGroup) => {
			const entries = Array.isArray(entryGroup?.items) && entryGroup.items.length
				? entryGroup.items
				: [entryGroup?.first];
			entries.filter(Boolean).forEach((entry) => {
				const id = normalizeItemId(entry?.id);
				if (!id || seenIds.has(id)) return;
				seenIds.add(id);
				regionItems.push(entry);
			});
		});
		const selectedId = normalizeItemId(item.id);
		if (selectedId && !seenIds.has(selectedId)) regionItems.unshift(item);
		hardCloseDetailPanel();
		currentDetailItem = null;
		clearAgentListFilter();
		state.leftListDetailMode = "map-region";
		state.leftListTitle = "매물 목록";
		state.selectionMode = "region-list";
		lockListToItems(regionItems, { keepOnMapClick: true });
		openSidebarList();
		resetLeftListPagination(regionItems);
		if (propertyList) {
			propertyList.innerHTML = "";
			propertyList.scrollTop = 0;
		}
		await loadMoreLeftListItems({ sourceItems: regionItems, renderImmediately: true });
		setResultInfo("선택 지역 매물 " + regionItems.length + "건");
		setListInfo("총 " + regionItems.length + "개 매물");
		if (typeof syncSidebarListTitle === "function") syncSidebarListTitle();
	}
	state.leftListDetailMode = "map-region";
	await openListSharedDetailFromItem(item);
}

async function focusMapRegionByMeta(meta, options = {})
{
	const opts = options || {};
	if (!window.kakao || !kakao.maps || !kakao.maps.services) {
		setAddressSearchStatus("주소 검색 서비스를 불러오지 못했습니다.", true);
		return;
	}
	const province = meta.province === "제주도" ? "제주특별자치도" : (meta.province || "제주특별자치도");
	const city = normalizeJejuCityName(meta.city || "제주시");
	const dong = normalizeRegionDongName(meta.dong || "");
	const query = [province, city, dong].filter(Boolean).join(" ");
	const geocoder = null;
	const places = new kakao.maps.services.Places();
	const queries = buildSubAddressSearchQueries(query);
	for (const q of queries) {
			const geocoded = await searchAddressByGeocoder(geocoder, q);
			if (geocoded) {
				focusMapByAddress(geocoded.y, geocoded.x, dong ? `${city} ${dong}` : city, {
					silent: !!opts.silent,
					leftListDetailMode: opts.leftListDetailMode || ""
				});
				return;
			}
		}
		for (const q of queries) {
			const searched = await searchAddressByKeyword(places, q);
			if (searched) {
				focusMapByAddress(searched.y, searched.x, dong ? `${city} ${dong}` : city, {
					silent: !!opts.silent,
					leftListDetailMode: opts.leftListDetailMode || ""
				});
				return;
			}
		}
	setAddressSearchStatus(`${dong || city} 위치를 찾지 못했습니다.`, true);
}

function isRealjejuPasswordRecoveryLocked()
{
	return !!(
		window.realjejuPasswordRecoveryRequired ||
		(document.body && document.body.classList.contains("auth-recovery-page-open"))
	);
}

function keepRealjejuPasswordRecoveryScreen(event)
{
	if (event) {
		event.preventDefault();
		event.stopPropagation();
		if (typeof event.stopImmediatePropagation === "function") event.stopImmediatePropagation();
	}
	if (typeof window.openRealjejuPasswordRecoveryScreen === "function") {
		window.openRealjejuPasswordRecoveryScreen();
		return;
	}
	const authModal = document.getElementById("authModal");
	const resetScreen = document.getElementById("authResetPasswordScreen");
	if (authModal) {
		document.body.classList.add("auth-page-open", "auth-recovery-page-open", "sidebar-list-collapsed");
		authModal.classList.add("open");
		authModal.classList.remove("profile-page-mode");
		authModal.setAttribute("aria-hidden", "false");
	}
	if (resetScreen) resetScreen.classList.remove("auth-screen-hidden");
}

document.addEventListener("click", function(event) {
	if (!isRealjejuPasswordRecoveryLocked()) return;
	const target = event.target && event.target.closest ? event.target.closest(".topbar-menu-item, .global-brand") : null;
	if (!target) return;
	keepRealjejuPasswordRecoveryScreen(event);
}, true);

(function bindNoticePage()
{
	function formatNoticeDate(value)
	{
		const rawValue = String(value || "").trim();
		const dateOnlyMatch = rawValue.match(/^(\d{4})-(\d{2})-(\d{2})/);
		if (dateOnlyMatch) return `${dateOnlyMatch[1]}.${dateOnlyMatch[2]}.${dateOnlyMatch[3]}`;
		const date = new Date(rawValue);
		if (Number.isNaN(date.getTime())) return "";
		const yyyy = date.getFullYear();
		const mm = String(date.getMonth() + 1).padStart(2, "0");
		const dd = String(date.getDate()).padStart(2, "0");
		return `${yyyy}.${mm}.${dd}`;
	}

	function escapeNoticeHtml(value)
	{
		return String(value ?? "")
			.replace(/&/g, "&amp;")
			.replace(/</g, "&lt;")
			.replace(/>/g, "&gt;")
			.replace(/"/g, "&quot;")
			.replace(/'/g, "&#39;");
	}

	function renderNoticeLineHtml(content)
	{
		const urlPattern = /https?:\/\/[^\s<>"']+/gi;
		let html = "";
		let cursor = 0;
		for (const match of content.matchAll(urlPattern)) {
			const rawUrl = match[0];
			const url = rawUrl.replace(/[.,!?;:]+$/g, "");
			const trailingText = rawUrl.slice(url.length);
			html += escapeNoticeHtml(content.slice(cursor, match.index));
			if (url) {
				const safeUrl = escapeNoticeHtml(url);
				html += `<a class="notice-content-link" href="${safeUrl}" target="_blank" rel="noopener noreferrer">${safeUrl}</a>`;
			}
			html += escapeNoticeHtml(trailingText);
			cursor = Number(match.index) + rawUrl.length;
		}
		return html + escapeNoticeHtml(content.slice(cursor));
	}

	function renderNoticeContentHtml(value)
	{
		return String(value ?? "")
			.replace(/\r\n?/g, "\n")
			.split("\n")
			.map((line) => {
				const trimmedLine = line.trim();
				const isEmphasisLine = line.includes("✅") || /^\[[^\[\]\r\n]+\]$/.test(trimmedLine);
				const lineHtml = renderNoticeLineHtml(line);
				return isEmphasisLine
					? `<strong class="notice-content-emphasis">${lineHtml}</strong>`
					: lineHtml;
			})
			.join("\n");
	}

	let publicNoticeRowsCache = null;
	let publicNoticeRowsPromise = null;

	function renderNoticeRows(listEl, rows)
	{
		listEl.innerHTML = rows.map((row) => `
			<article class="notice-item ${row.is_pinned ? "is-pinned" : ""}">
				<div class="notice-item-meta">
					<span class="notice-badge ${row.is_pinned ? "" : "notice-badge-soft"}">${escapeNoticeHtml(String(row.category || (row.is_pinned ? "중요" : "공지")).trim())}</span>
					<time datetime="${escapeNoticeHtml(String(row.created_at || ""))}">${escapeNoticeHtml(formatNoticeDate(row.created_at || row.updated_at))}</time>
				</div>
				<div>
					<h2 class="notice-item-title">${escapeNoticeHtml(row.title || "제목 없음")}</h2>
					<p class="notice-item-desc">${renderNoticeContentHtml(row.content || "")}</p>
				</div>
			</article>
		`).join("");
	}

	async function getPublicNoticeRows(options = {})
	{
		const force = options && options.force === true;
		if (!force && typeof shouldLoadRealjejuRemotePageData === "function" && !shouldLoadRealjejuRemotePageData("notices")) {
			return [];
		}
		if (force) publicNoticeRowsCache = null;
		if (Array.isArray(publicNoticeRowsCache)) return publicNoticeRowsCache;
		if (publicNoticeRowsPromise) return publicNoticeRowsPromise;
		publicNoticeRowsPromise = (async () => {
			if (!window.supabase || typeof window.supabase.createClient !== "function") {
				if (typeof loadSupabaseScript !== "function") throw new Error("Supabase 로더가 준비되지 않았습니다.");
				await loadSupabaseScript();
			}
			const sharedClient = typeof getRealjejuSupabaseClient === "function"
				? getRealjejuSupabaseClient()
				: (typeof window.getRealjejuSupabaseClient === "function" ? window.getRealjejuSupabaseClient() : null);
			const client = sharedClient || (typeof getMapListingsSupabaseClient === "function"
				? getMapListingsSupabaseClient()
				: null);
			if (!client) throw new Error("Supabase 공지사항 클라이언트를 만들지 못했습니다.");
			const { data, error } = await client
				.from("notices")
				.select("id, title, content, category, is_pinned, is_visible, created_at, updated_at, deleted_at")
				.eq("is_visible", true)
				.is("deleted_at", null)
				.order("is_pinned", { ascending: false })
				.order("created_at", { ascending: false });
			if (error) throw error;
			publicNoticeRowsCache = Array.isArray(data) ? data : [];
			return publicNoticeRowsCache;
		})().finally(() => {
			publicNoticeRowsPromise = null;
		});
		return publicNoticeRowsPromise;
	}

	function renderLandingNoticePreview(rows)
	{
		const listEl = document.getElementById("mainLandingNoticeList");
		if (!listEl) return;
		const previewRows = Array.isArray(rows) ? rows.slice(0, 3) : [];
		listEl.setAttribute("aria-busy", "false");
		if (!previewRows.length) {
			listEl.innerHTML = '<div class="main-landing-notice-empty">등록된 공지사항이 없습니다.</div>';
			return;
		}
		listEl.innerHTML = previewRows.map((row) => {
			const dateValue = String(row.created_at || row.updated_at || "");
			return `
				<button type="button" class="main-landing-notice-row" data-main-landing-action="notice">
					<span class="main-landing-notice-row-title">${escapeNoticeHtml(row.title || "제목 없음")}</span>
					<time datetime="${escapeNoticeHtml(dateValue)}">${escapeNoticeHtml(formatNoticeDate(dateValue))}</time>
				</button>
			`;
		}).join("");
	}

	async function loadLandingNoticePreview(options = {})
	{
		const listEl = document.getElementById("mainLandingNoticeList");
		if (!listEl) return;
		listEl.setAttribute("aria-busy", "true");
		try {
			const rows = await getPublicNoticeRows(options);
			renderLandingNoticePreview(rows);
		} catch (err) {
			console.warn("랜딩 공지사항 로드 실패:", err);
			listEl.setAttribute("aria-busy", "false");
			listEl.innerHTML = '<div class="main-landing-notice-empty">공지사항을 불러오지 못했습니다.</div>';
		}
	}

	async function loadPublicNotices(options = {})
	{
		const listEl = document.getElementById("noticeList");
		if (!listEl) return;
		listEl.innerHTML = '<div class="notice-empty">공지사항을 불러오는 중입니다.</div>';
		try {
			const rows = await getPublicNoticeRows(options);
			if (!rows.length) {
				listEl.innerHTML = '<div class="notice-empty">등록된 공지사항이 없습니다.</div>';
				return;
			}
			renderNoticeRows(listEl, rows);
		} catch (err) {
			console.warn("공지사항 로드 실패:", err);
			listEl.innerHTML = '<div class="notice-empty">공지사항을 불러오지 못했습니다.</div>';
		}
	}

	async function refreshPublicNotices()
	{
		publicNoticeRowsCache = null;
		await Promise.all([
			loadLandingNoticePreview(),
			loadPublicNotices()
		]);
	}

	function setNoticeTopbarActive()
	{
		document.querySelectorAll(".topbar-menu-item").forEach((btn) => {
			btn.classList.toggle("active", String(btn.textContent || "").trim() === "공지사항");
		});
	}

	function syncNoticeAdminButton()
	{
		const btn = document.getElementById("noticeAdminManageBtn");
		if (!btn) return;
		const user = window.currentRealjejuAuthUser || (typeof currentRealjejuAuthUser !== "undefined" ? currentRealjejuAuthUser : null);
		const hasAdminMenu = Array.from(document.querySelectorAll(".topbar-menu-item")).some((item) => String(item.textContent || "").trim() === "관리자 페이지");
		const accountLabel = String(document.querySelector(".global-auth-trigger")?.textContent || "").trim();
		const isAdmin = (typeof isAdminUser === "function" && isAdminUser(user)) || hasAdminMenu || accountLabel.includes("관리자");
		btn.hidden = !isAdmin;
	}

	function closeNoticePage()
	{
		const panel = document.getElementById("noticePagePanel");
		if (panel) panel.setAttribute("aria-hidden", "true");
		document.body.classList.remove("notice-page-open");
	}

	function openNoticePage()
	{
		if (typeof forgetCollapsedMapPanelForHome === "function") forgetCollapsedMapPanelForHome();
		const panel = document.getElementById("noticePagePanel");
		if (!panel) return;
		if (typeof closeAuthModal === "function") closeAuthModal();
		if (typeof window.closeMySuitePage === "function") window.closeMySuitePage();
		if (typeof window.closePaymentPage === "function") window.closePaymentPage();
		if (typeof window.closePropertyRegisterPage === "function") {
			window.closePropertyRegisterPage({
				suppressBrokerHomeReturn: true,
				suppressMapHomeReturn: true,
				suppressAdminListingsReturn: true,
				suppressMySuiteFavoritesReturn: true
			});
		}
		if (typeof window.closeAdminPage === "function") window.closeAdminPage();
		if (typeof window.closeOperatorPage === "function") window.closeOperatorPage();
		if (typeof window.closeBrokerHomePage === "function") window.closeBrokerHomePage();
		document.body.classList.remove(
			"auth-page-open",
			"payment-page-open",
			"profile-page-open",
			"myinfo-page-open",
			"profile-edit-page-open",
			"broker-office-info-page-open",
			"broker-office-apply-page-open",
			"broker-office-edit-page-open",
			"property-register-page-open",
			"admin-page-open",
			"operator-page-open",
			"broker-home-page-open",
			"my-suite-page-open",
			"notice-page-open"
		);
		[
			"mySuitePanel",
			"paymentPagePanel",
			"myInfoPagePanel",
			"profileEditPagePanel",
			"brokerOfficeInfoPagePanel",
			"brokerOfficeApplyPagePanel",
			"brokerOfficeEditPagePanel",
			"brokerHomePanel",
			"adminPagePanel",
			"propertyRegisterPage"
		].forEach((id) => {
			const el = document.getElementById(id);
			if (el) el.setAttribute("aria-hidden", "true");
		});
		document.body.classList.add("sidebar-list-collapsed", "notice-page-open");
		panel.setAttribute("aria-hidden", "false");
		panel.scrollTop = 0;
		setNoticeTopbarActive();
		syncNoticeAdminButton();
		loadPublicNotices();
	}

	document.addEventListener("click", function(event) {
		const menuBtn = event.target && event.target.closest ? event.target.closest(".topbar-menu-item") : null;
		if (!menuBtn) return;
		if (String(menuBtn.textContent || "").trim() !== "공지사항") {
			closeNoticePage();
			return;
		}
		event.preventDefault();
		event.stopPropagation();
		if (typeof event.stopImmediatePropagation === "function") event.stopImmediatePropagation();
		if (window.realjejuRouter && typeof window.realjejuRouter.navigate === "function") {
			window.realjejuRouter.navigate("/notices");
			return;
		}
		openNoticePage();
	}, true);

	document.addEventListener("click", function(event) {
		const manageBtn = event.target && event.target.closest ? event.target.closest("#noticeAdminManageBtn") : null;
		if (!manageBtn) return;
		event.preventDefault();
		event.stopPropagation();
		const adminOpener = typeof window.openAdminPage === "function" ? window.openAdminPage : (typeof openAdminPage === "function" ? openAdminPage : null);
		if (adminOpener) {
			Promise.resolve(adminOpener("notices")).then(() => {
				const manager = document.getElementById("adminNoticeManager");
				if (manager) manager.scrollIntoView({ block: "start", behavior: "smooth" });
				const titleInput = document.getElementById("adminNoticeTitleInput");
				if (titleInput && typeof titleInput.focus === "function") titleInput.focus({ preventScroll: true });
			});
		}
	}, true);

	window.openNoticePage = openNoticePage;
	window.closeNoticePage = closeNoticePage;
	window.loadPublicNotices = loadPublicNotices;
	window.loadLandingNoticePreview = loadLandingNoticePreview;
	window.refreshPublicNotices = refreshPublicNotices;
	if (document.body?.classList?.contains("main-landing-page-open")) {
		setTimeout(() => loadLandingNoticePreview(), 0);
	}
})();

(function bindRealjejuSideNav()
{
	let sideAccountOfficeLookupUserId = "";
	let sideAccountOfficeLookupPromise = null;
	let sideNavKnownAdminUserId = "";

	function getSideNav()
	{
		return document.getElementById("realjejuSideNav");
	}

		function getSideNavAction()
		{
			if (document.body.classList.contains("admin-page-open")) return "admin";
			if (document.body.classList.contains("operator-page-open")) return "operator";
			if (document.body.classList.contains("broker-home-page-open")) return "broker-home";
			if (document.body.classList.contains("property-register-page-open")) return "register";
			if (document.body.classList.contains("notice-page-open")) return "notice";
			if (document.body.classList.contains("my-suite-page-open")) {
				const activeMySuiteTab = document.querySelector(".my-suite-tab.active");
				return activeMySuiteTab && activeMySuiteTab.dataset.mySuiteTab === "favorites" ? "favorites" : "";
			}
			if (document.body.classList.contains("presale-page-open")) return "presale";
			return "home";
		}

	function syncSideNavActive()
	{
		const sideNav = getSideNav();
		if (!sideNav) return;
		const activeAction = getSideNavAction();
		sideNav.querySelectorAll("[data-side-nav-action]").forEach((btn) => {
			btn.classList.toggle("active", btn.dataset.sideNavAction === activeAction);
		});
	}

	function setSideNavActionHidden(action, hidden)
	{
		const sideNav = getSideNav();
		if (!sideNav) return;
		sideNav.querySelectorAll(`[data-side-nav-action="${action}"]`).forEach((btn) => {
			btn.hidden = !!hidden;
			btn.setAttribute("aria-hidden", hidden ? "true" : "false");
		});
	}

	function hasVisibleSideNavAction(action)
	{
		const sideNav = getSideNav();
		if (!sideNav) return false;
		return Array.from(sideNav.querySelectorAll(`[data-side-nav-action="${action}"]`)).some((btn) => btn && !btn.hidden && btn.getAttribute("aria-hidden") !== "true");
	}

	function getSideAccountOfficeName(row)
	{
		return String(row && (row.office_name || row.company_name || row.name) || "").trim();
	}

	function isSideAccountDeletedOffice(row)
	{
		const status = String(row && row.status || "").replace(/\s+/g, "").toLowerCase();
		return !!(row && row.deleted_at) || ["deleted", "delete", "trash", "withdrawn", "삭제", "휴지통"].includes(status);
	}

	function isSideAccountApprovedOffice(row)
	{
		const status = String(row && row.status || "").replace(/\s+/g, "").toLowerCase();
		return ["active", "approved", "approve", "accepted", "승인", "승인완료", "완료"].includes(status);
	}

	function isSideNavAdminProfile(profile)
	{
		const data = profile || {};
		const role = String(data.role || data.app_role || data.user_role || "").trim().toLowerCase();
		return role === "admin" || data.is_admin === true || data.admin === true;
	}

	function isSideNavOperatorProfile(profile)
	{
		const data = profile || {};
		const role = String(data.role || data.app_role || data.user_role || data.role_request || "").trim().toLowerCase();
		return ["operator", "operations", "운영자"].includes(role) || data.is_operator === true || data.operator === true;
	}

	function setSideNavAdminMenuMode(mode)
	{
		const btn = getSideNav()?.querySelector('[data-side-nav-action="admin"], [data-side-nav-action="operator"]');
		if (!btn) return;
		const isOperatorMode = mode === "operator";
		btn.dataset.sideNavAction = isOperatorMode ? "operator" : "admin";
		const label = btn.querySelector("span");
		if (label) label.textContent = isOperatorMode ? "운영자 페이지" : "관리자 페이지";
	}

	function syncSideNavVisibility()
	{
		const user = window.realjejuCurrentAuthUser || null;
		const profile = window.realjejuCurrentProfile || null;
		const brokerOffice = window.realjejuCurrentBrokerOffice || null;
		const userId = String(user && user.id || "").trim();
		const isLoggedIn = !!userId;
		const canUseBrokerRole = isLoggedIn
			&& typeof canRealjejuUseBrokerHomeRole === "function"
			&& canRealjejuUseBrokerHomeRole(user, profile);
		const canUseBrokerHome = canUseBrokerRole && isLoggedIn && isSideAccountApprovedOffice(brokerOffice);
		const adminWasVisible = isLoggedIn && hasVisibleSideNavAction("admin");
		const operatorWasVisible = isLoggedIn && hasVisibleSideNavAction("operator");
		let canUseAdmin = isLoggedIn && (window.realjejuCurrentIsAdmin === true || isSideNavAdminProfile(profile));
		let canUseOperator = isLoggedIn && !canUseAdmin && (window.realjejuCurrentIsOperator === true || isSideNavOperatorProfile(profile));
		if (!isLoggedIn) {
			sideNavKnownAdminUserId = "";
		} else if (canUseAdmin) {
			sideNavKnownAdminUserId = userId;
		} else if (sideNavKnownAdminUserId === userId || adminWasVisible) {
			canUseAdmin = true;
			sideNavKnownAdminUserId = userId;
			window.realjejuCurrentIsAdmin = true;
		} else if (operatorWasVisible && (window.realjejuCurrentIsOperator === true || isSideNavOperatorProfile(profile))) {
			canUseOperator = true;
		}
		const isNonRealestateCategory = document.body && !isGlobalRealestateCategory(document.body.dataset.globalCategory);
		setSideNavAdminMenuMode(canUseOperator ? "operator" : "admin");
		setSideNavActionHidden("broker-home", !canUseBrokerHome);
		const useRealestateMobileDrawer = window.matchMedia("(max-width: 850px)").matches;
		setSideNavActionHidden(
			"register",
			useRealestateMobileDrawer ? !canUseBrokerHome : (isNonRealestateCategory ? false : !canUseBrokerHome)
		);
		setSideNavActionHidden(canUseOperator ? "operator" : "admin", !(canUseAdmin || canUseOperator));
		const canShowManagementVersion = canUseAdmin || canUseOperator;
		const adminVersion = document.getElementById("realjejuSideAdminVersion");
		if (adminVersion) {
			adminVersion.hidden = !canShowManagementVersion;
			adminVersion.setAttribute("aria-hidden", canShowManagementVersion ? "false" : "true");
		}
		getSideNav()?.classList.toggle("admin-version-visible", canShowManagementVersion);
		if (typeof updateRealjejuTopbarVersionText === "function") {
			Promise.resolve().then(() => updateRealjejuTopbarVersionText());
		}
		if (canShowManagementVersion && typeof window.realjejuSyncManagementVersionListingCount === "function") {
			Promise.resolve().then(() => window.realjejuSyncManagementVersionListingCount());
		}
	}

		async function loadSideAccountOfficeName(user)
		{
		const userId = String(user && user.id || "").trim();
		if (!userId) return "";
		if (typeof shouldLoadRealjejuRemotePageData === "function" && !shouldLoadRealjejuRemotePageData("agencies")) {
			return String(window.realjejuCurrentBrokerOfficeName || "").trim();
		}
		if (sideAccountOfficeLookupUserId === userId && sideAccountOfficeLookupPromise) return sideAccountOfficeLookupPromise;
		sideAccountOfficeLookupUserId = userId;
		sideAccountOfficeLookupPromise = (async () => {
			const client = typeof window.getRealjejuSupabaseClient === "function" ? window.getRealjejuSupabaseClient() : null;
			if (!client) return "";
			const rows = [];
			try {
				const { data } = await client
					.from("agencies")
					.select("*")
					.eq("user_id", userId)
					.order("updated_at", { ascending: false })
					.limit(10);
				if (Array.isArray(data)) rows.push(...data);
			} catch (err) {}
			const visibleRows = rows.filter((row) => row && !isSideAccountDeletedOffice(row));
			const office = visibleRows.find(isSideAccountApprovedOffice) || visibleRows[0] || null;
			const officeName = getSideAccountOfficeName(office);
			if (officeName) {
				window.realjejuCurrentBrokerOffice = {
					...(window.realjejuCurrentBrokerOffice || {}),
					...office
				};
				window.realjejuCurrentBrokerOfficeName = officeName;
			}
			return officeName;
		})();
		return sideAccountOfficeLookupPromise;
	}

	function syncSideNavAccount()
	{
		const sideNav = getSideNav();
		if (!sideNav) return;
		syncSideNavVisibility();
		const sideAccount = document.getElementById("realjejuSideAccountTrigger");
		const sideBadge = document.getElementById("realjejuSideAccountBadge");
		const sideImage = document.getElementById("realjejuSideAccountImage");
		const sideName = document.getElementById("realjejuSideAccountName");
		if (!sideName) return;
		const user = window.realjejuCurrentAuthUser || null;
		const profile = window.realjejuCurrentProfile || null;
		const brokerOffice = window.realjejuCurrentBrokerOffice || null;
		const isLoggedIn = !!(user && user.id);
		const officeName = getSideAccountOfficeName(brokerOffice) || String(window.realjejuCurrentBrokerOfficeName || "").trim();
		const guestAccountLabel = "로그인 · 회원가입";
		const nameText = isLoggedIn ? String(officeName || (profile && profile.name) || user.email || "로그인").trim() : guestAccountLabel;
		sideName.textContent = nameText || (isLoggedIn ? "로그인" : guestAccountLabel);
		if (isLoggedIn && !officeName) {
			loadSideAccountOfficeName(user).then((loadedName) => {
				const currentUser = window.realjejuCurrentAuthUser || null;
				if (!loadedName || !currentUser || String(currentUser.id || "") !== String(user.id || "")) return;
				sideName.textContent = loadedName;
			}).catch(() => {});
		}
		const profileImage = isLoggedIn && profile && profile.profile_image ? String(profile.profile_image).trim() : "";
		if (sideAccount) {
			sideAccount.classList.toggle("has-profile-image", !!profileImage);
		}
		if (sideImage) {
			sideImage.hidden = !profileImage;
			sideImage.src = profileImage || "";
		}
		if (sideBadge) {
			sideBadge.hidden = !isLoggedIn || !!profileImage;
		}
		syncSideNavVisibility();
	}

	function syncSideNavLifeSafety()
	{
		const sideCheckbox = document.getElementById("realjejuSideLifeSafetyCheck");
		if (!sideCheckbox) return;
		const mainCheckbox = document.getElementById("lifeSafetyOverlayCheck");
		sideCheckbox.checked = mainCheckbox ? !!mainCheckbox.checked : false;
	}

	function closeAnalysisFlyout()
	{
		const sideNav = getSideNav();
		if (!sideNav) return;
		const trigger = sideNav.querySelector('[data-side-nav-action="analysis"]');
		const flyout = document.getElementById("realjejuSideAnalysisMenu");
		const arrow = trigger ? trigger.querySelector(".realjeju-side-nav-arrow") : null;
		if (trigger) {
			trigger.classList.remove("is-open");
			trigger.setAttribute("aria-expanded", "false");
		}
		if (arrow) {
			arrow.classList.remove("fa-chevron-up");
			arrow.classList.add("fa-chevron-down");
		}
		if (flyout) {
			flyout.classList.remove("open");
			flyout.setAttribute("aria-hidden", "true");
		}
	}

	function closeSideAccountMenu()
	{
		const sideNav = getSideNav();
		const trigger = document.getElementById("realjejuSideAccountTrigger");
		const menu = document.getElementById("realjejuSideAccountMenu");
		const arrow = trigger ? trigger.querySelector(".realjeju-side-account-arrow") : null;
		if (sideNav) sideNav.classList.remove("account-menu-expanded");
		if (trigger) trigger.classList.remove("account-open");
		if (arrow) {
			arrow.classList.add("fa-chevron-down");
			arrow.classList.remove("fa-chevron-up");
		}
		if (menu) {
			menu.classList.remove("open");
			menu.setAttribute("aria-hidden", "true");
		}
		syncSideAccountActive("");
	}

	function syncSideAccountActive(action)
	{
		const sideNav = getSideNav();
		if (!sideNav) return;
		const activeAction = String(action || "").trim();
		sideNav.querySelectorAll(".realjeju-side-account-menu-item[data-account-action]").forEach((btn) => {
			const isActive = !!activeAction && btn.dataset.accountAction === activeAction;
			btn.classList.toggle("active", isActive);
			if (isActive) btn.setAttribute("aria-current", "page");
			else btn.removeAttribute("aria-current");
		});
	}

	function isSideAccountAccordionViewport()
	{
		return typeof window.matchMedia === "function" && window.matchMedia("(max-width: 850px)").matches;
	}

	function openSideAccountMenuForMySuite(action)
	{
		if (!isSideAccountAccordionViewport()) {
			closeSideAccountMenu();
			return;
		}
		const sideNav = getSideNav();
		const trigger = document.getElementById("realjejuSideAccountTrigger");
		const menu = document.getElementById("realjejuSideAccountMenu");
		if (!sideNav || !trigger || !menu) return;
		const arrow = trigger.querySelector(".realjeju-side-account-arrow");
		sideNav.classList.add("account-menu-expanded");
		trigger.classList.add("account-open");
		if (arrow) {
			arrow.classList.add("fa-chevron-down");
			arrow.classList.remove("fa-chevron-up");
		}
		menu.classList.add("open");
		menu.setAttribute("aria-hidden", "false");
		syncSideAccountActive(action);
	}

	function isSideNavLoggedIn()
	{
		const user = window.realjejuCurrentAuthUser || null;
		return !!(user && user.id);
	}

	function openSideNavLoginRequired(message, title)
	{
		const errorModal = typeof window.openAuthErrorModal === "function" ? window.openAuthErrorModal : (typeof openAuthErrorModal === "function" ? openAuthErrorModal : null);
		const loginModal = typeof window.openAuthModal === "function" ? window.openAuthModal : (typeof openAuthModal === "function" ? openAuthModal : null);
		if (errorModal) {
			errorModal(message, title, null, loginModal || null);
			return;
		}
		if (loginModal) {
			loginModal();
			return;
		}
		alert(message);
	}

	function requireSideNavLogin(message, title)
	{
		if (isSideNavLoggedIn()) return true;
		closeAnalysisFlyout();
		closeSideAccountMenu();
		openSideNavLoginRequired(message, title);
		return false;
	}

	function navigateSideNavRoute(path)
	{
		const router = window.realjejuRouter;
		if (!router || typeof router.navigate !== "function") return false;
		router.navigate(path);
		return true;
	}

	function clearSideNavMapPanelState(options = {})
	{
		const shouldRememberCollapsedPanel = options && options.rememberCollapsed === true;
		if (!shouldRememberCollapsedPanel && typeof forgetCollapsedMapPanelForHome === "function") forgetCollapsedMapPanelForHome();
		const hasCollapsedPanel = document.body.classList.contains("map-panels-collapsed");
		const hasDetailPanel = document.body.classList.contains("map-detail-panel-active") || document.body.classList.contains("detail-page-panel-open");
		if (!hasCollapsedPanel && !hasDetailPanel) return;
		if (typeof closeDetailImageLightbox === "function") closeDetailImageLightbox();
		if (hasCollapsedPanel) {
			if (shouldRememberCollapsedPanel && typeof rememberCollapsedMapPanelForHome === "function") rememberCollapsedMapPanelForHome();
			document.body.classList.remove("map-panels-collapsed", "map-detail-panel-active", "detail-page-panel-open");
			const panel = document.getElementById("sidebarDetailPanel");
			if (panel) {
				panel.style.opacity = "0";
				panel.style.pointerEvents = "none";
				panel.style.visibility = "hidden";
			}
			const toggle = document.getElementById("mapPanelToggle");
			if (toggle) toggle.hidden = true;
			return;
		}
		if (typeof closeDetailPanel === "function") {
			closeDetailPanel();
			return;
		}
		document.body.classList.remove("map-panels-collapsed", "map-detail-panel-active", "detail-page-panel-open");
		const panel = document.getElementById("sidebarDetailPanel");
		if (panel) {
			panel.style.opacity = "0";
			panel.style.pointerEvents = "none";
			panel.style.visibility = "hidden";
		}
		const toggle = document.getElementById("mapPanelToggle");
		if (toggle) toggle.hidden = true;
	}

	function toggleAnalysisFlyout()
	{
		const sideNav = getSideNav();
		if (!sideNav) return;
		if (!requireSideNavLogin("로그인 후 입지 분석을 이용할 수 있습니다.", "입지분석")) return;
		if (typeof window.realjejuGoHome === "function") window.realjejuGoHome({ resetDetail: false });
		closeSideAccountMenu();
		const trigger = sideNav.querySelector('[data-side-nav-action="analysis"]');
		const flyout = document.getElementById("realjejuSideAnalysisMenu");
		if (!trigger || !flyout) return;
		const arrow = trigger.querySelector(".realjeju-side-nav-arrow");
		const willOpen = !flyout.classList.contains("open");
		trigger.classList.toggle("is-open", willOpen);
		trigger.setAttribute("aria-expanded", willOpen ? "true" : "false");
		if (arrow) {
			arrow.classList.toggle("fa-chevron-down", !willOpen);
			arrow.classList.toggle("fa-chevron-up", willOpen);
		}
		flyout.classList.toggle("open", willOpen);
		flyout.setAttribute("aria-hidden", willOpen ? "false" : "true");
		syncSideNavLifeSafety();
		setTimeout(syncSideNavActive, 0);
	}

	function toggleSideAccountMenu()
	{
		closeAnalysisFlyout();
		const sideNav = getSideNav();
		const user = window.realjejuCurrentAuthUser || null;
		const isLoggedIn = !!(user && user.id);
		if (isLoggedIn) {
			if (!isSideAccountAccordionViewport()) {
				closeSideAccountMenu();
				if (navigateSideNavRoute("/mypage/profile")) return;
				if (typeof window.realjejuOpenDedicatedMyInfo === "function") window.realjejuOpenDedicatedMyInfo();
				else if (typeof window.openMySuitePage === "function") window.openMySuitePage("myinfo");
				return;
			}
			const trigger = document.getElementById("realjejuSideAccountTrigger");
			const menu = document.getElementById("realjejuSideAccountMenu");
			if (!trigger || !menu) return;
			const willOpen = !menu.classList.contains("open");
			const arrow = trigger.querySelector(".realjeju-side-account-arrow");
			trigger.classList.toggle("account-open", willOpen);
			if (arrow) {
				arrow.classList.add("fa-chevron-down");
				arrow.classList.remove("fa-chevron-up");
			}
				menu.classList.toggle("open", willOpen);
				menu.setAttribute("aria-hidden", willOpen ? "false" : "true");
				if (sideNav) sideNav.classList.toggle("account-menu-expanded", willOpen);
				if (willOpen && menu && typeof menu.scrollIntoView === "function") {
					requestAnimationFrame(() => {
						menu.scrollIntoView({ block: "nearest" });
					});
				}
				return;
		}
		if (typeof openAuthModal === "function") openAuthModal();
	}

	function openSideNavDestination(action)
	{
		closeAnalysisFlyout();
		closeSideAccountMenu();
		if (action === "home") {
			if (getSideNavAction() === "home") {
				if (typeof updateMapPanelToggleState === "function") updateMapPanelToggleState();
				if (typeof refreshMapLayout === "function") setTimeout(refreshMapLayout, 0);
				return;
			}
			const currentCategory = document.body && document.body.dataset ? document.body.dataset.globalCategory || "realestate" : "realestate";
			const categoryPaths = {
				realestate: "/properties",
				"local-business": "/companies",
				"part-time": "/jobs",
				"used-market": "/used",
				car: "/cars",
				meetup: "/meetups"
			};
			if (navigateSideNavRoute(categoryPaths[currentCategory] || "/properties")) return;
			const shouldRestoreCollapsedPanel = typeof restoreMapPanelsCollapsedOnHome !== "undefined" && restoreMapPanelsCollapsedOnHome;
			if (typeof window.realjejuGoHome === "function") window.realjejuGoHome({ resetDetail: !shouldRestoreCollapsedPanel, category: currentCategory });
			if (shouldRestoreCollapsedPanel && typeof restoreCollapsedMapPanelOnHome === "function") {
				setTimeout(restoreCollapsedMapPanelOnHome, 0);
			}
			return;
		}
		if (action === "favorites") {
			if (!requireSideNavLogin("로그인 후 관심 부동산을 이용할 수 있습니다.", "관심 부동산")) return;
			if (navigateSideNavRoute("/properties/favorites")) return;
			if (typeof window.openMySuitePage === "function") window.openMySuitePage("favorites");
			return;
		}
		if (action === "broker-home") {
			if (navigateSideNavRoute("/properties/broker")) return;
			if (typeof window.openBrokerHomePage === "function") window.openBrokerHomePage();
			return;
		}
		if (action === "register") {
			if (document.body && !isGlobalRealestateCategory(document.body.dataset.globalCategory)) return;
			if (navigateSideNavRoute("/properties/register")) return;
			if (typeof window.openPropertyRegisterPage === "function") window.openPropertyRegisterPage({ confirmExistingDraft: true });
			return;
		}
		if (action === "my-page") {
			if (navigateSideNavRoute("/mypage/profile")) return;
			if (typeof window.realjejuOpenDedicatedMyInfo === "function") window.realjejuOpenDedicatedMyInfo();
			else if (typeof window.openMySuitePage === "function") window.openMySuitePage("myinfo");
			return;
		}
			if (action === "admin") {
				if (navigateSideNavRoute("/admin/notices")) return;
				if (typeof window.closeBrokerHomePage === "function") window.closeBrokerHomePage();
				if (typeof window.closePropertyRegisterPage === "function") {
					window.closePropertyRegisterPage({
						suppressBrokerHomeReturn: true,
						suppressMapHomeReturn: true,
						suppressAdminListingsReturn: true,
						suppressMySuiteFavoritesReturn: true
					});
				}
				if (typeof window.openAdminPage === "function") window.openAdminPage();
				return;
			}
			if (action === "operator") {
				if (typeof window.closeBrokerHomePage === "function") window.closeBrokerHomePage();
				if (typeof window.closePropertyRegisterPage === "function") {
					window.closePropertyRegisterPage({
						suppressBrokerHomeReturn: true,
						suppressMapHomeReturn: true,
						suppressAdminListingsReturn: true,
						suppressMySuiteFavoritesReturn: true
					});
				}
				if (typeof window.openOperatorPage === "function") window.openOperatorPage();
				return;
			}
		if (action === "notice") {
			if (navigateSideNavRoute("/notices")) return;
			if (typeof window.openNoticePage === "function") window.openNoticePage();
		}
	}

	function bind()
	{
		const sideNav = getSideNav();
		if (!sideNav || sideNav.dataset.bound === "1") return;
		sideNav.dataset.bound = "1";
	sideNav.addEventListener("click", (event) => {
		const recentItem = event.target.closest(".realjeju-side-recent-item[data-recent-item-id], .realjeju-side-recent-item[data-recent-listing-id]");
		if (recentItem) {
			event.preventDefault();
			event.stopPropagation();
			const recentCategory = recentItem.getAttribute("data-recent-category") || "realestate";
			const recentItemId = recentItem.getAttribute("data-recent-item-id") || recentItem.getAttribute("data-recent-listing-id");
			const currentRecentCategory = getCurrentSideRecentCategory();
			void (async () => {
				try {
					const isMobileDrawer = typeof window.matchMedia === "function"
						&& window.matchMedia("(max-width: 850px)").matches;
					if (isMobileDrawer && typeof window.realjejuCloseMobileSideNavDrawer === "function") {
						window.realjejuCloseMobileSideNavDrawer();
						await new Promise((resolve) => window.requestAnimationFrame(resolve));
					}
					if (recentCategory !== currentRecentCategory) {
						await activateSideRecentCategory(recentCategory);
					}
					await openSideCategoryRecentItem(recentCategory, recentItemId);
				} catch (error) {
					console.error("최근 조회 항목 열기 실패:", error);
				}
			})();
			return;
		}

			const recentBlock = event.target.closest(".realjeju-side-recent");
			if (recentBlock) {
				event.preventDefault();
				event.stopPropagation();
				return;
			}

			const accountBtn = event.target.closest("#realjejuSideAccountTrigger");
			if (accountBtn) {
				event.preventDefault();
				event.stopPropagation();
				toggleSideAccountMenu();
				return;
			}

			const analysisBtn = event.target.closest("[data-side-nav-analysis]");
			if (analysisBtn) {
				event.preventDefault();
				event.stopPropagation();
				const action = analysisBtn.dataset.sideNavAnalysis || "";
				if (!requireSideNavLogin("로그인 후 입지 분석을 이용할 수 있습니다.", "입지분석")) {
					const sideCheckbox = document.getElementById("realjejuSideLifeSafetyCheck");
					const mainCheckbox = document.getElementById("lifeSafetyOverlayCheck");
					if (sideCheckbox) sideCheckbox.checked = false;
					if (mainCheckbox) mainCheckbox.checked = false;
					return;
				}
				const checkbox = document.getElementById("lifeSafetyOverlayCheck");
				if (action === "reset") {
					const sideCheckbox = document.getElementById("realjejuSideLifeSafetyCheck");
					if (checkbox) checkbox.checked = false;
					if (sideCheckbox) sideCheckbox.checked = false;
					if (typeof setLifeSafetyOverlayVisible === "function") setLifeSafetyOverlayVisible(false);
					closeAnalysisFlyout();
				}
				return;
			}

			const menuBtn = event.target.closest("[data-side-nav-action]");
			if (!menuBtn) return;
			event.preventDefault();
			event.stopPropagation();
			const action = menuBtn.dataset.sideNavAction || "";
			if (
				window.matchMedia("(max-width: 850px)").matches
				&& ["favorites", "broker-home", "presale", "notice", "admin", "register"].includes(action)
				&& typeof window.realjejuCloseMobileSideNavDrawer === "function"
			) {
				window.realjejuCloseMobileSideNavDrawer();
			}
			if (action === "analysis") {
				clearSideNavMapPanelState();
				toggleAnalysisFlyout();
				return;
			}
			if (action === "presale") {
				clearSideNavMapPanelState();
				closeAnalysisFlyout();
				closeSideAccountMenu();
				if (navigateSideNavRoute("/properties/presales")) {
					setTimeout(syncSideNavActive, 0);
					return;
				}
				if (typeof window.realjejuGoHome === "function") window.realjejuGoHome({ resetDetail: true, presale: true });
				setTimeout(syncSideNavActive, 0);
				return;
			}
			if (action === "home" && getSideNavAction() === "home") {
				openSideNavDestination(action);
				setTimeout(syncSideNavActive, 0);
				return;
			}
			clearSideNavMapPanelState();
			openSideNavDestination(action);
			setTimeout(syncSideNavActive, 0);
		});

		sideNav.addEventListener("change", (event) => {
			const checkbox = event.target.closest("[data-side-nav-life-safety-check]");
			if (!checkbox) return;
			event.stopPropagation();
			if (checkbox.checked && !requireSideNavLogin("로그인 후 입지 분석을 이용할 수 있습니다.", "입지분석")) {
				checkbox.checked = false;
				const mainCheckbox = document.getElementById("lifeSafetyOverlayCheck");
				if (mainCheckbox) mainCheckbox.checked = false;
				return;
			}
			const mainCheckbox = document.getElementById("lifeSafetyOverlayCheck");
			if (mainCheckbox) mainCheckbox.checked = !!checkbox.checked;
			if (typeof setLifeSafetyOverlayVisible === "function") setLifeSafetyOverlayVisible(!!checkbox.checked);
		});

		document.addEventListener("click", (event) => {
			if (!event.target.closest("#realjejuSideNav")) {
				closeAnalysisFlyout();
				if (!document.body.classList.contains("my-suite-page-open")) closeSideAccountMenu();
			}
		}, true);

		new MutationObserver(syncSideNavActive).observe(document.body, {
			attributes: true,
			attributeFilter: ["class"]
		});
		const topbarTrigger = document.getElementById("detailAuthTrigger") || document.querySelector(".global-auth-trigger");
		if (topbarTrigger) {
			new MutationObserver(syncSideNavAccount).observe(topbarTrigger, {
				attributes: true,
				childList: true,
				subtree: true
			});
		}
		syncSideNavActive();
		syncSideNavVisibility();
		syncSideNavAccount();
		syncSideNavLifeSafety();
		window.realjejuSyncSideNavAccount = syncSideNavAccount;
		window.realjejuSyncSideNavVisibility = syncSideNavVisibility;
		window.realjejuCloseSideAccountMenu = closeSideAccountMenu;
		window.realjejuOpenSideAccountMenuForMySuite = openSideAccountMenuForMySuite;
	}

	if (document.readyState === "loading") {
		document.addEventListener("DOMContentLoaded", bind);
	} else {
		bind();
	}

	window.syncRealjejuSideNavActive = syncSideNavActive;
	window.syncRealjejuSideNavAccount = syncSideNavAccount;
	window.syncRealjejuSideNavVisibility = syncSideNavVisibility;
})();

(function bindPropertyDetailDescriptionCounter()
{
	const textarea = document.getElementById("propertyDetailDescriptionInput");
	const counter = document.getElementById("propertyDetailDescriptionCount");
	if (!textarea || !counter) return;

	const update = () => {
		if (textarea.value.length > 5000) textarea.value = textarea.value.slice(0, 5000);
		counter.textContent = textarea.value.length + "/5000";
	};

	textarea.addEventListener("input", update);
	update();
})();

(function bindPropertyAgencyMemoCounter()
{
	const textarea = document.getElementById("propertyAgencyMemoInput");
	const counter = document.getElementById("propertyAgencyMemoCount");
	const maxLength = 500;
	if (!textarea || !counter) return;

	const update = () => {
		if (textarea.value.length > maxLength) textarea.value = textarea.value.slice(0, maxLength);
		counter.textContent = textarea.value.length + "/" + maxLength;
	};

	textarea.addEventListener("input", update);
	update();
})();

(function bindRegistrantLicensedAgentToggle()
{
	const chk = document.getElementById("registrantLicensedAgentChk");
	const manager = document.getElementById("registrantManagerNameInput");
	const phone = document.getElementById("registrantPhone2Input");
	if (!chk || !manager || !phone) return;

	function toggle()
	{
		const enabled = chk.checked;
		[manager, phone].forEach((input) => {
			input.disabled = !enabled;
			if (!enabled) input.value = "";
		});
	}

	chk.addEventListener("change", toggle);
	toggle();
})();

document.documentElement.style.setProperty("--brand", BRAND_HEX);

function getPropertyBadgeStyleStorageKey(userId)
{
	const id = String(userId || "").trim();
	return id ? `${PROPERTY_BADGE_STYLE_STORAGE_PREFIX}${id}` : "";
}

function readCachedPropertyBadgeStyle(userId)
{
	const key = getPropertyBadgeStyleStorageKey(userId);
	if (!key) return null;
	try {
		const parsed = JSON.parse(localStorage.getItem(key) || "null");
		if (!parsed || typeof parsed !== "object") return null;
		const usesLegacyBorderDefault = PROPERTY_BADGE_OBSOLETE_BORDER_COLORS.has(
			String(parsed.borderColor || "").trim().toUpperCase()
		);
		return {
			color: normalizePropertyBadgeStyleColor(parsed.color),
			textColor: normalizePropertyBadgeTextColor(parsed.textColor),
			textOpacity: normalizePropertyBadgeTextOpacity(parsed.textOpacity),
			borderColor: usesLegacyBorderDefault ? PROPERTY_BADGE_STYLE_DEFAULT.borderColor : normalizePropertyBadgeBorderColor(parsed.borderColor),
			borderOpacity: usesLegacyBorderDefault ? PROPERTY_BADGE_STYLE_DEFAULT.borderOpacity : normalizePropertyBadgeBorderOpacity(parsed.borderOpacity),
			opacity: normalizePropertyBadgeStyleOpacity(parsed.opacity)
		};
	} catch (err) {
		return null;
	}
}

function writeCachedPropertyBadgeStyle(userId, style)
{
	const key = getPropertyBadgeStyleStorageKey(userId);
	if (!key) return;
	try {
		localStorage.setItem(key, JSON.stringify({
			color: normalizePropertyBadgeStyleColor(style && style.color),
			textColor: normalizePropertyBadgeTextColor(style && style.textColor),
			textOpacity: normalizePropertyBadgeTextOpacity(style && style.textOpacity),
			borderColor: normalizePropertyBadgeBorderColor(style && style.borderColor),
			borderOpacity: normalizePropertyBadgeBorderOpacity(style && style.borderOpacity),
			opacity: normalizePropertyBadgeStyleOpacity(style && style.opacity)
		}));
	} catch (err) {}
}

function applyPropertyBadgeStyle(style, options = {})
{
	const normalized = {
		color: normalizePropertyBadgeStyleColor(style && style.color),
		textColor: normalizePropertyBadgeTextColor(style && style.textColor),
		textOpacity: normalizePropertyBadgeTextOpacity(style && style.textOpacity),
		borderColor: normalizePropertyBadgeBorderColor(style && style.borderColor),
		borderOpacity: normalizePropertyBadgeBorderOpacity(style && style.borderOpacity),
		opacity: normalizePropertyBadgeStyleOpacity(style && style.opacity)
	};
	propertyBadgeStyleState.color = normalized.color;
	propertyBadgeStyleState.textColor = normalized.textColor;
	propertyBadgeStyleState.textOpacity = normalized.textOpacity;
	propertyBadgeStyleState.borderColor = normalized.borderColor;
	propertyBadgeStyleState.borderOpacity = normalized.borderOpacity;
	propertyBadgeStyleState.opacity = normalized.opacity;
	document.documentElement.style.setProperty("--property-badge-color", normalized.color);
	document.documentElement.style.setProperty("--property-badge-text-color", normalized.textColor);
	document.documentElement.style.setProperty("--property-badge-text-opacity", String(normalized.textOpacity));
	document.documentElement.style.setProperty("--property-badge-border-color", normalized.borderColor);
	document.documentElement.style.setProperty("--property-badge-border-opacity", String(normalized.borderOpacity));
	document.documentElement.style.setProperty("--property-badge-opacity", String(normalized.opacity));
	if (options.refresh !== false && typeof window.realjejuRefreshPropertyBadgeStyle === "function") {
		window.realjejuRefreshPropertyBadgeStyle();
	}
	return normalized;
}

function resetPropertyBadgeStyle(options = {})
{
	propertyBadgeStyleLoadSeq += 1;
	propertyBadgeStyleState = {
		userId: "",
		color: PROPERTY_BADGE_STYLE_DEFAULT.color,
		textColor: PROPERTY_BADGE_STYLE_DEFAULT.textColor,
		textOpacity: PROPERTY_BADGE_STYLE_DEFAULT.textOpacity,
		borderColor: PROPERTY_BADGE_STYLE_DEFAULT.borderColor,
		borderOpacity: PROPERTY_BADGE_STYLE_DEFAULT.borderOpacity,
		opacity: PROPERTY_BADGE_STYLE_DEFAULT.opacity,
		loaded: false
	};
	applyPropertyBadgeStyle(PROPERTY_BADGE_STYLE_DEFAULT, options);
}

async function syncPropertyBadgeStyleForUser(user, options = {})
{
	const userId = String(user && user.id || "").trim();
	if (!userId) {
		resetPropertyBadgeStyle(options);
		return getPropertyBadgeStyle();
	}
	if (propertyBadgeStyleState.userId === userId && propertyBadgeStyleState.loaded && options.force !== true) {
		return getPropertyBadgeStyle();
	}

	const requestSeq = ++propertyBadgeStyleLoadSeq;
	propertyBadgeStyleState.userId = userId;
	propertyBadgeStyleState.loaded = false;
	const cached = readCachedPropertyBadgeStyle(userId);
	applyPropertyBadgeStyle(cached || PROPERTY_BADGE_STYLE_DEFAULT, options);

	const client = typeof window.getRealjejuSupabaseClient === "function"
		? window.getRealjejuSupabaseClient()
		: null;
	if (!client) {
		// 인증 세션이 Supabase 클라이언트 공개보다 먼저 복원될 수 있습니다.
		// 이때 완료 처리하지 않고, 클라이언트 공개 직후 서버 원본을 다시 읽습니다.
		propertyBadgeStyleState.loaded = false;
		return getPropertyBadgeStyle();
	}

	try {
		const { data, error } = await client
			.from("property_badge_preferences")
			.select("badge_color, badge_opacity")
			.eq("user_id", userId)
			.maybeSingle();
		if (error) throw error;
		if (requestSeq !== propertyBadgeStyleLoadSeq || propertyBadgeStyleState.userId !== userId) {
			return getPropertyBadgeStyle();
		}
		const serverStyle = data
			? {
				color: data.badge_color,
				textColor: cached && cached.textColor,
				textOpacity: cached && cached.textOpacity,
				borderColor: cached && cached.borderColor,
				borderOpacity: cached && cached.borderOpacity,
				opacity: data.badge_opacity
			}
			: {
				...PROPERTY_BADGE_STYLE_DEFAULT,
				textColor: cached && cached.textColor,
				textOpacity: cached && cached.textOpacity,
				borderColor: cached && cached.borderColor,
				borderOpacity: cached && cached.borderOpacity
			};
		const normalized = applyPropertyBadgeStyle(serverStyle, options);
		writeCachedPropertyBadgeStyle(userId, normalized);
		propertyBadgeStyleState.loaded = true;
		return normalized;
	} catch (error) {
		if (requestSeq === propertyBadgeStyleLoadSeq && propertyBadgeStyleState.userId === userId) {
			propertyBadgeStyleState.loaded = true;
		}
		console.warn("원형 매물 뱃지 설정 조회 실패:", error);
		return getPropertyBadgeStyle();
	}
}

async function savePropertyBadgeStyleForCurrentUser(style)
{
	const user = typeof getBrokerMapCurrentUser === "function"
		? getBrokerMapCurrentUser()
		: (window.realjejuCurrentAuthUser || null);
	const userId = String(user && user.id || "").trim();
	if (!userId) throw new Error("로그인 후 색상을 저장할 수 있습니다.");

	const previous = getPropertyBadgeStyle();
	const normalized = applyPropertyBadgeStyle(style);
	writeCachedPropertyBadgeStyle(userId, normalized);
	propertyBadgeStyleState.userId = userId;

	const client = typeof window.getRealjejuSupabaseClient === "function"
		? window.getRealjejuSupabaseClient()
		: null;
	if (!client) {
		applyPropertyBadgeStyle(previous);
		writeCachedPropertyBadgeStyle(userId, previous);
		throw new Error("설정을 저장할 수 없습니다. 잠시 후 다시 시도해 주세요.");
	}

	const { error } = await client
		.from("property_badge_preferences")
		.upsert({
			user_id: userId,
			badge_color: normalized.color,
			badge_opacity: normalized.opacity,
			updated_at: new Date().toISOString()
		}, { onConflict: "user_id" });
	if (error) {
		applyPropertyBadgeStyle(previous);
		writeCachedPropertyBadgeStyle(userId, previous);
		throw error;
	}
	propertyBadgeStyleState.loaded = true;
	return normalized;
}

function getAdminBoundaryStyleStorageKey(userId)
{
	const id = String(userId || "").trim() || "guest";
	return ADMIN_BOUNDARY_STYLE_STORAGE_PREFIX + id;
}

function readCachedAdminBoundaryStyle(userId)
{
	try {
		const parsed = JSON.parse(localStorage.getItem(getAdminBoundaryStyleStorageKey(userId)) || "null");
		if (!parsed || typeof parsed !== "object") return null;
		const cachedColor = String(parsed.color || "").trim().toUpperCase();
		const cachedOpacity = normalizeAdminBoundaryStyleOpacity(parsed.opacity);
		if (cachedColor === "#10B981" && Math.abs(cachedOpacity - 0.15) < 0.001) {
			return { ...ADMIN_BOUNDARY_STYLE_DEFAULT };
		}
		if (
			(cachedColor === "#00B8D9" || cachedColor === "#2563EB")
			&& Math.abs(cachedOpacity - 0.10) < 0.001
		) {
			return { ...ADMIN_BOUNDARY_STYLE_DEFAULT };
		}
		if (cachedColor === "#2563EB" && Math.abs(cachedOpacity - 0.30) < 0.001) {
			return { ...ADMIN_BOUNDARY_STYLE_DEFAULT };
		}
		return {
			color: normalizeAdminBoundaryStyleColor(parsed.color),
			opacity: normalizeAdminBoundaryStyleOpacity(parsed.opacity)
		};
	} catch (error) {
		return null;
	}
}

function writeCachedAdminBoundaryStyle(userId, style)
{
	try {
		localStorage.setItem(getAdminBoundaryStyleStorageKey(userId), JSON.stringify({
			color: normalizeAdminBoundaryStyleColor(style && style.color),
			opacity: normalizeAdminBoundaryStyleOpacity(style && style.opacity)
		}));
	} catch (error) {}
}

function applyAdminBoundaryStyle(style, options = {})
{
	const normalized = {
		color: normalizeAdminBoundaryStyleColor(style && style.color),
		opacity: normalizeAdminBoundaryStyleOpacity(style && style.opacity)
	};
	adminBoundaryStyleState.color = normalized.color;
	adminBoundaryStyleState.opacity = normalized.opacity;
	document.documentElement.style.setProperty("--admin-boundary-color", normalized.color);
	document.documentElement.style.setProperty("--admin-boundary-opacity", String(normalized.opacity));
	if (options.refresh !== false && typeof renderAdminBoundaryOverlay === "function") {
		Promise.resolve().then(() => renderAdminBoundaryOverlay());
	}
	if (options.refresh !== false
		&& typeof window.getParcelBoundaryInfo === "function"
		&& window.getParcelBoundaryInfo()
		&& typeof renderParcelBoundaryOverlay === "function") {
		Promise.resolve().then(() => renderParcelBoundaryOverlay(window.getParcelBoundaryInfo()));
	}
	return normalized;
}

function syncAdminBoundaryStyleForUser(user, options = {})
{
	const userId = String(user && user.id || "").trim();
	if (adminBoundaryStyleState.userId === userId && adminBoundaryStyleState.loaded && options.force !== true) {
		return getAdminBoundaryStylePreference();
	}
	adminBoundaryStyleState.userId = userId;
	adminBoundaryStyleState.loaded = true;
	return applyAdminBoundaryStyle(readCachedAdminBoundaryStyle(userId) || ADMIN_BOUNDARY_STYLE_DEFAULT, options);
}

async function saveAdminBoundaryStyleForCurrentUser(style)
{
	const user = typeof getBrokerMapCurrentUser === "function"
		? getBrokerMapCurrentUser()
		: (window.realjejuCurrentAuthUser || null);
	const userId = String(user && user.id || "").trim();
	const normalized = applyAdminBoundaryStyle(style);
	writeCachedAdminBoundaryStyle(userId, normalized);
	adminBoundaryStyleState.userId = userId;
	adminBoundaryStyleState.loaded = true;
	return normalized;
}

window.realjejuSyncPropertyBadgeStyleForUser = syncPropertyBadgeStyleForUser;

window.realjejuResetPropertyBadgeStyle = resetPropertyBadgeStyle;

window.realjejuSyncAdminBoundaryStyleForUser = syncAdminBoundaryStyleForUser;

applyAdminBoundaryStyle(ADMIN_BOUNDARY_STYLE_DEFAULT, { refresh: false });

function showRealjejuStandalonePageTransitionCover()
{
	if (typeof document === "undefined" || !document.body || !document.body.classList) return;
	if (realjejuStandalonePageTransitionCoverFrame && typeof window !== "undefined" && window.cancelAnimationFrame) {
		window.cancelAnimationFrame(realjejuStandalonePageTransitionCoverFrame);
		realjejuStandalonePageTransitionCoverFrame = 0;
	}
	document.body.classList.add("realjeju-standalone-page-transition-cover");
}

function releaseRealjejuStandalonePageTransitionCover()
{
	if (typeof document === "undefined" || !document.body || !document.body.classList) return;
	if (realjejuStandalonePageTransitionCoverFrame && typeof window !== "undefined" && window.cancelAnimationFrame) {
		window.cancelAnimationFrame(realjejuStandalonePageTransitionCoverFrame);
	}
	if (typeof window === "undefined" || !window.requestAnimationFrame) {
		document.body.classList.remove("realjeju-standalone-page-transition-cover");
		realjejuStandalonePageTransitionCoverFrame = 0;
		return;
	}
	realjejuStandalonePageTransitionCoverFrame = window.requestAnimationFrame(() => {
		realjejuStandalonePageTransitionCoverFrame = window.requestAnimationFrame(() => {
			realjejuStandalonePageTransitionCoverFrame = 0;
			document.body?.classList?.remove("realjeju-standalone-page-transition-cover");
		});
	});
}

if (typeof window !== "undefined") {
	window.realjejuShowStandalonePageTransitionCover = showRealjejuStandalonePageTransitionCover;
	window.realjejuReleaseStandalonePageTransitionCover = releaseRealjejuStandalonePageTransitionCover;
}

async function syncRealjejuBrokerOfficeProfileImage(client, userId, profileImage)
{
	const normalizedUserId = normalizeItemId(userId);
	const imageUrl = String(profileImage || "").trim();
	if (!client || !normalizedUserId || !imageUrl) return;
	if (typeof brokerOfficeLatestProfileImagePromiseByUserId !== "undefined") {
		brokerOfficeLatestProfileImagePromiseByUserId.delete(normalizedUserId);
	}
	try {
		const { error } = await client
			.from("broker_office_locations")
			.update({
				profile_image: imageUrl,
				updated_at: new Date().toISOString()
			})
			.eq("user_id", normalizedUserId);
		if (error) console.warn("중개사무소 프로필 사진 동기화 실패:", error);
	} catch (error) {
		console.warn("중개사무소 프로필 사진 동기화 오류:", error);
	}
	if (typeof state !== "undefined" && state && Array.isArray(state.brokerOfficeRows)) {
		state.brokerOfficeRows = state.brokerOfficeRows.map((office) => (
			normalizeItemId(office && (office.userId || office.user_id)) === normalizedUserId
				? { ...office, profileImage: imageUrl, profile_image: imageUrl }
				: office
		));
	}
	if (typeof window !== "undefined"
		&& window.realjejuCurrentBrokerOffice
		&& normalizeItemId(window.realjejuCurrentBrokerOffice.user_id || window.realjejuCurrentBrokerOffice.userId) === normalizedUserId) {
		window.realjejuCurrentBrokerOffice = {
			...window.realjejuCurrentBrokerOffice,
			profileImage: imageUrl,
			profile_image: imageUrl
		};
	}
}

async function saveRealjejuOwnProfile(client, userId, profilePayload)
{
	if (!client || !userId || !profilePayload) return { error: new Error("profile save context missing") };
	const requestedProfileImage = String(profilePayload.profile_image || "").trim();
	const updatePayload = { ...profilePayload };
	delete updatePayload.id;
	let result = await client.from("profiles").update(updatePayload).eq("id", userId).select("id").maybeSingle();
	if (result && !result.error && result.data && result.data.id) {
		if (requestedProfileImage) await syncRealjejuBrokerOfficeProfileImage(client, userId, requestedProfileImage);
		return result;
	}
	if (result && result.error && /profile_image/i.test(String(result.error.message || ""))) {
		delete updatePayload.profile_image;
		delete profilePayload.profile_image;
		result = await client.from("profiles").update(updatePayload).eq("id", userId).select("id").maybeSingle();
		if (result && !result.error && result.data && result.data.id) {
			if (requestedProfileImage) await syncRealjejuBrokerOfficeProfileImage(client, userId, requestedProfileImage);
			return result;
		}
	}
	result = await client.from("profiles").insert(profilePayload).select("id").maybeSingle();
	if (result && !result.error && result.data && result.data.id && requestedProfileImage) {
		await syncRealjejuBrokerOfficeProfileImage(client, userId, requestedProfileImage);
	}
	return result;
}

if (typeof window !== "undefined") window.realjejuSaveOwnProfile = saveRealjejuOwnProfile;

function normalizeRealjejuSharedPhone(value)
{
	return String(value || "").replace(/[^0-9]/g, "");
}

function isValidRealjejuMobilePhone(value)
{
	return /^010\d{8}$/.test(normalizeRealjejuSharedPhone(value));
}

function isValidRealjejuOfficePhone(value)
{
	const phone = normalizeRealjejuSharedPhone(value);
	if (/^010\d{8}$/.test(phone)) return true;
	if (/^02\d{7,8}$/.test(phone)) return true;
	return /^(031|032|033|041|042|043|044|051|052|053|054|055|061|062|063|064)\d{7,8}$/.test(phone);
}

function isValidRealjejuBrokerOfficeEmail(value)
{
	return /^[^\s@]+@[^\s@]+$/.test(String(value || "").trim());
}

function isValidRealjejuKakaoOpenChatUrl(value)
{
	const url = String(value || "").trim();
	return !url || /^https?:\/\/\S+$/i.test(url);
}

function getRealjejuErrorText(error)
{
	return [error && error.code, error && error.message, error && error.details, error && error.hint]
		.map((value) => String(value || ""))
		.join(" ");
}

function isRealjejuKakaoUrlColumnError(error)
{
	return /kakao_url/i.test(getRealjejuErrorText(error)) && /(42703|schema cache|column|could not find)/i.test(getRealjejuErrorText(error));
}

function isRealjejuMissingKakaoRpcError(error)
{
	return /save_my_agency_kakao_url|save_my_agency_profile|PGRST202|schema cache|function/i.test(getRealjejuErrorText(error));
}

function isRealjejuAgencyNotFoundError(error)
{
	return /P0002|agency not found/i.test(getRealjejuErrorText(error));
}

async function saveRealjejuAgencyProfile(client, agencyId, payload)
{
	if (!client) throw new Error("Supabase client missing");
	const params = {
		p_agency_id: agencyId ? String(agencyId) : null,
		p_office_name: String(payload && payload.office_name || "").trim(),
		p_owner_name: String(payload && payload.owner_name || "").trim(),
		p_office_reg_no: normalizeBrokerOfficeRegNo(payload && payload.office_reg_no),
		p_office_address: String(payload && payload.office_address || "").trim(),
		p_phone: String(payload && payload.phone || "").trim(),
		p_email: String(payload && payload.email || "").trim(),
		p_kakao_url: String(payload && payload.kakao_url || "").trim()
	};
	const { data, error } = await client.rpc("save_my_agency_profile", params);
	if (error) throw error;
	const row = Array.isArray(data) ? data[0] : data;
	if (!row || !row.id) throw new Error("중개사무소 정보 저장 확인 실패");
	return row;
}

if (typeof window !== "undefined") {
	window.realjejuIsValidMobilePhone = isValidRealjejuMobilePhone;
	window.realjejuIsValidOfficePhone = isValidRealjejuOfficePhone;
}

async function syncRealjejuManagementVersionListingCount()
{
	if (!shouldShowRealjejuTopbarVersionStats()) return;
	if (Number.isFinite(realjejuManagementVersionListingCount)) {
		updateRealjejuTopbarVersionText();
		return realjejuManagementVersionListingCount;
	}
	if (realjejuManagementVersionListingCountPromise) return realjejuManagementVersionListingCountPromise;
	realjejuManagementVersionListingCountPromise = (async () => {
		try {
			if (typeof loadPropertyRegionManagementCountRows !== "function") return null;
			await loadPropertyRegionManagementCountRows();
			if (!Array.isArray(propertyRegionManagementCountRowsCache)) return null;
			// 4.938: 관리자 페이지에서는 방금 읽은 관리자 전체 메타데이터가 최종 기준입니다.
			// 먼저 시작된 60초 지역 집계 요청이 늦게 끝나 관리자 전체 숫자를 다시 덮지 않게 합니다.
			const isAdminPageOpen = !!(document.body && document.body.classList.contains("admin-page-open"));
			if (!isAdminPageOpen) {
				realjejuManagementVersionListingCount = propertyRegionManagementCountRowsCache.length;
				updateRealjejuTopbarVersionText();
			}
			return realjejuManagementVersionListingCount;
		} catch (error) {
			console.warn("관리자·운영자 매물 수 표시 실패:", error);
			return null;
		} finally {
			realjejuManagementVersionListingCountPromise = null;
		}
	})();
	return realjejuManagementVersionListingCountPromise;
}

function applyRealjejuVisitStats(row)
{
	const uniqueIpCount = Number(row && row.unique_ip_count);
	const totalVisitCount = Number(row && row.total_visit_count);
	if (!Number.isFinite(uniqueIpCount) || !Number.isFinite(totalVisitCount)) return;
	realjejuTopbarVersionStatsText = APP_VERSION + "(" + Math.max(0, Math.trunc(uniqueIpCount)).toLocaleString("ko-KR") + "," + Math.max(0, Math.trunc(totalVisitCount)).toLocaleString("ko-KR") + ")";
	updateRealjejuTopbarVersionText();
	if (shouldShowRealjejuTopbarVersionStats()) void syncRealjejuManagementVersionListingCount();
}

async function syncRealjejuSiteVisitStats()
{
	if (realjejuSiteVisitStatsRequested) return;
	realjejuSiteVisitStatsRequested = true;
	updateRealjejuTopbarVersionText();
	if (typeof shouldLoadRealjejuRemotePageData === "function" && !shouldLoadRealjejuRemotePageData("site-visit")) return;
	try {
		if (typeof loadSupabaseScript === "function") await loadSupabaseScript();
		const client = typeof window.getRealjejuSupabaseClient === "function" ? window.getRealjejuSupabaseClient() : null;
		if (!client || typeof client.rpc !== "function") return;
		const { data, error } = await client.rpc("record_site_visit");
		if (error) throw error;
		const row = Array.isArray(data) ? data[0] : data;
		applyRealjejuVisitStats(row);
	} catch (error) {
		console.warn("방문 통계 표시 실패:", error);
	}
}

window.realjejuGetTopbarVersionText = getRealjejuTopbarVersionText;

window.realjejuUpdateTopbarVersionText = updateRealjejuTopbarVersionText;

window.realjejuSyncManagementVersionListingCount = syncRealjejuManagementVersionListingCount;

function scheduleRealjejuSiteVisitStats()
{
	const run = () => syncRealjejuSiteVisitStats();
	if (typeof window.requestIdleCallback === "function") {
		window.requestIdleCallback(run, { timeout: 4000 });
		return;
	}
	window.setTimeout(run, 2500);
}

if (document.readyState === "loading") {
	document.addEventListener("DOMContentLoaded", scheduleRealjejuSiteVisitStats, { once: true });
} else {
	scheduleRealjejuSiteVisitStats();
}

function findRealjejuPropertyTypeOption(select, ...values)
{
	if (!select) return null;
	const wrap = select.closest("[data-register-dropdown]");
	const optionNodes = wrap
		? Array.from(wrap.querySelectorAll(".property-register-dropdown-option[data-value]"))
		: Array.from(select.options || []);
	const options = optionNodes
		.map((option) => ({
			node: option,
			value: String(option.dataset?.value || option.value || "").trim(),
			text: String(option.textContent || "").trim()
		}))
		.filter((option) => option.value);
	if (!options.length) return null;
	for (const raw of values) {
		const text = String(raw || "").trim();
		if (!text) continue;
		const exactValue = options.find((option) => option.value === text);
		if (exactValue) return exactValue.node;
		const exactText = options.find((option) => option.text.replace(/\s+/g, " ").trim() === text.replace(/\s+/g, " ").trim());
		if (exactText) return exactText.node;
		const alias = resolveRealjejuPropertyTypeValue(text);
		if (alias) {
			const aliasOption = options.find((option) => option.value === alias);
			if (aliasOption) return aliasOption.node;
		}
		const textKey = normalizeRealjejuPropertyTypeKey(text);
		const containsText = options.find((option) => {
			const optionKey = normalizeRealjejuPropertyTypeKey(option.text);
			return textKey && optionKey && (textKey.includes(optionKey) || optionKey.includes(textKey));
		});
		if (containsText) return containsText.node;
	}
	return null;
}

function syncRealjejuPropertyTypeSelect(select, ...values)
{
	if (!select) return "";
	const wrap = select.closest("[data-register-dropdown]");
	const label = wrap?.querySelector("[data-register-dropdown-label]");
	const activeOption = wrap?.querySelector(".property-register-dropdown-option.active[data-value], .property-register-dropdown-option[aria-selected='true'][data-value]");
	const option = findRealjejuPropertyTypeOption(
		select,
		...values,
		select.value,
		select.dataset.selectedValue,
		select.dataset.lastValue,
		wrap?.dataset.selectedValue,
		activeOption?.dataset?.value,
		activeOption?.textContent,
		label?.textContent
	);
	if (!option) {
		select.value = "";
		select.dataset.selectedValue = "";
		select.dataset.lastValue = "";
		if (wrap) wrap.dataset.selectedValue = "";
		return "";
	}
	const value = String(option.dataset?.value || option.value || "").trim();
	if (!value) return "";
	select.value = value;
	select.dataset.selectedValue = value;
	select.dataset.lastValue = value;
	if (wrap) {
		wrap.dataset.selectedValue = value;
		if (label) label.textContent = String(option.textContent || "").trim();
		wrap.querySelectorAll(".property-register-dropdown-option[data-value]").forEach((btn) => {
			const isActive = String(btn.dataset.value || "").trim() === value;
			btn.classList.toggle("active", isActive);
			btn.setAttribute("aria-selected", isActive ? "true" : "false");
		});
	}
	return value;
}

function resolvePropertyRegisterTypeValue(select, ...values)
{
	if (!select) return "";
	const wrap = select.closest("[data-register-dropdown]");
	const label = wrap?.querySelector("[data-register-dropdown-label]");
	const activeOption = wrap?.querySelector(".property-register-dropdown-option.active[data-value], .property-register-dropdown-option[aria-selected='true'][data-value]");
	const selectedOption = select.options && select.selectedIndex >= 0 ? select.options[select.selectedIndex] : null;
	const option = findRealjejuPropertyTypeOption(
		select,
		...values,
		select.value,
		select.dataset.selectedValue,
		select.dataset.lastValue,
		wrap?.dataset.selectedValue,
		activeOption?.dataset?.value,
		activeOption?.textContent,
		selectedOption?.value,
		selectedOption?.textContent,
		label?.textContent
	);
	if (!option) return "";
	return syncRealjejuPropertyTypeSelect(select, option.dataset?.value || option.value || option.textContent || "");
}

function getPropertyRegisterTypeDebugText(select)
{
	if (!select) return "";
	const wrap = select.closest("[data-register-dropdown]");
	const label = wrap?.querySelector("[data-register-dropdown-label]");
	const activeOption = wrap?.querySelector(".property-register-dropdown-option.active[data-value], .property-register-dropdown-option[aria-selected='true'][data-value]");
	const selectedOption = select.options && select.selectedIndex >= 0 ? select.options[select.selectedIndex] : null;
	return [
		select.value,
		select.dataset.selectedValue,
		select.dataset.lastValue,
		wrap?.dataset.selectedValue,
		activeOption?.dataset?.value,
		activeOption?.textContent,
		selectedOption?.value,
		selectedOption?.textContent,
		label?.textContent
	].map((value) => String(value || "").trim()).filter(Boolean).join(" / ");
}

function isRealjejuExpiredTrashDate(value)
{
	if (!value) return false;
	const time = new Date(value).getTime();
	return Number.isFinite(time) && time <= Date.now() - REALJEJU_TRASH_RETENTION_MS;
}

function isRealjejuPrimaryBrokerHomeRole(role)
{
	const value = String(role || "").trim().toLowerCase();
	return value === "agent" || value === "corporation" || value === "대표 공인중개사" || value === "법인";
}

function isRealjejuManagementAccount(user, profile)
{
	const data = profile && typeof profile === "object" ? profile : {};
	const roles = [
		data.role,
		data.app_role,
		data.user_role,
		data.role_request,
		user && user.app_metadata && user.app_metadata.role,
		user && user.user_metadata && user.user_metadata.role
	].map((value) => String(value || "").trim().toLowerCase());
	return roles.some((role) => ["admin", "operator", "operations", "관리자", "운영자"].includes(role))
		|| data.is_admin === true
		|| data.admin === true
		|| data.is_operator === true
		|| data.operator === true;
}

function canRealjejuUseBrokerHomeRole(user, profile)
{
	return isRealjejuPrimaryBrokerHomeRole(profile && profile.role_request)
		|| isRealjejuManagementAccount(user, profile);
}

function isBrokerOfficeRowOwnedByUser(row, user, profile = null)
{
	if (!row || !user || !user.id) return false;
	const rowUserId = String(row.user_id || "").trim();
	if (rowUserId && rowUserId === String(user.id)) return true;
	const rowEmail = String(row.email || "").trim().toLowerCase();
	const userEmail = String(user.email || "").trim().toLowerCase();
	const profileEmail = String(profile && profile.email || "").trim().toLowerCase();
	return !!rowEmail && (rowEmail === userEmail || rowEmail === profileEmail);
}

function pickCurrentRealjejuBrokerOffice(rows, user, profile = null)
{
	const visibleRows = (Array.isArray(rows) ? rows : []).filter((row) => {
		if (!row || row.deleted_at) return false;
		if (getBrokerOfficeRowStatus(row) === "deleted") return false;
		return isBrokerOfficeRowOwnedByUser(row, user, profile);
	});
	return visibleRows.find((row) => getBrokerOfficeRowStatus(row) === "active")
		|| visibleRows.find((row) => row && (row.owner_name || row.office_reg_no || row.office_address))
		|| visibleRows[0]
		|| null;
}

function getBrokerOfficeLookupEmail(user, profile)
{
	const candidates = [
		user && user.email,
		profile && profile.email,
		window.realjejuCurrentProfile && window.realjejuCurrentProfile.email
	];
	const found = candidates.find((value) => String(value || "").trim());
	return found ? String(found).trim().toLowerCase() : "";
}

function mergeBrokerOfficeRows(...rowSets)
{
	const merged = [];
	const seen = new Set();
	rowSets.flat().forEach((row) => {
		if (!row || typeof row !== "object") return;
		const key = String(row.id || `${row.user_id || ""}:${row.email || ""}:${row.office_name || ""}`).trim();
		if (key && seen.has(key)) return;
		if (key) seen.add(key);
		merged.push(row);
	});
	return merged;
}

async function fetchSharedBrokerOfficeRows(client, user, profile)
{
	if (!client || !user || !user.id) return [];
	if (typeof shouldLoadRealjejuRemotePageData === "function" && !shouldLoadRealjejuRemotePageData("agencies")) return [];
	const email = getBrokerOfficeLookupEmail(user, profile);
	const cacheKey = `${String(user.id)}|${email}`;
	const cached = brokerOfficeRowsCache.get(cacheKey);
	if (cached && Date.now() - cached.time < BROKER_OFFICE_LOOKUP_CACHE_MS) return cached.rows;
	if (brokerOfficeRowsInflight.has(cacheKey)) return brokerOfficeRowsInflight.get(cacheKey);

	const promise = (async () => {
		let userRows = [];
		let emailRows = [];
		try {
			const { data, error } = await client
				.from("agencies")
				.select("*")
				.eq("user_id", user.id)
				.order("updated_at", { ascending: false })
				.order("created_at", { ascending: false })
				.limit(10);
			if (error) throw error;
			userRows = Array.isArray(data) ? data : [];
		} catch (err) {
			console.warn("중개사무소 user_id 조회 실패:", err);
		}
		if (email) {
			try {
				const { data, error } = await client
					.from("agencies")
					.select("*")
					.eq("email", email)
					.order("updated_at", { ascending: false })
					.order("created_at", { ascending: false })
					.limit(10);
				if (error) throw error;
				emailRows = Array.isArray(data) ? data : [];
			} catch (err) {
				console.warn("중개사무소 email 조회 실패:", err);
			}
		}

			const safeEmailRows = emailRows.filter((row) => {
				if (isBrokerOfficeRowOwnedByUser(row, user, profile)) return true;
				if (String(row && row.user_id || "").trim()) return false;
				return getBrokerOfficeRowStatus(row) !== "active";
			});
			const rows = mergeBrokerOfficeRows(userRows, safeEmailRows);
			brokerOfficeRowsCache.set(cacheKey, { time: Date.now(), rows });
			return rows;
		})().finally(() => {
		brokerOfficeRowsInflight.delete(cacheKey);
	});

	brokerOfficeRowsInflight.set(cacheKey, promise);
	return promise;
}

