function applyAppVersion()
{
	const path = String(arguments.length ? arguments[0] : (window.location && window.location.pathname) || "/").toLowerCase().replace(/\/+$/, "") || "/";
	let metaPath = path;
	if (/^\/properties(?:\/|$)/.test(path)) metaPath = "/properties";
	else if (/^\/companies(?:\/|$)/.test(path)) metaPath = "/companies";
	else if (/^\/jobs(?:\/|$)/.test(path)) metaPath = "/jobs";
	else if (/^\/cars(?:\/|$)/.test(path)) metaPath = "/cars";
	else if (/^\/notices(?:\/|$)/.test(path)) metaPath = "/notices";
	else if (!REALJEJU_ROUTE_SEO_META[metaPath]) metaPath = "/";
	const seoMeta = REALJEJU_ROUTE_SEO_META[metaPath] || REALJEJU_ROUTE_SEO_META["/"];
	document.title = seoMeta.title;

	const descriptionMeta = document.getElementById("descriptionMeta") || document.querySelector('meta[name="description"]');
	if (descriptionMeta) descriptionMeta.setAttribute("content", seoMeta.description);

	const canonicalLink = document.getElementById("canonicalLink") || document.querySelector('link[rel="canonical"]');
	if (canonicalLink) canonicalLink.setAttribute("href", seoMeta.url);

	const ogTitleMeta = document.getElementById("ogTitleMeta");
	if (ogTitleMeta) ogTitleMeta.setAttribute("content", seoMeta.title);

	const ogDescriptionMeta = document.getElementById("ogDescriptionMeta");
	if (ogDescriptionMeta) ogDescriptionMeta.setAttribute("content", seoMeta.description);

	const ogUrlMeta = document.getElementById("ogUrlMeta") || document.querySelector('meta[property="og:url"]');
	if (ogUrlMeta) ogUrlMeta.setAttribute("content", seoMeta.url);

	const twitterTitleMeta = document.querySelector('meta[name="twitter:title"]');
	if (twitterTitleMeta) twitterTitleMeta.setAttribute("content", seoMeta.title);

	const twitterDescriptionMeta = document.querySelector('meta[name="twitter:description"]');
	if (twitterDescriptionMeta) twitterDescriptionMeta.setAttribute("content", seoMeta.description);
}

applyAppVersion();

