function parseRecentViewedListings(raw)
{
	try {
		const parsed = JSON.parse(String(raw || ""));
		if (!Array.isArray(parsed)) return [];
		return parsed.map(normalizeRecentViewedListing).filter(Boolean);
	} catch (error) {
		return [];
	}
}

function loadRecentViewedListings()
{
	if (!window.localStorage) return [];
	const saved = window.localStorage.getItem(REALJEJU_RECENT_LISTINGS_KEY);
	if (!saved) return [];
	const parsed = parseRecentViewedListings(saved);
	return parsed
		.sort((a, b) => Number(b.updatedAt || 0) - Number(a.updatedAt || 0))
		.slice(0, REALJEJU_RECENT_LISTINGS_LIMIT);
}

function getCurrentMainActionForRecentViewed()
{
	// 최근 조회에서 상세를 열기 전에, 현재 어떤 상단 뷰에 머물러 있는지 확인해
	// home이 아닌 화면에서는 홈으로 복귀 후 목록/상세 오픈 동작을 맞춘다.
	if (document.body.classList.contains("admin-page-open")) return "admin";
	if (document.body.classList.contains("broker-home-page-open")) return "broker-home";
	if (document.body.classList.contains("property-register-page-open")) return "register";
	if (document.body.classList.contains("notice-page-open")) return "notice";
	if (document.body.classList.contains("my-suite-page-open")) {
		const activeMySuiteTab = document.querySelector(".my-suite-tab.active");
		return activeMySuiteTab && activeMySuiteTab.dataset.mySuiteTab === "favorites" ? "favorites" : "";
	}
	if (document.body.classList.contains("presale-page-open")) return "presale";
	return "home";
}

