async function openRecentViewedListingById(listingId)
{
	// 최근 조회 카드에서 받은 id를 화면 처리에 쓰기 전에 항상 정규화한다.
	const normalizedId = normalizeItemId(listingId);
	if (!normalizedId) return;
	let listing = findRealJejuListingById(normalizedId);
	const cachedRecent = realjejuRecentViewedListings.find((row) => normalizeItemId(row && row.id) === normalizedId) || null;
	// 목록에서 id를 찾지 못한 경우 서버/캐시된 최근조회 데이터로 최소 표시 정보를 구성해
	// 뒤늦은 상세 데이터 로딩 실패 시에도 상세 영역을 비정상 종료시키지 않는다.
	if (!listing) {
		const dbItem = await resolveDetailDataFromDatabase({ id: normalizedId });
		if (dbItem && normalizeItemId(dbItem.id) === normalizedId) {
			listing = dbItem;
		}
	}
	if (!listing) {
		listing = {
			id: normalizedId,
			title: cachedRecent && (cachedRecent.title || cachedRecent.address || cachedRecent.summary) ? normalizeRecentValueText(cachedRecent.title || cachedRecent.address || cachedRecent.summary) : "매물 조회",
			listingNo: cachedRecent ? normalizePropertyListingNoCandidate(String(cachedRecent.listingNo || "").trim()) : "",
			type: cachedRecent ? normalizeRecentValueText(cachedRecent.propertyType || cachedRecent.type || cachedRecent.property_type || cachedRecent.property_type_label || cachedRecent.propertyTypeLabel || "") : "",
			dealType: cachedRecent ? cachedRecent.dealType : "",
			price: cachedRecent ? cachedRecent.price : "",
			address: cachedRecent ? cachedRecent.address : "",
			summary: cachedRecent ? cachedRecent.summary : ""
		};
	}
	if (!listing) return;

	const normalizedTargetId = normalizeItemId(listing && listing.id);
	if (normalizedTargetId) {
		const patchListingInPlace = (list) => {
			// 최근 조회로 연 경우에도 좌측 목록/필터 정렬을 건드리지 않도록
			// 기존 순서는 유지하고 항목 데이터만 최신값으로 갱신한다.
			const source = Array.isArray(list) ? [...list] : [];
			const index = source.findIndex(candidate => normalizeItemId(candidate && candidate.id) === normalizedTargetId);
			if (index >= 0) {
				source[index] = { ...source[index], ...listing };
			}
			return source;
		};
		state.all = patchListingInPlace(state.all);
		state.filtered = patchListingInPlace(state.filtered);
	}

	// 홈이 아니면 먼저 홈 이동 후 최근조회 상세 모드로 진입해
	// 사이드 바/필터 상태가 다른 화면 규칙에 의해 꼬이지 않도록 처리한다.
	const sideNavAction = getCurrentMainActionForRecentViewed();
	if (sideNavAction !== "home") {
		if (typeof window.realjejuGoHome === "function") {
			const homeResult = window.realjejuGoHome({ resetDetail: true });
			if (homeResult && typeof homeResult.then === "function") {
				await homeResult.catch(() => {});
			}
		}
		await new Promise((resolve) => setTimeout(resolve, 0));
	}

	// 공유형 최근조회 상세 모드 클래스는 목록-필터바 폭 조정 및 오른쪽 상세 패널 표시 계산의 기준점이다.
		const detailPanel = document.getElementById("sidebarDetailPanel");
		closeEducationFacilityDetailForPropertyInteraction();
		if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
			await closeRoadviewPanelForPropertyInteraction();
		} else if (typeof hideRoadview === "function") {
			await hideRoadview();
		}
	document.body.classList.remove("detail-page-panel-open", "direct-detail-list-mode", "list-shared-detail-mode", "map-panels-collapsed", "map-detail-panel-active");
	document.body.classList.add("shared-detail-mode");
	document.body.classList.add("recent-shared-detail-mode");
	document.body.classList.remove("sidebar-list-collapsed");
	state.isListOpen = true;
	state.selectionMode = "single";
	state.selectedClusterKey = null;
	state.selectedMarkerId = normalizedTargetId;
	state.selectedMarkerIds = new Set([normalizedTargetId]);
	lockListToItems([listing]);
	updateMarkerSelection(normalizedTargetId, [normalizedTargetId]);
	if (detailPanel) {
		detailPanel.style.display = "block";
		detailPanel.style.opacity = "";
		detailPanel.style.visibility = "";
		detailPanel.style.pointerEvents = "";
	}
	// 최근 조회 상세 오픈 직후에도 필터바를 좌측 오프셋 계산 대상으로 잡도록
	// 렌더 타이밍마다 정렬 보정을 강제 호출한다.
	setSharedDetailMode(true);
	if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
		window.realjejuSyncTopbarFilterSafeLeft();
	}

	allowDetailOpenFromListClick = true;
	let detailOpenError;
	try {
		// 최근 조회 메뉴 클릭은 최근조회 패널 정렬에만 영향을 주지 않도록, 조회 이력 업서트는 건너뛴다.
		await openDetailPanel(listing, {
			syncUrl: false,
			forceOpen: true,
			overlayPage: false,
			sharedMode: true,
			skipRecentViewTracking: true
		});
		if (sidebar) sidebar.classList.add("expanded");
		state.isListOpen = true;
		updateSidebarWidth();
		if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
		if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
		if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
			window.realjejuSyncTopbarFilterSafeLeft();
		}
		if (typeof refreshMapLayout === "function") {
			refreshMapLayout();
			setTimeout(refreshMapLayout, 120);
		}
	} catch (error) {
		detailOpenError = error;
		console.error("최근 조회 상세 패널 열기 실패:", error);
	} finally {
		allowDetailOpenFromListClick = false;
	}
	if (detailOpenError) {
		throw detailOpenError;
	}
	syncDetailUrl(listing.id);
	await focusProperty(normalizedTargetId || listing.id);
	await focusRecentViewedListingOnMap(currentDetailItem || listing, normalizedTargetId || listing.id);

	setTimeout(() => {
		state.isListOpen = true;
		updateSidebarWidth();
		if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
		if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
		if (typeof window.realjejuSyncTopbarFilterSafeLeft === "function") {
			window.realjejuSyncTopbarFilterSafeLeft();
		}
		refreshClusterBadges();
	}, 0);
}

async function activateSideRecentCategory(category)
{
	const nextCategory = REALJEJU_RECENT_CATEGORY_STORAGE_KEYS[category] ? category : "realestate";
	const currentCategory = getCurrentSideRecentCategory();
	if (currentCategory === nextCategory) return;
	const categoryButton = document.querySelector(`.global-category-item[data-global-category="${CSS.escape(nextCategory)}"]`);
	if (categoryButton) categoryButton.click();
	await new Promise((resolve) => setTimeout(resolve, nextCategory === "local-business" ? 260 : (nextCategory === "parcel" ? 80 : 0)));
}

async function openPartTimeRecentItem(itemId)
{
	for (let attempt = 0; attempt < 12; attempt += 1) {
		const job = typeof findRealjejuPartTimeJobById === "function" ? findRealjejuPartTimeJobById(itemId) : null;
		if (job && typeof openPartTimeDetailPanel === "function") {
			openPartTimeDetailPanel(itemId);
			return true;
		}
		await new Promise((resolve) => setTimeout(resolve, 160));
	}
	return false;
}

async function openSideRecentMarker(markerKey, options = {})
{
	if (!markerKey) return false;
	for (let attempt = 0; attempt < 12; attempt += 1) {
		const marker = document.querySelector(`[data-category-recent-key="${CSS.escape(markerKey)}"]`);
		if (marker && typeof marker.click === "function") {
			if (options && options.tooltipOnly) {
				if (typeof marker.focus === "function") marker.focus({ preventScroll: true });
				marker.dispatchEvent(new MouseEvent("mouseenter", { bubbles: true, cancelable: true }));
				marker.classList.add("realjeju-side-recent-marker-focus");
				setTimeout(() => marker.classList.remove("realjeju-side-recent-marker-focus"), 900);
				return true;
			}
			marker.click();
			return true;
		}
		await new Promise((resolve) => setTimeout(resolve, 180));
	}
	return false;
}

function getBrokerOfficeRecentMarkerKey(office)
{
	if (!office || typeof getBrokerOfficeOverlayKey !== "function") return "";
	return `broker:${getBrokerOfficeOverlayKey(office)}`;
}

async function findBrokerOfficeForRecentMarkerKey(markerKey)
{
	const key = String(markerKey || "").trim();
	if (!key || !key.startsWith("broker:")) return null;
	let rows = Array.isArray(state.brokerOfficeRows) && state.brokerOfficeRows.length
		? state.brokerOfficeRows
		: [];
	if (!rows.length && typeof fetchBrokerOfficeMapRows === "function") {
		try {
			rows = await fetchBrokerOfficeMapRows();
		} catch (error) {
			rows = [];
		}
	}
	const candidates = [];
	(Array.isArray(rows) ? rows : []).forEach((office) => {
		if (!office) return;
		candidates.push(office);
		if (Array.isArray(office.offices)) office.offices.forEach((item) => item && candidates.push(item));
	});
	return candidates.find((office) => getBrokerOfficeRecentMarkerKey(office) === key) || null;
}

async function showBrokerOfficeRecentCard(recentItem)
{
	const markerKey = String(recentItem && recentItem.markerKey || "").trim();
	if (markerKey.startsWith("professional:")) {
		const business = findLocalProfessionalBusinessById(markerKey.slice("professional:".length));
		return business ? showLocalProfessionalBusinessCard(business) : false;
	}
	if (!markerKey.startsWith("broker:")) return false;
	const fallbackOfficeName = String(recentItem && recentItem.title || "").trim();
	const fallbackAddress = String(recentItem && recentItem.summary || "").trim();
	if (fallbackOfficeName) {
		showLocalBusinessRecentCard(buildLocalBusinessCardDataFromBrokerOffice({
			officeName: fallbackOfficeName,
			address: fallbackAddress
		}, recentItem));
		focusLocalBusinessRecentMapPosition(recentItem);
	}
	const office = await findBrokerOfficeForRecentMarkerKey(markerKey);
	if (office) {
		await showBrokerOfficeLocalBusinessCard(office, recentItem);
		return true;
	}
	if (!fallbackOfficeName) return false;
	return true;
}

async function openParcelRecentItem(recentItem)
{
	const position = normalizeJejuLatLngPair(recentItem && recentItem.lat, recentItem && recentItem.lng);
	if (!position || !state.map || !window.kakao || !kakao.maps) return false;
	const latLng = new kakao.maps.LatLng(position.lat, position.lng);
	if (typeof state.map.relayout === "function") state.map.relayout();
	if (typeof state.map.getLevel === "function" && typeof state.map.setLevel === "function" && state.map.getLevel() > 5) {
		state.map.setLevel(5, { anchor: latLng, __allowClusterRestore: true });
	}
	if (typeof state.map.setCenter === "function") state.map.setCenter(latLng, { __allowClusterRestore: true });
	else if (typeof state.map.panTo === "function") state.map.panTo(latLng);
	return await showParcelBoundaryForSearchLocation(position.lat, position.lng, {
		openLandInfoPanel: true,
		fromRecentParcel: true
	});
}

async function openSideCategoryRecentItem(category, itemId)
{
	const nextCategory = REALJEJU_RECENT_CATEGORY_STORAGE_KEYS[category] ? category : "realestate";
	if (nextCategory === "realestate") {
		await openRecentViewedListingById(itemId);
		return;
	}
	const recentItem = loadSideCategoryRecentItems(nextCategory)
		.find((item) => String(item && item.id || "") === String(itemId || ""));
	await activateSideRecentCategory(nextCategory);
	if (!recentItem) return;
	if (recentItem.action === "charger-roadview" && nextCategory === "ev-charger") {
		const lat = Number(recentItem.lat);
		const lng = Number(recentItem.lng);
		if (Number.isFinite(lat) && Number.isFinite(lng) && typeof showRoadview === "function") {
			showRoadview(lat, lng, { evChargerRecent: recentItem });
		}
		return;
	}
	if (recentItem.action === "part-time-detail") {
		await openPartTimeRecentItem(recentItem.id);
		return;
	}
	if (recentItem.action === "parcel-info" && nextCategory === "parcel") {
		await openParcelRecentItem(recentItem);
		return;
	}
	// 동네업체 최근 조회는 업체 카드를 기록한 것과 같은 공통 카드 경로로 다시 연다.
	// 저장 action이 business-card인 항목을 map-marker 분기에만 맡기면 클릭해도 카드가 복원되지 않는다.
	if (recentItem.action === "business-card" && nextCategory === "local-business") {
		const opened = await showBrokerOfficeRecentCard(recentItem);
		if (opened) return;
		// 저장 항목에 markerKey가 지워진 경우에도 지도 위치/마커 경로로 복구한다.
		if (nextCategory === "local-business") {
			focusLocalBusinessRecentMapPosition(recentItem);
		}
		await openSideRecentMarker(recentItem.markerKey, {
			tooltipOnly: nextCategory === "local-business"
		});
		return;
	}
	if (recentItem.action === "map-marker") {
		if (nextCategory === "local-business"
			&& /^(broker|professional):/.test(String(recentItem.markerKey || ""))) {
			const opened = await showBrokerOfficeRecentCard(recentItem);
			if (opened) return;
		}
		if (nextCategory === "local-business") {
			focusLocalBusinessRecentMapPosition(recentItem);
		}
		await openSideRecentMarker(recentItem.markerKey, {
			tooltipOnly: nextCategory === "local-business"
		});
		return;
	}
	if (typeof window.realjejuOpenCustomCategoryRecentItem === "function") {
		await window.realjejuOpenCustomCategoryRecentItem(nextCategory, recentItem);
	}
}

function isRealjejuPropertySubrouteSegment(value)
{
	let normalized = String(value || "").trim().toLowerCase();
	try {
		normalized = decodeURIComponent(normalized);
	} catch (error) {}
	return REALJEJU_PROPERTY_SUBROUTE_SEGMENTS.has(normalized);
}

function getDetailIdFromLocation()
{
	const pathname = String(window.location.pathname || "");
	const pathMatch = pathname.match(/^\/properties\/([^/]+)\/?$/i);
	if (pathMatch && pathMatch[1] && !isRealjejuPropertySubrouteSegment(pathMatch[1])) {
		try {
			return normalizeItemId(decodeURIComponent(pathMatch[1]));
		} catch (error) {
			return normalizeItemId(pathMatch[1]);
		}
	}
	const acceptsLegacyQuery = pathname === "/"
		|| pathname === "/properties"
		|| pathname === "/properties/"
		|| /^\/properties\/index\.html$/i.test(pathname)
		|| /^\/(?:index|realjeju_\d+\.\d+)\.html$/i.test(pathname);
	if (!acceptsLegacyQuery) return "";
	const params = new URLSearchParams(String(window.location.search || ""));
	return normalizeItemId(params.get(DETAIL_QUERY_KEY));
}

function clearPropertyScaleQueryCaches()
{
	propertyScaleRegionCountGeneration += 1;
	propertyScaleRegionCountCache.clear();
	propertyScaleRegionCountInflight.clear();
	propertyScaleRegionPageCache.clear();
	propertyScaleRegionFirstPageCache.clear();
	propertyScaleAgentPageCache.clear();
	propertyScaleViewportCache.clear();
	propertyScaleViewportCoverage = null;
	propertyScaleMarkerSnapshot = null;
}

function schedulePropertyScaleDataRefresh(delay = 0, options = {})
{
	if (propertyScaleRefreshTimer) clearTimeout(propertyScaleRefreshTimer);
	propertyScaleRefreshTimer = setTimeout(() => {
		propertyScaleRefreshTimer = 0;
		refreshPropertyScaleMapData(options).catch((error) => {
			console.error("지도 범위 매물 새로고침 실패:", error);
		});
	}, Math.max(0, Number(delay) || 0));
}

function canPrefetchLandingPropertyViewport()
{
	return document.body?.classList?.contains("main-landing-page-open") === true
		&& Boolean(state.map)
		&& !mapListingsInitialDataApplied;
}

function isPropertyCoordinatePresentationMode(mode)
{
	return mode === "clusters" || mode === "individual";
}

function scheduleLandingPropertyViewportPrefetch()
{
	if (!canPrefetchLandingPropertyViewport()
		|| landingPropertyViewportPrefetchTimer
		|| landingPropertyViewportPrefetchPromise) return false;

	landingPropertyViewportPrefetchTimer = window.setTimeout(() => {
		landingPropertyViewportPrefetchTimer = 0;
		if (!canPrefetchLandingPropertyViewport()) return;
		const mode = getPropertyMapPresentationMode();
		if (!isPropertyCoordinatePresentationMode(mode)) return;
		const bounds = getPropertyScaleViewportBounds();
		if (!bounds) return;
		// 화면 상태와 마커는 건드리지 않고 경량 좌표 결과만 30초 캐시에 채운다.
		landingPropertyViewportPrefetchPromise = fetchPropertyScaleViewportRows({ bounds })
			.catch((error) => {
				console.warn("랜딩 부동산 지도 경량 좌표 선조회 실패:", error);
				return null;
			})
			.finally(() => {
				landingPropertyViewportPrefetchPromise = null;
			});
	}, 0);
	return true;
}

function matchesBrokerListingMapScope(item)
{
	const scope = String(state.brokerListingMapScope || "all");
	if (scope === "all") return true;
	if (!canUseBrokerOwnListingMapFilters()) return true;
	const user = getBrokerMapCurrentUser();
	const officeIdentity = getBrokerOfficeIdentityFromCurrentOffice();
	const itemIdentity = getBrokerListingIdentity(item);
	if (scope === "mine") {
		const userId = normalizeItemId(user && user.id);
		return !!(userId && itemIdentity.userId && itemIdentity.userId === userId);
	}
	if (scope === "office") {
		if (officeIdentity.agencyId && itemIdentity.agencyId) return officeIdentity.agencyId === itemIdentity.agencyId;
		if (officeIdentity.userId && itemIdentity.userId) return officeIdentity.userId === itemIdentity.userId;
		if (officeIdentity.officeName && itemIdentity.officeName) return officeIdentity.officeName === itemIdentity.officeName;
		return false;
	}
	return true;
}

function matchesDealFilterValue(itemDeal, selectedDealValue)
{
	const deal = String(itemDeal || "").trim();
	const selected = String(selectedDealValue || "").trim();
	if (!deal || !selected) return false;
	if (deal === selected) return true;
	return selected === "월세" && (deal === "년세" || deal === "연세");
}

function matchesSelectedDealFilter(itemDeal, dealValues)
{
	if (!(dealValues instanceof Set) || dealValues.size === 0) return false;
	const deals = (Array.isArray(itemDeal) ? itemDeal : [itemDeal])
		.map((deal) => {
			const label = typeof getMapDealLabel === "function" ? getMapDealLabel(deal) : deal;
			return String(label || deal || "").trim();
		})
		.filter(Boolean);
	return Array.from(dealValues).some(value => deals.some(deal => matchesDealFilterValue(deal, value)));
}

function ensureTypeFilterHasSelection()
{
	if (!(selectedType instanceof Set) || selectedType.size === 0) {
		selectedType = createDefaultTypeFilterSet();
	}
}

function isBrokerOfficeRegNoInput(input)
{
	return !!(input && input.id && BROKER_OFFICE_REG_NO_INPUT_IDS.has(input.id));
}

function formatBrokerOfficeRegNoInputValue(value)
{
	const text = String(value || "");
	const trimmed = text.trim();
	if (!/^\d{14}$/.test(trimmed)) return text;
	return `${trimmed.slice(0, 5)}-${trimmed.slice(5, 9)}-${trimmed.slice(9, 14)}`;
}

function isNumericBrokerOfficeRegNoText(value)
{
	const text = String(value || "");
	return !!text && /^[\d-]+$/.test(text);
}

function limitNumericBrokerOfficeRegNoInputValue(value)
{
	const text = String(value || "");
	if (!isNumericBrokerOfficeRegNoText(text)) return text;
	let digitCount = 0;
	let nextValue = "";
	for (const char of text) {
		if (/\d/.test(char)) {
			if (digitCount >= 14) continue;
			digitCount += 1;
			nextValue += char;
			continue;
		}
		nextValue += char;
	}
	return nextValue;
}

function applyBrokerOfficeRegNoAutoFormat(input)
{
	if (!isBrokerOfficeRegNoInput(input)) return;
	input.setAttribute("inputmode", "text");
	input.removeAttribute("maxlength");
	const limitedValue = limitNumericBrokerOfficeRegNoInputValue(input.value);
	const nextValue = formatBrokerOfficeRegNoInputValue(limitedValue);
	if (input.value === nextValue) return;
	input.value = nextValue;
	try {
		input.setSelectionRange(input.value.length, input.value.length);
	} catch (_) {}
}

document.addEventListener("input", function (event) {
	applyBrokerOfficeRegNoAutoFormat(event.target);
}, true);

document.addEventListener("focusin", function (event) {
	applyBrokerOfficeRegNoAutoFormat(event.target);
}, true);

document.addEventListener("focusout", function (event) {
	applyBrokerOfficeRegNoAutoFormat(event.target);
}, true);

