document.addEventListener("click", (event) => {
  const countButton = event.target.closest(".parcel-land-price-count-button");
  if (countButton) {
    const section = countButton.closest("[data-parcel-land-price-section]");
    if (!section) return;
    section.querySelectorAll(".parcel-land-price-count-button").forEach((item) => {
      item.classList.toggle("is-active", item === countButton);
    });
    const chart = section.querySelector("[data-parcel-land-price-chart]");
    if (chart) chart.dataset.renderSignature = "";
    scheduleParcelLandPriceRefresh();
    return;
  }

  const listToggle = event.target.closest("[data-parcel-land-price-list-toggle]");
  if (listToggle) {
    const section = listToggle.closest("[data-parcel-land-price-section]");
    if (!section) return;
    section.dataset.landPriceListExpanded = section.dataset.landPriceListExpanded === "true" ? "false" : "true";
    scheduleParcelLandPriceRefresh();
    return;
  }

  const navButton = event.target.closest("[data-price-nav]");
  if (navButton) {
    const section = navButton.closest("[data-parcel-land-price-section]");
    if (!section || navButton.disabled) return;
    const currentIndex = Number(section.dataset.selectedPriceIndex || 0);
    section.dataset.selectedPriceIndex = String(
      navButton.dataset.priceNav === "older" ? currentIndex + 1 : currentIndex - 1
    );
    scheduleParcelLandPriceRefresh();
    return;
  }

  const chartPoint = event.target.closest(".parcel-land-price-chart-point");
  if (chartPoint) {
    const section = chartPoint.closest("[data-parcel-land-price-section]");
    if (!section) return;
    section.dataset.selectedPriceIndex = String(Number(chartPoint.dataset.priceItemIndex || 0));
    scheduleParcelLandPriceRefresh();
  }
});

document.addEventListener("keydown", (event) => {
  if (event.key !== "Enter" && event.key !== " ") return;
  const chartPoint = event.target.closest(".parcel-land-price-chart-point");
  if (!chartPoint) return;
  event.preventDefault();
  const section = chartPoint.closest("[data-parcel-land-price-section]");
  if (!section) return;
  section.dataset.selectedPriceIndex = String(Number(chartPoint.dataset.priceItemIndex || 0));
  scheduleParcelLandPriceRefresh();
});

document.addEventListener("pointermove", (event) => {
  const svg = event.target.closest("[data-parcel-land-price-chart] svg");
  if (!svg) return;
  const chartPoints = Array.from(svg.querySelectorAll(".parcel-land-price-chart-point"));
  if (!chartPoints.length) return;
  const rect = svg.getBoundingClientRect();
  if (!rect.width) return;
  const viewBoxWidth = svg.viewBox?.baseVal?.width || 640;
  const cursorX = ((event.clientX - rect.left) / rect.width) * viewBoxWidth;
  const nearestPoint = chartPoints.reduce((nearest, point) => {
    const distance = Math.abs(Number(point.dataset.priceX) - cursorX);
    if (!nearest || distance < nearest.distance) return { point, distance };
    return nearest;
  }, null);
  if (!nearestPoint) return;
  const section = svg.closest("[data-parcel-land-price-section]");
  if (!section) return;
  const nextIndex = String(Number(nearestPoint.point.dataset.priceItemIndex || 0));
  if (section.dataset.selectedPriceIndex === nextIndex) return;
  section.dataset.selectedPriceIndex = nextIndex;
  scheduleParcelLandPriceRefresh();
});

