function getPropertyRegionManagementEffectiveStatus(row)
{
	const payload = row && row.payload && typeof row.payload === "object" ? row.payload : {};
	const deletedAt = row?.payload_deleted_at || payload.deleted_at || row?.deleted_at;
	const brokerStatus = String(row?.payload_broker_status || payload.broker_status || "").trim().toLowerCase();
	const status = String(row?.status || "").trim().toLowerCase();
	if (status === "deleted" || status === "trash" || deletedAt) return "deleted";
	if (brokerStatus === "closed") return "closed";
	if (brokerStatus === "hidden" || brokerStatus === "archive") return "hidden";
	return status;
}

function isPropertyRegionManagementCountRow(row)
{
	return !["closed", "hidden", "archive", "deleted", "trash"].includes(getPropertyRegionManagementEffectiveStatus(row));
}

function normalizePropertyRegionManagementCountRow(row)
{
	const source = row && typeof row === "object" ? row : {};
	return {
		...source,
		payload: {
			broker_status: source.payload_broker_status || "",
			deleted_at: source.payload_deleted_at || "",
			office_name: source.payload_office_name || "",
			registrant: { office_name: source.payload_registrant_office_name || "" }
		}
	};
}

async function loadPropertyRegionManagementCountRows()
{
	const now = Date.now();
	if (Array.isArray(propertyRegionManagementCountRowsCache)
		&& now - propertyRegionManagementCountRowsLoadedAt < PROPERTY_REGION_MANAGEMENT_COUNT_CACHE_MS) {
		return propertyRegionManagementCountRowsCache;
	}
	if (propertyRegionManagementCountRowsPromise) return propertyRegionManagementCountRowsPromise;
	if (now < propertyRegionManagementCountRowsFailureUntil) return getPropertyRegionCountSourceItems();

	propertyRegionManagementCountRowsPromise = (async () => {
		try {
			if (typeof loadSupabaseScript === "function") await loadSupabaseScript();
			const client = typeof window.getRealjejuSupabaseClient === "function"
				? window.getRealjejuSupabaseClient()
				: null;
			if (!client) throw new Error("전체 매물 집계 클라이언트를 준비하지 못했습니다.");
			const rows = [];
			for (let from = 0; ; from += PROPERTY_REGION_MANAGEMENT_COUNT_PAGE_SIZE) {
				const { data, error } = await client
					.from("property_listings")
					.select(PROPERTY_REGION_MANAGEMENT_COUNT_SELECT)
					.order("id", { ascending: true })
					.range(from, from + PROPERTY_REGION_MANAGEMENT_COUNT_PAGE_SIZE - 1);
				if (error) throw error;
				const pageRows = Array.isArray(data) ? data : [];
				rows.push(...pageRows);
				if (pageRows.length < PROPERTY_REGION_MANAGEMENT_COUNT_PAGE_SIZE) break;
			}
			propertyRegionManagementCountRowsCache = rows
				.map(normalizePropertyRegionManagementCountRow)
				.filter(isPropertyRegionManagementCountRow);
			propertyRegionManagementCountRowsLoadedAt = Date.now();
			propertyRegionManagementCountRowsFailureUntil = 0;
			return propertyRegionManagementCountRowsCache;
		} catch (error) {
			propertyRegionManagementCountRowsFailureUntil = Date.now() + 30000;
			console.warn("상위 행정구역 전체 매물 집계 조회 실패:", error);
			return getPropertyRegionCountSourceItems();
		} finally {
			propertyRegionManagementCountRowsPromise = null;
		}
	})();
	return propertyRegionManagementCountRowsPromise;
}

