function initLocationAnalysisDropdown()
{
	if (document.documentElement.dataset.locationAnalysisDropdownBound === "true") return;
	document.documentElement.dataset.locationAnalysisDropdownBound = "true";

	document.addEventListener("click", (e) => {
		const trigger = e.target && e.target.closest ? e.target.closest("#locationAnalysisTrigger") : null;
		const dropdown = document.getElementById("locationAnalysisDropdown");
		if (!trigger || !dropdown) return;
		e.preventDefault();
		e.stopPropagation();
		e.stopImmediatePropagation();

		const willOpen = !dropdown.classList.contains("open");
		closeMapFilterDropdownsExcept("locationAnalysisDropdown");
		dropdown.classList.toggle("open", willOpen);
		trigger.setAttribute("aria-expanded", willOpen ? "true" : "false");
		if (willOpen) syncOpenMapFilterMenuPosition(dropdown);
	}, true);

	document.addEventListener("click", (e) => {
		const dropdown = document.getElementById("locationAnalysisDropdown");
		if (!dropdown || dropdown.contains(e.target)) return;
		dropdown.classList.remove("open");
		const trigger = document.getElementById("locationAnalysisTrigger");
		if (trigger) trigger.setAttribute("aria-expanded", "false");
	});

	document.addEventListener("change", (e) => {
		const input = e.target && e.target.closest ? e.target.closest("#lifeSafetyOverlayCheck") : null;
		if (!input) return;
		setLifeSafetyOverlayVisible(input.checked);
	});

	document.addEventListener("click", (e) => {
		const resetBtn = e.target && e.target.closest ? e.target.closest("#locationAnalysisResetBtn") : null;
		if (!resetBtn) return;
		e.preventDefault();
		e.stopPropagation();
		e.stopImmediatePropagation();
		if (lifeSafetyOverlayCheck) lifeSafetyOverlayCheck.checked = false;
		setLifeSafetyOverlayVisible(false);
	}, true);

	syncLocationAnalysisUI();
}

