function captureLockedListBeforeBrowserSwitch()
{
	if (!state.keepLockedListOnMapClick || !Array.isArray(state.lockedListIds) || !state.lockedListIds.length) {
		browserFocusLockedListSnapshot = null;
		return;
	}
	const sourceItems = getLockedListItems();
	if (!sourceItems || !sourceItems.length) return;
	browserFocusLockedListSnapshot = {
		path: `${window.location.pathname || ""}${window.location.search || ""}`,
		ids: state.lockedListIds.slice(),
		sourceItems: sourceItems.slice(),
		renderedItems: Array.isArray(state.leftListItems) ? state.leftListItems.slice() : [],
		selectedClusterKey: state.selectedClusterKey,
		selectedClusterAnchor: state.selectedClusterAnchor,
		selectedMarkerIds: state.selectedMarkerIds instanceof Set
			? Array.from(state.selectedMarkerIds)
			: [],
		selectionMode: state.selectionMode || "cluster",
		wasOpen: !!state.isListOpen,
		scrollTop: propertyList ? propertyList.scrollTop : 0
	};
}

function restoreLockedListAfterBrowserSwitch()
{
	const snapshot = browserFocusLockedListSnapshot;
	if (!snapshot || !snapshot.wasOpen) return;
	const currentPath = `${window.location.pathname || ""}${window.location.search || ""}`;
	if (snapshot.path !== currentPath) {
		browserFocusLockedListSnapshot = null;
		return;
	}
	const lockIntact = state.keepLockedListOnMapClick
		&& state.isListOpen
		&& Array.isArray(state.lockedListIds)
		&& state.lockedListIds.length === snapshot.ids.length
		&& state.lockedListIds.every((id, index) => normalizeItemId(id) === normalizeItemId(snapshot.ids[index]));
	if (lockIntact && propertyList && propertyList.childElementCount) {
		propertyList.scrollTop = snapshot.scrollTop;
		return;
	}

	lockListToItems(snapshot.sourceItems, { keepOnMapClick: true });
	state.selectionMode = snapshot.selectionMode;
	state.selectedClusterKey = snapshot.selectedClusterKey;
	state.selectedClusterAnchor = snapshot.selectedClusterAnchor;
	state.selectedMarkerId = null;
	openSidebarList();

	const sortedItems = sortItems(snapshot.sourceItems);
	resetLeftListPagination(sortedItems);
	if (snapshot.renderedItems.length) {
		state.leftListItems = snapshot.renderedItems.slice();
		state.leftListRenderedCount = Math.min(sortedItems.length, snapshot.renderedItems.length);
		state.leftListVisibleCount = Math.max(LEFT_LIST_PAGE_SIZE, snapshot.renderedItems.length);
		renderList(state.leftListItems);
	} else {
		if (propertyList) propertyList.innerHTML = "";
		loadMoreLeftListItems({ sourceItems: sortedItems });
	}
	setResultInfo(`선택 매물 ${sortedItems.length}건`);
	setListInfo(state.leftListItems.length < sortedItems.length ? `${sortedItems.length}개 중 ${state.leftListItems.length}개` : `총 ${sortedItems.length}개 매물`);
	updateMarkerSelection(null, snapshot.selectionMode === "region-list" ? [] : snapshot.selectedMarkerIds);
	setTimeout(() => {
		if (propertyList) propertyList.scrollTop = snapshot.scrollTop;
		refreshClusterBadges();
	}, 0);
}

window.addEventListener("blur", captureLockedListBeforeBrowserSwitch, { passive: true });

window.addEventListener("focus", () => setTimeout(restoreLockedListAfterBrowserSwitch, 60), { passive: true });

document.addEventListener("visibilitychange", () => {
	if (document.visibilityState === "hidden") captureLockedListBeforeBrowserSwitch();
	else setTimeout(restoreLockedListAfterBrowserSwitch, 60);
});

function deleteLeftListDetailItemCache(id)
{
	const key = normalizeItemId(id);
	if (key) leftListDetailItemCache.delete(key);
}

function getSidebarAgentListDeepLink()
{
	try {
		const params = new URLSearchParams(window.location.search || "");
		if (params.get("agentList") !== "1") return null;
		const userId = String(params.get("agentUser") || "").trim();
		const agencyId = String(params.get("agentAgency") || "").trim();
		const officeName = String(params.get("agentOffice") || "").trim();
		const label = String(params.get("agentLabel") || officeName || "").trim();
		const name = String(params.get("agentName") || "").trim();
		const address = String(params.get("agentAddress") || "").trim();
		if (!userId && !agencyId && !officeName && !label) return null;
		return {
			filter: {
				userId,
				agencyId,
				officeName,
				rawOfficeName: officeName,
				label: label || officeName || name || "공인중개사"
			},
			card: {
				office: label || officeName,
				name,
				address
			}
		};
	} catch (error) {
		return null;
	}
}

function getSidebarAgentPublicIdDeepLink()
{
	try {
		const value = new URLSearchParams(window.location.search || "").get("agency");
		const normalizePublicId = window.normalizeRealjejuAgencyPublicId;
		return typeof normalizePublicId === "function"
			? normalizePublicId(value)
			: String(value || "").trim().toLowerCase();
	} catch (error) {
		return "";
	}
}

async function resolveSidebarAgentPublicIdDeepLink(publicId)
{
	const resolveAgency = window.resolveRealjejuAgencyByPublicId;
	if (typeof resolveAgency !== "function") return null;
	const normalizePublicId = window.normalizeRealjejuAgencyPublicId;
	const agency = await resolveAgency(publicId);
	if (!agency) return null;
	const office = {
		agencyId: normalizeItemId(agency.id || ""),
		publicId: typeof normalizePublicId === "function"
			? normalizePublicId(agency.public_id || publicId)
			: String(agency.public_id || publicId || "").trim().toLowerCase(),
		userId: normalizeItemId(agency.user_id || ""),
		officeName: String(agency.office_name || "공인중개사").trim(),
		ownerName: String(agency.owner_name || "").trim(),
		address: String(agency.office_address || "").trim(),
		phone: String(agency.phone || "").trim(),
		regNo: String(agency.office_reg_no || "").trim(),
		kakaoUrl: String(agency.kakao_url || "").trim()
	};
	return {
		filter: buildBrokerOfficeAgentFilter(office),
		card: buildBrokerOfficeAgentCard(office)
	};
}

async function openSidebarAgentListFromDeepLink(attempt = 0, requestedPublicId = "")
{
	const normalizePublicId = window.normalizeRealjejuAgencyPublicId;
	const publicId = requestedPublicId
		? (typeof normalizePublicId === "function"
			? normalizePublicId(requestedPublicId)
			: String(requestedPublicId || "").trim().toLowerCase())
		: getSidebarAgentPublicIdDeepLink();
	const deepLink = publicId
		? await resolveSidebarAgentPublicIdDeepLink(publicId)
		: getSidebarAgentListDeepLink();
	if (!deepLink) {
		if (publicId && attempt < 30) {
			setTimeout(() => openSidebarAgentListFromDeepLink(attempt + 1, publicId), 180);
		}
		return false;
	}
	if (document.body) document.body.classList.remove("main-landing-page-open");
	const landingPage = document.getElementById("mainLandingPage");
	if (landingPage) landingPage.setAttribute("aria-hidden", "true");
	// 4.924: 전체 지도 매물 배열을 기다리지 않고 중개사 전용 30건 RPC를 바로 연다.
	await showAgentListingList(deepLink.filter, deepLink.card);
	return true;
}

window.realjejuOpenSidebarAgentListFromDeepLink = openSidebarAgentListFromDeepLink;

if (document.readyState === "loading") {
	document.addEventListener("DOMContentLoaded", () => openSidebarAgentListFromDeepLink(), { once: true });
} else {
	setTimeout(() => openSidebarAgentListFromDeepLink(), 0);
}

function getPresaleFilterOwnerDropdown(element)
{
	if (!element || typeof element.closest !== "function") return null;
	const localDropdown = element.closest("[data-presale-filter-dropdown]");
	if (localDropdown) return localDropdown;
	const menu = element.closest("[data-presale-filter-menu]");
	const ownerId = menu ? String(menu.dataset.mapFilterOwner || "").trim() : "";
	return ownerId ? document.getElementById(ownerId) : null;
}

function formatPresaleFilterNumber(value, decimals = 0)
{
	const number = Number(value);
	if (!Number.isFinite(number)) return "0";
	return Number(number.toFixed(decimals)).toLocaleString("ko-KR");
}

function formatPresaleRangeValue(dropdown, value)
{
	const kind = String(dropdown && dropdown.dataset.rangeKind || "");
	if (kind === "price") return `${formatPresaleFilterNumber(value)}억`;
	if (kind === "households") return `${formatPresaleFilterNumber(value)}세대`;
	if (kind === "area" && dropdown.dataset.areaUnit === "py") {
		return `${formatPresaleFilterNumber(Number(value) / 3.3058, 1)}평`;
	}
	if (kind === "area") return `${formatPresaleFilterNumber(value)}m²`;
	return formatPresaleFilterNumber(value);
}

function syncPresaleAreaTickLabels(dropdown, menu)
{
	if (!dropdown || !menu || dropdown.dataset.rangeKind !== "area") return;
	const configMin = Number(dropdown.dataset.rangeMin) || 0;
	const configMax = Number(dropdown.dataset.rangeMax) || 0;
	menu.querySelectorAll("[data-presale-range-ticks] [data-range-value]").forEach((tick) => {
		const value = Number(tick.dataset.rangeValue);
		if (value === configMin) tick.textContent = "최소";
		else if (value === configMax) tick.textContent = "최대";
		else tick.textContent = formatPresaleRangeValue(dropdown, value);
	});
}

function getPresaleRangeThumbGapValue(dropdown, menu)
{
	if (!dropdown || !menu) return 1;
	const range = menu.querySelector("[data-presale-dual-range]");
	const width = range ? range.getBoundingClientRect().width : 0;
	const configMin = Number(dropdown.dataset.rangeMin) || 0;
	const configMax = Number(dropdown.dataset.rangeMax) || 0;
	const step = Math.max(Number(dropdown.dataset.rangeStep) || 1, 0.0001);
	if (!width || configMax <= configMin) return step;
	const pixelGapValue = (26 / width) * (configMax - configMin);
	return Math.max(step, Math.ceil(pixelGapValue / step) * step);
}

function clampPresaleRangeValues(dropdown, menu, changedInput = null)
{
	const minInput = menu && menu.querySelector("[data-presale-range-min]");
	const maxInput = menu && menu.querySelector("[data-presale-range-max]");
	if (!dropdown || !minInput || !maxInput) return null;
	const configMin = Number(dropdown.dataset.rangeMin) || 0;
	const configMax = Number(dropdown.dataset.rangeMax) || 0;
	const step = Math.max(Number(dropdown.dataset.rangeStep) || 1, 0.0001);
	const gap = getPresaleRangeThumbGapValue(dropdown, menu);
	let minValue = Math.max(configMin, Math.min(configMax, Number(minInput.value)));
	let maxValue = Math.max(configMin, Math.min(configMax, Number(maxInput.value)));
	if (changedInput === minInput) minValue = Math.min(minValue, maxValue - gap);
	else if (changedInput === maxInput) maxValue = Math.max(maxValue, minValue + gap);
	else if (minValue > maxValue - gap) maxValue = Math.min(configMax, minValue + gap);
	minValue = Math.max(configMin, Math.round(minValue / step) * step);
	maxValue = Math.min(configMax, Math.round(maxValue / step) * step);
	minInput.value = String(minValue);
	maxInput.value = String(maxValue);
	return { minInput, maxInput, minValue, maxValue, configMin, configMax, step, gap };
}

function syncPresaleRangeUI(dropdown, changedInput = null)
{
	if (!dropdown || !dropdown.hasAttribute("data-presale-range-dropdown")) return;
	const menu = getMapFilterDropdownMenu(dropdown);
	if (!menu) return;
	const values = clampPresaleRangeValues(dropdown, menu, changedInput);
	if (!values) return;
	const { minValue, maxValue, configMin, configMax, step } = values;

	const span = Math.max(configMax - configMin, 1);
	const minPercent = ((minValue - configMin) / span) * 100;
	const maxPercent = ((maxValue - configMin) / span) * 100;
	const fill = menu.querySelector("[data-presale-range-fill]");
	if (fill) {
		fill.style.left = `${Math.max(0, Math.min(100, minPercent))}%`;
		fill.style.right = `${Math.max(0, Math.min(100, 100 - maxPercent))}%`;
	}

	const isDefault = minValue <= configMin && maxValue >= configMax;
	const summary = menu.querySelector("[data-presale-range-summary]");
	if (summary) {
		const minLabel = minValue <= configMin ? "최소" : formatPresaleRangeValue(dropdown, minValue);
		const maxLabel = maxValue >= configMax ? "최대" : formatPresaleRangeValue(dropdown, maxValue);
		summary.textContent = isDefault ? "전체" : `${minLabel} ~ ${maxLabel}`;
	}

	const baseLabel = String(dropdown.querySelector("[data-presale-filter-trigger]")?.dataset.baseLabel || "").trim();
	const triggerLabel = dropdown.querySelector("[data-presale-trigger-label]");
	if (triggerLabel) triggerLabel.textContent = isDefault ? baseLabel : `${baseLabel} +1`;
	dropdown.classList.toggle("has-active", !isDefault);

	const manualMin = menu.querySelector("[data-presale-manual-min]");
	const manualMax = menu.querySelector("[data-presale-manual-max]");
	if (manualMin && manualMax) {
		const usesPy = dropdown.dataset.rangeKind === "area" && dropdown.dataset.areaUnit === "py";
		manualMin.min = "0";
		manualMax.min = "0";
		manualMin.max = usesPy ? String(Number((configMax / 3.3058).toFixed(1))) : String(configMax);
		manualMax.max = manualMin.max;
		manualMin.step = usesPy ? "0.1" : String(step);
		manualMax.step = manualMin.step;
		manualMin.value = usesPy ? String(Number((minValue / 3.3058).toFixed(1))) : String(minValue);
		manualMax.value = usesPy ? String(Number((maxValue / 3.3058).toFixed(1))) : String(maxValue);
	}
	syncPresaleAreaTickLabels(dropdown, menu);
}

function syncPresaleFilterDropdownSummary(dropdown)
{
	if (!dropdown) return;
	if (dropdown.hasAttribute("data-presale-range-dropdown")) {
		syncPresaleRangeUI(dropdown);
		return;
	}
	const menu = getMapFilterDropdownMenu(dropdown);
	if (!menu) return;
	const selected = [...menu.querySelectorAll("[data-presale-option].active")]
		.filter(option => String(option.dataset.value || "") !== "");
	menu.querySelectorAll("[data-presale-option]").forEach((option) => {
		option.setAttribute("aria-pressed", option.classList.contains("active") ? "true" : "false");
	});
	const trigger = dropdown.querySelector("[data-presale-filter-trigger]");
	const label = dropdown.querySelector("[data-presale-trigger-label]");
	const baseLabel = String(trigger && trigger.dataset.baseLabel || "").trim();
	if (label) label.textContent = selected.length ? `${baseLabel} +${selected.length}` : baseLabel;
	dropdown.classList.toggle("has-active", selected.length > 0);
}

function syncPresaleOptionGroup(menu, group)
{
	if (!menu || !group) return;
	const options = [...menu.querySelectorAll("[data-presale-option]")]
		.filter(option => option.dataset.group === group);
	const allOption = options.find(option => String(option.dataset.value || "") === "");
	const selected = options.filter(option => String(option.dataset.value || "") !== "" && option.classList.contains("active"));
	if (!selected.length && allOption) allOption.classList.add("active");
	if (selected.length && allOption) allOption.classList.remove("active");
	options.forEach((option) => {
		option.setAttribute("aria-pressed", option.classList.contains("active") ? "true" : "false");
	});
}

function closePresaleMapFilters()
{
	document.querySelectorAll("[data-presale-filter-dropdown]").forEach((dropdown) => {
		dropdown.classList.remove("open");
		const trigger = dropdown.querySelector("[data-presale-filter-trigger]");
		if (trigger) trigger.setAttribute("aria-expanded", "false");
		const menu = getMapFilterDropdownMenu(dropdown);
		if (menu) menu.setAttribute("aria-hidden", "true");
	});
	if (typeof syncFloatingMapFilterMenus === "function") syncFloatingMapFilterMenus();
}

function handlePresaleMapFilterClick(event)
{
	if (!isPresaleMapMode()) return;
	const target = event && event.target;
	if (!target || typeof target.closest !== "function") return;

	const trigger = target.closest("[data-presale-filter-trigger]");
	if (trigger) {
		const dropdown = getPresaleFilterOwnerDropdown(trigger);
		if (!dropdown) return;
		event.preventDefault();
		event.stopPropagation();
		const willOpen = !dropdown.classList.contains("open");
		closeMapFilterDropdownsExcept(willOpen ? dropdown.id : null);
		dropdown.classList.toggle("open", willOpen);
		trigger.setAttribute("aria-expanded", willOpen ? "true" : "false");
		const menu = getMapFilterDropdownMenu(dropdown);
		if (menu) menu.setAttribute("aria-hidden", willOpen ? "false" : "true");
		if (willOpen) syncOpenMapFilterMenuPosition(dropdown);
		else if (typeof syncFloatingMapFilterMenus === "function") syncFloatingMapFilterMenus();
		return;
	}

	const manualToggle = target.closest("[data-presale-manual-toggle]");
	if (manualToggle) {
		const menu = manualToggle.closest("[data-presale-filter-menu]");
		const row = menu ? menu.querySelector("[data-presale-manual-row]") : null;
		if (!row) return;
		event.preventDefault();
		event.stopPropagation();
		row.hidden = !row.hidden;
		manualToggle.setAttribute("aria-expanded", row.hidden ? "false" : "true");
		return;
	}

	const areaUnitToggle = target.closest("[data-presale-area-unit]");
	if (areaUnitToggle) {
		const dropdown = getPresaleFilterOwnerDropdown(areaUnitToggle);
		if (!dropdown) return;
		event.preventDefault();
		event.stopPropagation();
		const nextUnit = dropdown.dataset.areaUnit === "py" ? "m2" : "py";
		dropdown.dataset.areaUnit = nextUnit;
		const label = areaUnitToggle.querySelector("span");
		if (label) label.textContent = nextUnit === "py" ? "m²" : "평";
		syncPresaleRangeUI(dropdown);
		return;
	}

	const manualApply = target.closest("[data-presale-manual-apply]");
	if (manualApply) {
		const dropdown = getPresaleFilterOwnerDropdown(manualApply);
		const menu = manualApply.closest("[data-presale-filter-menu]");
		if (!dropdown || !menu) return;
		event.preventDefault();
		event.stopPropagation();
		const minInput = menu.querySelector("[data-presale-range-min]");
		const maxInput = menu.querySelector("[data-presale-range-max]");
		const manualMin = menu.querySelector("[data-presale-manual-min]");
		const manualMax = menu.querySelector("[data-presale-manual-max]");
		if (!minInput || !maxInput || !manualMin || !manualMax) return;
		const configMin = Number(dropdown.dataset.rangeMin) || 0;
		const configMax = Number(dropdown.dataset.rangeMax) || 0;
		const usesPy = dropdown.dataset.rangeKind === "area" && dropdown.dataset.areaUnit === "py";
		let minValue = Number(manualMin.value);
		let maxValue = Number(manualMax.value);
		if (usesPy) {
			minValue *= 3.3058;
			maxValue *= 3.3058;
		}
		minValue = Math.max(configMin, Math.min(configMax, Number.isFinite(minValue) ? minValue : configMin));
		maxValue = Math.max(configMin, Math.min(configMax, Number.isFinite(maxValue) ? maxValue : configMax));
		if (minValue > maxValue) [minValue, maxValue] = [maxValue, minValue];
		minInput.value = String(Math.round(minValue));
		maxInput.value = String(Math.round(maxValue));
		syncPresaleRangeUI(dropdown);
		const row = menu.querySelector("[data-presale-manual-row]");
		if (row) row.hidden = true;
		const toggle = menu.querySelector("[data-presale-manual-toggle]");
		if (toggle) toggle.setAttribute("aria-expanded", "false");
		return;
	}

	const option = target.closest("[data-presale-option]");
	if (!option) return;
	const dropdown = getPresaleFilterOwnerDropdown(option);
	const menu = option.closest("[data-presale-filter-menu]");
	if (!dropdown || !menu) return;
	event.preventDefault();
	event.stopPropagation();
	const group = String(option.dataset.group || "");
	const groupOptions = [...menu.querySelectorAll("[data-presale-option]")]
		.filter(candidate => candidate.dataset.group === group);
	if (String(option.dataset.value || "") === "") {
		groupOptions.forEach(candidate => candidate.classList.toggle("active", candidate === option));
	} else {
		option.classList.toggle("active");
	}
	syncPresaleOptionGroup(menu, group);
	syncPresaleFilterDropdownSummary(dropdown);
}

function handlePresaleRangeInput(event)
{
	const input = event && event.target;
	if (!input || typeof input.matches !== "function") return;
	if (!input.matches("[data-presale-range-min], [data-presale-range-max]")) return;
	const dropdown = getPresaleFilterOwnerDropdown(input);
	if (!dropdown) return;
	syncPresaleRangeUI(dropdown, input);
}

function handlePresaleRangePointerDown(event)
{
	if (!isPresaleMapMode() || !event || (typeof event.button === "number" && event.button !== 0)) return;
	const range = event.target && event.target.closest ? event.target.closest("[data-presale-dual-range]") : null;
	if (!range) return;
	const dropdown = getPresaleFilterOwnerDropdown(range);
	const menu = range.closest("[data-presale-filter-menu]");
	if (!dropdown || !menu) return;
	const values = clampPresaleRangeValues(dropdown, menu);
	if (!values) return;
	const rect = range.getBoundingClientRect();
	if (!rect.width) return;
	const pointerX = event.clientX;
	const span = Math.max(values.configMax - values.configMin, values.step);
	const minX = rect.left + ((values.minValue - values.configMin) / span) * rect.width;
	const maxX = rect.left + ((values.maxValue - values.configMin) / span) * rect.width;
	if (Math.min(Math.abs(pointerX - minX), Math.abs(pointerX - maxX)) <= 18) return;
	event.preventDefault();
	event.stopPropagation();
	const ratio = Math.max(0, Math.min(1, (pointerX - rect.left) / rect.width));
	const rawValue = values.configMin + ratio * span;
	const nextValue = Math.round(rawValue / values.step) * values.step;
	const target = Math.abs(nextValue - values.minValue) <= Math.abs(values.maxValue - nextValue)
		? values.minInput
		: values.maxInput;
	target.value = String(nextValue);
	syncPresaleRangeUI(dropdown, target);
}

function initializePresaleMapFilters()
{
	const wrapper = document.getElementById("presaleMapFilterBar");
	if (!wrapper) return;
	wrapper.querySelectorAll("[data-presale-group]").forEach((groupElement) => {
		syncPresaleOptionGroup(groupElement.closest("[data-presale-filter-menu]"), groupElement.dataset.presaleGroup);
	});
	wrapper.querySelectorAll("[data-presale-filter-dropdown]").forEach((dropdown) => {
		syncPresaleFilterDropdownSummary(dropdown);
	});
	if (document.documentElement.dataset.presaleMapFiltersBound === "true") return;
	document.documentElement.dataset.presaleMapFiltersBound = "true";
	document.addEventListener("click", handlePresaleMapFilterClick, true);
	document.addEventListener("input", handlePresaleRangeInput, true);
	document.addEventListener("pointerdown", handlePresaleRangePointerDown, true);
}

function openPresaleMapMode()
{
	initializePresaleMapFilters();
	closeMapFilterDropdownsExcept(null);
	document.body.classList.add("presale-page-open");
	document.body.classList.remove("my-suite-favorites-tab-open");
	syncRealjejuPageTopbarSearchLabels();
	renderPresaleEmptyMap();
	if (typeof scheduleMapFilterScrollSyncBurst === "function") scheduleMapFilterScrollSyncBurst();
}

function closePresaleMapMode()
{
	const wasOpen = isPresaleMapMode();
	closePresaleMapFilters();
	document.body.classList.remove("presale-page-open");
	if (wasOpen && typeof applyFilter === "function") {
		applyFilter();
	}
}

window.realjejuOpenPresaleMapMode = openPresaleMapMode;

window.realjejuClosePresaleMapMode = closePresaleMapMode;

function rememberCollapsedMapPanelForHome()
{
	if (document.body.classList.contains("map-panels-collapsed")) {
		restoreMapPanelsCollapsedOnHome = true;
	}
}

function openRealjejuWorkspacePage(routeKey, options = {})
{
	const normalizedRoute = normalizeRealjejuWorkspaceRouteKey(routeKey);
	if (!normalizedRoute) return null;

	const route = REALJEJU_WORKSPACE_ROUTE_CONFIG[normalizedRoute];
	const targetPanelId = options.panelId || route.panelIds[0];
	if (!targetPanelId) return null;

	closeRealjejuWorkspacePages(normalizedRoute);

	if (options.preserveSidebar !== true) {
		document.body.classList.add("sidebar-list-collapsed");
		if (typeof state !== "undefined" && state) state.isListOpen = false;
		if (sidebar) sidebar.classList.remove("expanded");
	}

	document.body.classList.add(route.bodyClass);
	(route.panelIds || []).forEach((panelId) => {
		const panel = document.getElementById(panelId);
		if (!panel) return;
		panel.setAttribute("aria-hidden", panelId === targetPanelId ? "false" : "true");
	});

	const panel = document.getElementById(targetPanelId);
	if (panel && options.scrollTop) panel.scrollTop = 0;
	return {
		...route,
		routeKey: normalizedRoute,
		panel: panel || null,
		targetPanelId
	};
}

function restoreCollapsedMapPanelOnHome()
{
	if (!restoreMapPanelsCollapsedOnHome || isRealjejuWorkspacePageOpen()) return;
	restoreMapPanelsCollapsedOnHome = false;
	if (sidebar) sidebar.classList.add("expanded");
	document.body.classList.remove("detail-page-panel-open");
	document.body.classList.add("map-panels-collapsed");
	const detailPanel = document.getElementById("sidebarDetailPanel");
	if (detailPanel) {
		detailPanel.style.display = "";
		detailPanel.style.opacity = "0";
		detailPanel.style.visibility = "hidden";
		detailPanel.style.pointerEvents = "none";
	}
	updateMapPanelToggleState();
	scheduleMapLayoutAfterPanelTransition();
}

window.toggleMapPropertyPanels = toggleMapPropertyPanels;

window.toggleMapPrimaryAction = toggleMapPrimaryAction;

if (document.body && typeof MutationObserver === "function") {
	const mapPrimaryCategoryObserver = new MutationObserver(function() {
		const category = getCurrentRealjejuGlobalCategoryKey();
		if (category !== "parcel" && isParcelLifeSafetyFilterPanelOpen()) {
			closeConvenienceFacilityFilterPanel();
		}
		if (category !== "parcel") {
			try {
				if (isLifeSafetyOverlayVisible) void setLifeSafetyOverlayVisible(false);
			} catch (_error) {}
		}
		syncMapPropertyToggleButton();
	});
	mapPrimaryCategoryObserver.observe(document.body, { attributes: true, attributeFilter: ["data-global-category"] });
}

window.setMapPropertyMarkersVisible = setMapPropertyMarkersVisible;

window.setMapPanelsCollapsed = setMapPanelsCollapsed;

function loadDaumPostcodeScript()
{
	if (window.daum && window.daum.Postcode) {
		return Promise.resolve(window.daum.Postcode);
	}

	if (daumPostcodeLoadPromise) {
		return daumPostcodeLoadPromise;
	}

	daumPostcodeLoadPromise = new Promise((resolve, reject) => {
		const existingScript = document.querySelector('script[data-realjeju-postcode="true"]');
		if (existingScript) {
			existingScript.addEventListener("load", () => {
				if (window.daum && window.daum.Postcode) {
					resolve(window.daum.Postcode);
					return;
				}
				reject(new Error("주소 검색 스크립트가 준비되지 않았습니다."));
			}, { once: true });
			existingScript.addEventListener("error", () => {
				reject(new Error("주소 검색 스크립트를 불러오지 못했습니다."));
			}, { once: true });
			return;
		}

		const script = document.createElement("script");
		script.src = "https://t1.daumcdn.net/mapjsapi/bundle/postcode/prod/postcode.v2.js";
		script.async = true;
		script.dataset.realjejuPostcode = "true";
		script.addEventListener("load", () => {
			if (window.daum && window.daum.Postcode) {
				resolve(window.daum.Postcode);
				return;
			}
			reject(new Error("주소 검색 스크립트가 준비되지 않았습니다."));
		}, { once: true });
		script.addEventListener("error", () => {
			reject(new Error("주소 검색 스크립트를 불러오지 못했습니다."));
		}, { once: true });
		document.head.appendChild(script);
	});

	return daumPostcodeLoadPromise;
}

function scheduleSupabaseScriptLoad()
{
	const run = () => {
		loadSupabaseScript()
		.then(() => {
			if (typeof window.realjejuInitAccountUI === "function") {
				window.realjejuInitAccountUI();
			}
		})
		.catch(err => {
			console.warn("Supabase 스크립트 로드 실패:", err);
		});
	};

	if (document.readyState === "complete") {
		run();
		return;
	}
	window.addEventListener("load", run, { once: true });
}

function hasFeatureLabel(item, label)
{
	const aliasTokens = [label, ...((FEATURE_ALIAS_MAP[label] || []))]
	.map(normalizeFeatureToken)
	.filter(Boolean);
	const featureTokens = Array.isArray(item?.featuresNormalized)
	? item.featuresNormalized
	: normalizeFeatureList(item?.features);
	const tokenSet = new Set(featureTokens);

	return aliasTokens.some(token => tokenSet.has(token));
}

function areaFilterToM2(value, unit = selectedAreaUnit)
{
	const number = Number(value);
	if (!Number.isFinite(number)) return null;
	return unit === "py" ? number * 3.3058 : number;
}

function areaFilterFromM2(value, unit = selectedAreaUnit)
{
	const number = Number(value);
	if (!Number.isFinite(number)) return null;
	return unit === "py" ? number / 3.3058 : number;
}

function getAreaFilterUnitMax(unit = selectedAreaUnit)
{
	if (selectedAreaLandOnly) return unit === "py" ? AREA_FILTER_LAND_MAX_PY : AREA_FILTER_LAND_MAX_M2;
	return unit === "py" ? AREA_FILTER_MAX_PY : AREA_FILTER_MAX_M2;
}

function getAreaFilterModeKey()
{
	return selectedAreaLandOnly ? "land" : "exclusive";
}

function saveCurrentAreaFilterRange(mode = getAreaFilterModeKey())
{
	const key = mode === "land" ? "land" : "exclusive";
	selectedAreaRangeByMode[key] = {
		minM2: Number.isFinite(selectedAreaMinM2) ? selectedAreaMinM2 : null,
		maxM2: selectedAreaMaxTouched && Number.isFinite(selectedAreaMaxM2) ? selectedAreaMaxM2 : AREA_FILTER_UNBOUNDED_MAX_M2,
		maxTouched: !!selectedAreaMaxTouched
	};
}

function loadAreaFilterRange(mode = getAreaFilterModeKey())
{
	const key = mode === "land" ? "land" : "exclusive";
	const range = selectedAreaRangeByMode[key] || {};
	selectedAreaMinM2 = Number.isFinite(range.minM2) ? range.minM2 : null;
	selectedAreaMaxTouched = !!range.maxTouched;
	selectedAreaMaxM2 = selectedAreaMaxTouched && Number.isFinite(range.maxM2) ? range.maxM2 : AREA_FILTER_UNBOUNDED_MAX_M2;
}

function switchAreaFilterMode(mode)
{
	const nextMode = mode === "land" ? "land" : "exclusive";
	const currentMode = getAreaFilterModeKey();
	saveCurrentAreaFilterRange(currentMode);
	selectedAreaLandOnly = nextMode === "land";
	selectedAreaExclusiveOnly = nextMode !== "land";
	loadAreaFilterRange(nextMode);
}

function resetAreaFilterRanges()
{
	selectedAreaRangeByMode.exclusive = { minM2: null, maxM2: AREA_FILTER_UNBOUNDED_MAX_M2, maxTouched: false };
	selectedAreaRangeByMode.land = { minM2: null, maxM2: AREA_FILTER_UNBOUNDED_MAX_M2, maxTouched: false };
	selectedAreaExclusiveOnly = true;
	selectedAreaLandOnly = false;
	loadAreaFilterRange("exclusive");
}

function formatAreaFilterNumber(value, unit = selectedAreaUnit)
{
	const number = Number(value);
	if (!Number.isFinite(number)) return "";
	return Math.round(number).toLocaleString("ko-KR");
}

function formatAreaFilterLabelFromM2(value, unit = selectedAreaUnit)
{
	const converted = areaFilterFromM2(value, unit);
	if (!Number.isFinite(converted)) return "";
	return `${formatAreaFilterNumber(converted, unit)}${unit === "py" ? "평" : "㎡"}`;
}

function getAreaFilterRangeLabel(fallback = "면적")
{
	const hasMin = Number.isFinite(selectedAreaMinM2);
	const hasMax = selectedAreaMaxTouched && Number.isFinite(selectedAreaMaxM2) && !isAreaFilterMaxUnbounded();
	if (!hasMin && !hasMax) return fallback;
	const prefix = selectedAreaExclusiveOnly && !selectedAreaLandOnly ? "전용 " : "";
	if (hasMin && hasMax) {
		return `${prefix}${formatAreaFilterLabelFromM2(selectedAreaMinM2)}~${formatAreaFilterLabelFromM2(selectedAreaMaxM2)}`;
	}
	if (hasMin) return `${prefix}${formatAreaFilterLabelFromM2(selectedAreaMinM2)} 이상`;
	return `${prefix}${formatAreaFilterLabelFromM2(selectedAreaMaxM2)} 이하`;
}

function getFiniteAreaNumber(value)
{
	const number = Number(String(value ?? "").replace(/,/g, ""));
	return Number.isFinite(number) && number > 0 ? number : null;
}

function getFirstFiniteAreaNumber(values)
{
	for (const value of values) {
		const number = getFiniteAreaNumber(value);
		if (Number.isFinite(number)) return number;
	}
	return null;
}

function pushFiniteAreaNumber(target, value, unit = "m2")
{
	const number = getFiniteAreaNumber(value);
	if (!Number.isFinite(number)) return;
	target.push(unit === "py" ? number * 3.3058 : number);
}

function pushAreaTextValues(target, value)
{
	parseAreaNumbers(value).forEach((area) => pushFiniteAreaNumber(target, area));
}

function collectAreaTextCandidates(value, target)
{
	if (value === null || value === undefined) return;
	if (typeof value === "string" || typeof value === "number") {
		target.push(String(value));
		return;
	}
	if (Array.isArray(value)) {
		value.forEach((entry) => collectAreaTextCandidates(entry, target));
		return;
	}
	if (typeof value !== "object") return;
	["label", "name", "title", "value", "text", "display", "description", "area", "areaText", "m2_text", "py_text", "m2Text", "pyText"].forEach((key) => {
		if (Object.prototype.hasOwnProperty.call(value, key)) collectAreaTextCandidates(value[key], target);
	});
}

function isAreaFilterLandItem(item)
{
	const payload = item?.payload && typeof item.payload === "object" ? item.payload : {};
	const typeText = [
		item?.type,
		item?.propertyType,
		item?.category,
		payload?.type,
		payload?.property_type,
		payload?.category
	].map(value => String(value || "")).join(" ");
	return /\bland\b|토지|임야|대지|과수원|목장용지|(?:^|\s)(?:전|답)(?:\s|$)/i.test(typeText);
}

function getItemAreaFilterValuesM2(item, exclusiveOnly = selectedAreaExclusiveOnly)
{
	if (selectedAreaLandOnly && !isAreaFilterLandItem(item)) return [];
	const values = [];
	const payload = item?.payload && typeof item.payload === "object" ? item.payload : {};
	const areas = payload.areas && typeof payload.areas === "object" ? payload.areas : {};
	const textCandidates = [];

	[
		item?.area,
		item?.areaText,
		item?.displayArea,
		item?.cardArea,
		item?.description,
		item?.desc,
		item?.summary,
		item?.title,
		item?.type,
		item?.payload?.description,
		item?.payload?.desc,
		item?.payload?.title
	].forEach((entry) => collectAreaTextCandidates(entry, textCandidates));
	collectAreaTextCandidates(item?.infoRows, textCandidates);
	collectAreaTextCandidates(item?.sections, textCandidates);
	collectAreaTextCandidates(areas?.area_items, textCandidates);
	collectAreaTextCandidates(payload?.form_state?.areaItems, textCandidates);
	textCandidates.forEach((text) => pushAreaTextValues(values, text));

	const structuredKeys = selectedAreaLandOnly
		? ["land"]
		: exclusiveOnly
		? ["exclusive"]
		: ["supply", "total", "building", "land", "exclusive"];
	structuredKeys.forEach((key) => {
		pushFiniteAreaNumber(values, areas[`${key}_m2`], "m2");
		pushFiniteAreaNumber(values, areas[`${key}_py`], "py");
	});

	const areaItems = [
		...(Array.isArray(areas?.area_items) ? areas.area_items : []),
		...(Array.isArray(payload?.form_state?.areaItems) ? payload.form_state.areaItems : [])
	];
	areaItems.forEach((entry) => {
		if (!entry || typeof entry !== "object") return;
		if (selectedAreaLandOnly && getAreaKeyFromLabel(entry.label) !== "land" && String(entry.key || "") !== "land") return;
		if (!selectedAreaLandOnly && exclusiveOnly && getAreaKeyFromLabel(entry.label) !== "exclusive" && String(entry.key || "") !== "exclusive") return;
		["m2", "m2_value", "value_m2", "area_m2"].forEach((key) => pushFiniteAreaNumber(values, entry[key], "m2"));
		["py", "py_value", "value_py", "area_py"].forEach((key) => pushFiniteAreaNumber(values, entry[key], "py"));
	});

	return [...new Set(values.map((value) => Math.round(value * 10000) / 10000))]
		.filter((value) => Number.isFinite(value) && value > 0);
}

function getItemAreaFilterValueM2(item, exclusiveOnly = selectedAreaExclusiveOnly)
{
	if (selectedAreaLandOnly && !isAreaFilterLandItem(item)) return null;
	const payload = item?.payload && typeof item.payload === "object" ? item.payload : {};
	const areas = payload.areas && typeof payload.areas === "object" ? payload.areas : {};
	const rawArea = item?.area || "";
	const parsedApartment = parseApartmentAreas(rawArea);
	const parsedDetached = parseDetachedHouseAreas(rawArea);
	const cardAreaValue = getFirstFiniteAreaNumber(parseAreaNumbers(rawArea));
	const anyStoredAreaValue = getFirstFiniteAreaNumber([
		areas.supply_m2,
		areas.total_m2,
		areas.building_m2,
		areas.land_m2,
		areas.exclusive_m2,
		Number.isFinite(getFiniteAreaNumber(areas.supply_py)) ? getFiniteAreaNumber(areas.supply_py) * 3.3058 : null,
		Number.isFinite(getFiniteAreaNumber(areas.total_py)) ? getFiniteAreaNumber(areas.total_py) * 3.3058 : null,
		Number.isFinite(getFiniteAreaNumber(areas.building_py)) ? getFiniteAreaNumber(areas.building_py) * 3.3058 : null,
		Number.isFinite(getFiniteAreaNumber(areas.land_py)) ? getFiniteAreaNumber(areas.land_py) * 3.3058 : null,
		Number.isFinite(getFiniteAreaNumber(areas.exclusive_py)) ? getFiniteAreaNumber(areas.exclusive_py) * 3.3058 : null
	]);

	const exclusiveValue = getFirstFiniteAreaNumber([
		areas.exclusive_m2,
		Number.isFinite(getFiniteAreaNumber(areas.exclusive_py)) ? getFiniteAreaNumber(areas.exclusive_py) * 3.3058 : null,
		parsedApartment.private,
		findCardLabeledAreaValue(rawArea, [/전용\s*(?:면적)?\s*([\d,.]+)\s*(?:㎡|평)?/])
	]);
	const landValue = getFirstFiniteAreaNumber([
		areas.land_m2,
		Number.isFinite(getFiniteAreaNumber(areas.land_py)) ? getFiniteAreaNumber(areas.land_py) * 3.3058 : null,
		parsedDetached.land,
		cardAreaValue
	]);

	if (selectedAreaLandOnly) return Number.isFinite(landValue) ? landValue : null;
	if (exclusiveOnly && Number.isFinite(exclusiveValue)) return exclusiveValue;
	if (!exclusiveOnly) {
		if (Number.isFinite(cardAreaValue)) return cardAreaValue;
		if (Number.isFinite(anyStoredAreaValue)) return anyStoredAreaValue;
	}

	const representativeValue = getFirstFiniteAreaNumber([
		cardAreaValue,
		anyStoredAreaValue,
		areas.supply_m2,
		areas.total_m2,
		areas.building_m2,
		areas.land_m2,
		Number.isFinite(getFiniteAreaNumber(areas.supply_py)) ? getFiniteAreaNumber(areas.supply_py) * 3.3058 : null,
		Number.isFinite(parsedApartment.supply) ? parsedApartment.supply : null,
		Number.isFinite(parsedDetached.total) ? parsedDetached.total : null,
		Number.isFinite(parsedDetached.land) ? parsedDetached.land : null,
		getPrimaryAreaForUnitPrice(rawArea, item?.type || "")
	]);

	return Number.isFinite(representativeValue) ? representativeValue : exclusiveValue;
}

function matchesAreaFilter(item)
{
	const hasMaxFilter = selectedAreaMaxTouched && Number.isFinite(selectedAreaMaxM2) && !isAreaFilterMaxUnbounded();
	if (!Number.isFinite(selectedAreaMinM2) && !hasMaxFilter) {
		return selectedAreaLandOnly ? isAreaFilterLandItem(item) : true;
	}
	if (selectedAreaLandOnly && !isAreaFilterLandItem(item)) return false;
	const representativeValue = getItemAreaFilterValueM2(item, selectedAreaExclusiveOnly);
	const values = Number.isFinite(representativeValue)
		? [representativeValue]
		: getItemAreaFilterValuesM2(item, selectedAreaExclusiveOnly);
	return values.some((value) => {
		if (!Number.isFinite(value)) return false;
		if (Number.isFinite(selectedAreaMinM2) && value < selectedAreaMinM2) return false;
		if (hasMaxFilter && value > selectedAreaMaxM2) return false;
		return true;
	});
}

function matchesLandTypeFilter(item, selectedValues)
{
	if (!(selectedValues instanceof Set) || selectedValues.size === 0) return true;
	const tokens = getItemLandTypeTokens(item);
	if (!tokens.size) return false;
	return Array.from(selectedValues).some(value => tokens.has(normalizeLandTypeFilterValue(value)));
}

function addLandUseZoneCandidateToken(tokens, value)
{
	const normalized = normalizeLandUseZoneFilterValue(value);
	if (!normalized) return;
	const exactValue = LAND_USE_ZONE_FILTER_NORMALIZED_TO_VALUE.get(normalized);
	if (exactValue) {
		tokens.add(exactValue);
		return;
	}
	LAND_USE_ZONE_FILTER_VALUES.forEach(zoneValue => {
		const zoneNormalized = normalizeLandUseZoneFilterValue(zoneValue);
		if (zoneNormalized && normalized.includes(zoneNormalized)) tokens.add(zoneValue);
	});
}

function getItemLandUseZoneTokens(item)
{
	const tokens = new Set();
	const payload = item?.payload && typeof item.payload === "object" ? item.payload : {};
	const areas = payload.areas && typeof payload.areas === "object" ? payload.areas : {};
	const land = payload.land && typeof payload.land === "object" ? payload.land : {};
	const formState = payload.form_state && typeof payload.form_state === "object" ? payload.form_state : {};
	const formInputs = formState.inputs && typeof formState.inputs === "object" ? formState.inputs : {};
	[
		item?.landUseZone,
		item?.land_use_zone,
		item?.landUseZoneLabel,
		item?.land_use_zone_label,
		areas.land_use_zone,
		areas.landUseZone,
		land.land_use_zone,
		land.landUseZone,
		payload.land_use_zone,
		payload.landUseZone,
		payload.land_use_zone_label,
		payload.landUseZoneLabel,
		formInputs.land_use_zone,
		formInputs.landUseZone,
		formInputs.landUseZoneSelect
	].forEach(value => addLandUseZoneCandidateToken(tokens, value));
	return tokens;
}

function matchesLandUseZoneFilter(item, selectedValues)
{
	if (!(selectedValues instanceof Set) || selectedValues.size === 0) return true;
	const tokens = getItemLandUseZoneTokens(item);
	if (!tokens.size) return false;
	return Array.from(selectedValues).some(value => tokens.has(value));
}

function parseApprovalDateValue(value)
{
	const raw = String(value || "").trim();
	if (!raw) return null;
	const match = raw.match(/^(\d{4})(?:[-./년\s]*(\d{1,2})?)?(?:[-./월\s]*(\d{1,2})?)?/);
	if (match) {
		const year = Number(match[1]);
		const month = match[2] ? Number(match[2]) : 1;
		const day = match[3] ? Number(match[3]) : 1;
		if (Number.isFinite(year) && year >= 1900) {
			const date = new Date(year, Math.max(0, month - 1), Math.max(1, day));
			return Number.isNaN(date.getTime()) ? null : date;
		}
	}
	const date = new Date(raw);
	return Number.isNaN(date.getTime()) ? null : date;
}

function getApprovalAgeYearsFromDate(date, now = new Date())
{
	if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
	const today = now instanceof Date && !Number.isNaN(now.getTime()) ? now : new Date();
	let age = today.getFullYear() - date.getFullYear();
	const beforeAnniversary = today.getMonth() < date.getMonth()
		|| (today.getMonth() === date.getMonth() && today.getDate() < date.getDate());
	if (beforeAnniversary) age -= 1;
	return Math.max(0, age);
}

function getItemApprovalAgeYears(item)
{
	const dateValue = getItemApprovalDateValue(item);
	return getApprovalAgeYearsFromDate(parseApprovalDateValue(dateValue));
}

function matchesApprovalYearFilter(item)
{
	if (!Number.isFinite(selectedApprovalYearMinAge) && !Number.isFinite(selectedApprovalYearMaxAge)) return true;
	const age = getItemApprovalAgeYears(item);
	if (!Number.isFinite(age)) return false;
	if (Number.isFinite(selectedApprovalYearMinAge) && age < selectedApprovalYearMinAge) return false;
	if (Number.isFinite(selectedApprovalYearMaxAge) && age > selectedApprovalYearMaxAge) return false;
	return true;
}

