function setHeroSlide(index)
{
	if (!currentHeroImages.length) return;
	currentHeroIndex = (index + currentHeroImages.length) % currentHeroImages.length;
	ensureDetailHeroSlide(currentHeroIndex);

	const slides = detailHeroSlides.querySelectorAll(".detail-hero-slide");
	slides.forEach((slide, i) => {
		slide.classList.toggle("active", Number(slide.dataset.heroIndex) === currentHeroIndex);
	});

	const displayTotal = Math.max(currentHeroImages.length, currentHeroImageTotalCount || 0);
	detailHeroDots.textContent = detailHero.classList.contains("detail-hero-preview-grid")
		? `${displayTotal || currentHeroImages.length}`
		: `${currentHeroIndex + 1} / ${displayTotal || currentHeroImages.length}`;
	detailHero.style.backgroundImage = `url('${escapeHtml(currentHeroImages[currentHeroIndex])}')`;
}

function openDetailImageLightbox()
{
	if (document.body.classList.contains("map-panels-collapsed")) return;
	if (!currentHeroImages.length) return;
	if (typeof window.realjejuCloseGlobalTopbarTransientUi === "function") {
		window.realjejuCloseGlobalTopbarTransientUi();
	}
	if (detailImageLightbox && detailImageLightbox.parentElement !== document.body) document.body.appendChild(detailImageLightbox);
	detailImageLightbox.classList.add("open");
	document.body.classList.add("detail-image-lightbox-open");
	if (typeof window.realjejuSyncGlobalDetailSurfaceState === "function") {
		window.realjejuSyncGlobalDetailSurfaceState();
	}
	document.body.style.overflow = "hidden";
	renderDetailImageLightboxInfo();
	renderDetailImageLightboxThumbnails();
	updateLightboxImage();
}

function closeDetailImageLightbox()
{
	detailLightboxImageLoadSequence += 1;
	detailImageLightbox.classList.remove("open");
	document.body.classList.remove("detail-image-lightbox-open");
	detailImageLightboxImg.src = "";
	if (detailImageLightboxThumbnails) detailImageLightboxThumbnails.innerHTML = "";
	document.body.style.overflow = "";
	if (typeof window.realjejuSyncGlobalDetailSurfaceState === "function") {
		window.realjejuSyncGlobalDetailSurfaceState();
	}
}

function renderDetailImageLightboxInfo()
{
	const item = currentDetailItem || {};
	const title = sanitizePublicListingText(item.title || "매물 사진", item);
	const payload = item.payload && typeof item.payload === "object" ? item.payload : {};
	const registrant = payload.registrant && typeof payload.registrant === "object" ? payload.registrant : {};
	const office = String(item.agentOffice || registrant.office_name || payload.office_name || "개인 매물").trim();
	const rawDate = formatDetailSummaryDate(getListingRegistrationDateSource(item));
	const dateText = rawDate === "-" ? "" : rawDate.replace(/-/g, ".");
	if (detailImageLightboxTitle) detailImageLightboxTitle.textContent = title;
	if (detailImageLightboxMeta) detailImageLightboxMeta.textContent = [office, dateText].filter(Boolean).join(" | ");
	if (detailImageLightboxImg) detailImageLightboxImg.alt = title ? `${title} 확대 사진` : "매물 사진 확대";
}

function renderDetailImageLightboxThumbnails()
{
	if (!detailImageLightboxThumbnails) return;
	const title = String(detailImageLightboxTitle?.textContent || "매물").trim();
	detailImageLightboxThumbnails.innerHTML = currentHeroImages.map((imageUrl, index) => {
		const thumbnailUrl = currentHeroThumbnailImages[index] || imageUrl;
		return `
			<button type="button" class="detail-image-lightbox-thumbnail${index === currentHeroIndex ? " active" : ""}" data-lightbox-index="${index}" aria-label="${escapeHtml(title)} ${index + 1}번째 사진 보기" aria-current="${index === currentHeroIndex ? "true" : "false"}">
				<img src="${escapeHtml(thumbnailUrl)}" alt="" loading="lazy" decoding="async" fetchpriority="low">
			</button>
		`;
	}).join("");
	detailImageLightboxThumbnails.style.display = currentHeroImages.length > 1 ? "flex" : "none";
}

function syncDetailImageLightboxThumbnailSelection()
{
	if (!detailImageLightboxThumbnails) return;
	detailImageLightboxThumbnails.querySelectorAll("[data-lightbox-index]").forEach((button) => {
		const active = Number(button.dataset.lightboxIndex) === currentHeroIndex;
		button.classList.toggle("active", active);
		button.setAttribute("aria-current", active ? "true" : "false");
		if (active) button.scrollIntoView({ block: "nearest", inline: "nearest", behavior: "smooth" });
	});
}

function updateLightboxImage()
{
	if (!currentHeroImages.length) return;

	const requestedIndex = currentHeroIndex;
	const requestSequence = ++detailLightboxImageLoadSequence;
	const originalUrl = currentHeroImages[requestedIndex];
	const thumbnailUrl = currentHeroThumbnailImages[requestedIndex] || originalUrl;

	// 인접 프리로드 범위 밖의 사진을 직접 누른 경우에는 이미 받은 작은 썸네일을 즉시 표시하고,
	// 선택 원본이 디코딩된 뒤 같은 img의 src만 교체해 빈 화면이나 레이아웃 이동을 만들지 않습니다.
	detailImageLightboxImg.src = detailPhotoDecodedUrls.has(originalUrl) ? originalUrl : thumbnailUrl;
	if (originalUrl !== thumbnailUrl && !detailPhotoDecodedUrls.has(originalUrl)) {
		void preloadDecodedDetailPhoto(originalUrl).then((decoded) => {
			if (!decoded || requestSequence !== detailLightboxImageLoadSequence) return;
			if (!detailImageLightbox?.classList.contains("open") || currentHeroIndex !== requestedIndex) return;
			detailImageLightboxImg.src = originalUrl;
		});
	}
	prefetchDetailPhotoWindow(currentHeroImages, currentHeroIndex);
	const hasMultiple = currentHeroImages.length > 1;
	detailImageLightboxPrev.style.display = hasMultiple ? "flex" : "flex";
	detailImageLightboxNext.style.display = hasMultiple ? "flex" : "flex";
	detailImageLightboxPrev.style.visibility = hasMultiple ? "visible" : "hidden";
	detailImageLightboxNext.style.visibility = hasMultiple ? "visible" : "hidden";
	if (detailImageLightboxCount) {
		detailImageLightboxCount.textContent = `${currentHeroIndex + 1} / ${currentHeroImages.length}`;
		detailImageLightboxCount.style.display = "flex";
	}
	syncDetailImageLightboxThumbnailSelection();
}

function nextLightboxImage()
{
	if (!currentHeroImages.length) return;
	setHeroSlide(currentHeroIndex + 1);
	updateLightboxImage();
}

function prevLightboxImage()
{
	if (!currentHeroImages.length) return;
	setHeroSlide(currentHeroIndex - 1);
	updateLightboxImage();
}

function getParcelTradeCanvasDistanceMeters(lat1, lng1, lat2, lng2)
{
	const toRadians = (value) => Number(value) * Math.PI / 180;
	const dLat = toRadians(Number(lat2) - Number(lat1));
	const dLng = toRadians(Number(lng2) - Number(lng1));
	const firstLat = toRadians(lat1);
	const secondLat = toRadians(lat2);
	const haversine = Math.sin(dLat / 2) ** 2
		+ Math.cos(firstLat) * Math.cos(secondLat) * Math.sin(dLng / 2) ** 2;
	return 6371000 * 2 * Math.atan2(Math.sqrt(haversine), Math.sqrt(Math.max(0, 1 - haversine)));
}

window.__realjejuGetParcelTradeCanvasNearbyRows = function(options)
{
	const source = options && typeof options === "object" ? options : {};
	const lat = Number(source.lat);
	const lng = Number(source.lng);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return [];
	const radiusMeters = Math.min(5000, Math.max(1, Number(source.radiusMeters) || 500));
	const limit = Math.min(200, Math.max(1, Number(source.limit) || 100));
	const excludePnu = String(source.excludePnu || "").replace(/\D/g, "");
	return parcelTradeCanvasRows
		.filter((row) => !excludePnu || String(row?.pnu || "").replace(/\D/g, "") !== excludePnu)
		.map((row) => ({
			...row,
			amountManWon: getParcelTradeCanvasAmountManWon(row),
			distance: getParcelTradeCanvasDistanceMeters(lat, lng, row.lat, row.lng)
		}))
		.filter((row) => Number.isFinite(row.distance) && row.distance <= radiusMeters)
		.sort((left, right) => left.distance - right.distance
			|| String(right.dealDate || "").localeCompare(String(left.dealDate || "")))
		.slice(0, limit);
};

