async function recoverBrokerOfficeProfileImageElement(img, fallbackUrl = REALJEJU_AGENT_FALLBACK_IMAGE)
{
	if (!img) return;
	const useFallback = () => {
		img.onerror = null;
		if (fallbackUrl) img.src = fallbackUrl;
	};
	if (img.dataset.realjejuProfileRecovery === "done") {
		useFallback();
		return;
	}
	const failedUrl = String(img.currentSrc || img.src || "").trim();
	const userId = normalizeItemId(img.dataset && img.dataset.brokerUserId)
		|| getBrokerProfileUserIdFromStorageUrl(failedUrl);
	if (!userId) {
		useFallback();
		return;
	}
	img.dataset.realjejuProfileRecovery = "loading";
	const recoveredUrl = await resolveLatestBrokerProfileImageFromStorage(userId);
	if (!recoveredUrl || recoveredUrl === failedUrl) {
		img.dataset.realjejuProfileRecovery = "done";
		useFallback();
		return;
	}
	applyRecoveredBrokerProfileImage(userId, recoveredUrl);
	img.dataset.realjejuProfileRecovery = "done";
	img.src = recoveredUrl;
}

if (typeof window !== "undefined") {
	window.realjejuRecoverBrokerProfileImageElement = recoverBrokerOfficeProfileImageElement;
}

async function backfillBrokerOfficeLocationLatLng()
{
	if (state.isBrokerOfficeLocationBackfillRunning) {
		console.warn("중개사무소 좌표 저장이 이미 실행 중입니다. 중단하려면 window.stopBrokerOfficeLocationLatLngBackfill() 를 실행하세요.");
		return { total: 0, success: 0, failed: [], running: true };
	}
	state.isBrokerOfficeLocationBackfillRunning = true;
	state.stopBrokerOfficeLocationBackfill = false;
	const client = getRealjejuSupabaseClient();
	const result = { total: 0, success: 0, failed: [] };
	if (!client) {
		console.warn("중개사무소 좌표 저장 실패: Supabase 연결을 확인하세요.");
		return result;
	}
	if (!window.kakao || !kakao.maps || !kakao.maps.services) {
		console.warn("중개사무소 좌표 저장 실패: 카카오 지도 서비스가 아직 준비되지 않았습니다.");
		return result;
	}

	const { data, error } = await client
		.from("broker_office_locations")
		.select("id,user_id,agency_id,broker_name,office_name,phone,office_address,lat,lng,updated_at")
		.order("updated_at", { ascending: false });
	if (error) {
		console.warn("중개사무소 좌표 저장 대상 조회 실패:", error);
		return result;
	}

	const locationRows = (Array.isArray(data) ? data : [])
		.map(row => {
			const office = normalizeBrokerOfficeMapRow(row, { requireCoordinates: false });
			return office ? { ...office, sourceTable: "broker_office_locations" } : null;
		})
		.filter(Boolean);
	const agencyRows = await fetchBrokerOfficeSeedRowsFromAgencies(client);
	let rows = mergeBrokerOfficeMapRows(locationRows, agencyRows)
		.filter(office => !normalizeJejuLatLngPair(office.lat, office.lng));
	if (!rows.length) {
		state.brokerOfficeRows = null;
		console.info("중개사무소 좌표가 이미 채워져 있습니다.", {
			locationRows: locationRows.length,
			agencyRows: agencyRows.length
		});
		return result;
	}
	result.total = rows.length;
	if (!rows.length) {
		state.brokerOfficeRows = null;
		console.info("좌표를 채울 중개사무소 데이터가 없습니다. office_name/office_address 값을 확인하세요.", {
			brokerOfficeLocationRawRows: Array.isArray(data) ? data.length : 0,
			normalizedLocationRows: locationRows.length
		});
		return result;
	}

	const geocoder = null;
	const places = kakao.maps.services.Places ? new kakao.maps.services.Places() : null;
	const resolvePosition = async (office) => {
		const queries = buildSubAddressSearchQueries(office.address);
		for (const q of queries) {
			const found = await searchAddressByGeocoder(geocoder, q);
			const normalized = normalizeJejuLatLngPair(found && found.y, found && found.x);
			if (normalized) return normalized;
		}
		if (places) {
			for (const q of queries) {
				const found = await searchAddressByKeyword(places, q);
				const normalized = normalizeJejuLatLngPair(found && found.y, found && found.x);
				if (normalized) return normalized;
			}
		}
		return null;
	};

	try {
	for (const office of rows) {
		if (state.stopBrokerOfficeLocationBackfill) {
			console.warn("중개사무소 좌표 저장을 중단했습니다.", result);
			break;
		}
		const position = await resolvePosition(office);
		if (state.stopBrokerOfficeLocationBackfill) {
			console.warn("중개사무소 좌표 저장을 중단했습니다.", result);
			break;
		}
		const normalized = position && normalizeJejuLatLngPair(position.lat, position.lng);
		if (!normalized) {
			result.failed.push({
				id: office.id,
				officeName: office.officeName,
				address: office.address
			});
			continue;
		}

		const payload = {
			user_id: office.userId || null,
			agency_id: office.agencyId || null,
			broker_name: office.ownerName || null,
			office_name: office.officeName,
			phone: office.phone || null,
			office_address: office.address,
			lat: normalized.lat,
			lng: normalized.lng,
			updated_at: new Date().toISOString()
		};

		const agencySaveResult = await saveAgencyLatLngSnapshot(client, payload);
		let writeError = null;
		if (office.sourceTable === "broker_office_locations" && office.id) {
			const { error: updateError } = await client
				.from("broker_office_locations")
				.update({
					broker_name: payload.broker_name,
					office_name: payload.office_name,
					phone: payload.phone,
					office_address: payload.office_address,
					lat: payload.lat,
					lng: payload.lng,
					updated_at: payload.updated_at
				})
				.eq("id", office.id);
			writeError = updateError;
		} else if (office.sourceTable === "broker_office_locations" && office.userId) {
			const { error: updateError } = await client
				.from("broker_office_locations")
				.update({
					broker_name: payload.broker_name,
					office_name: payload.office_name,
					phone: payload.phone,
					office_address: payload.office_address,
					lat: payload.lat,
					lng: payload.lng,
					updated_at: payload.updated_at
				})
				.eq("user_id", office.userId);
			writeError = updateError;
		} else if (!agencySaveResult) {
			writeError = {
				code: "AGENCY_LAT_LNG_MISSING",
				message: "agencies.lat/lng 저장에 실패했습니다. sql/agencies_lat_lng_3.809.sql을 실행한 뒤 다시 시도하세요."
			};
		}

		if (writeError) {
			result.failed.push({
				id: office.id,
				officeName: office.officeName,
				address: office.address,
				error: writeError
			});
			console.warn("중개사무소 좌표 저장 실패:", office.officeName, writeError);
			if (writeError.code === "42501" || writeError.code === "LOCATION_ROW_MISSING") {
				state.stopBrokerOfficeLocationBackfill = true;
				console.warn("권한/행 문제라 좌표 저장을 즉시 중단합니다.", writeError);
				break;
			}
			continue;
		}
		result.success += 1;
	}

	state.brokerOfficeRows = null;
	console.info("중개사무소 좌표 저장 완료:", result);
	return result;
	} finally {
		state.isBrokerOfficeLocationBackfillRunning = false;
	}
}

function stopBrokerOfficeLocationLatLngBackfill()
{
	state.stopBrokerOfficeLocationBackfill = true;
	console.warn("중개사무소 좌표 저장 중단 요청됨. 진행 중인 주소 요청 1건이 끝나면 멈춥니다.");
}

window.backfillBrokerOfficeLocationLatLng = backfillBrokerOfficeLocationLatLng;

window.stopBrokerOfficeLocationLatLngBackfill = stopBrokerOfficeLocationLatLngBackfill;

async function backfillEducationFacilityLatLng(options = {})
{
	if (state.isEducationFacilityLatLngBackfillRunning) {
		console.warn("교육시설 좌표 저장이 이미 실행 중입니다. 중단하려면 window.stopEducationFacilityLatLngBackfill() 를 실행하세요.");
		return { total: 0, success: 0, failed: [], running: true };
	}
	state.isEducationFacilityLatLngBackfillRunning = true;
	state.stopEducationFacilityLatLngBackfill = false;
	const result = { total: 0, success: 0, failed: [] };
	const client = getRealjejuSupabaseClient();
	try {
		if (!client) {
			console.warn("교육시설 좌표 저장 실패: Supabase 연결을 확인하세요.");
			return result;
		}
		if (!window.kakao || !kakao.maps || !kakao.maps.services) {
			console.warn("교육시설 좌표 저장 실패: 카카오 지도 서비스가 아직 준비되지 않았습니다.");
			return result;
		}
		let query = client
			.from("education_facilities")
			.select("id,official_code,category,school_type,name,address,road_address,lat,lng,updated_at")
			.or("lat.is.null,lng.is.null")
			.order("category", { ascending: true })
			.order("name", { ascending: true });
		const targetCategory = String(options && options.category || "").trim();
		const targetLimit = Number(options && options.limit);
		if (targetCategory) query = query.eq("category", targetCategory);
		if (Number.isFinite(targetLimit) && targetLimit > 0) query = query.limit(Math.floor(targetLimit));
		const { data, error } = await query;
		if (error) {
			console.warn("교육시설 좌표 저장 대상 조회 실패:", error);
			return result;
		}
		const rows = (Array.isArray(data) ? data : []).filter(row => row && row.id && String(row.address || row.road_address || "").trim());
		result.total = rows.length;
		if (!rows.length) {
			console.info("좌표를 채울 교육시설 데이터가 없습니다.");
			return result;
		}
		const geocoder = null;
		const normalizePosition = (found) => {
			const lat = Number(found && found.y);
			const lng = Number(found && found.x);
			if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
			if (lat < 32.8 || lat > 34.1 || lng < 125.8 || lng > 127.2) return null;
			return { lat, lng };
		};
		for (const row of rows) {
			if (state.stopEducationFacilityLatLngBackfill) {
				console.warn("교육시설 좌표 저장을 중단했습니다.", result);
				break;
			}
			const queries = buildSubAddressSearchQueries(row.address || row.road_address);
			let position = null;
			for (const query of queries) {
				const found = await searchAddressByGeocoder(geocoder, query);
				position = normalizePosition(found);
				if (position) break;
			}
			if (!position && kakao.maps.services.Places) {
				const places = new kakao.maps.services.Places();
				const keywordQueries = [
					...queries.map(query => `${row.name} ${query}`),
					`${row.name} ${row.address || row.road_address || ""}`.trim()
				];
				for (const query of [...new Set(keywordQueries)]) {
					const found = await searchAddressByKeyword(places, query);
					position = normalizePosition(found);
					if (position) break;
				}
			}
			if (!position) {
				result.failed.push({
					id: row.id,
					name: row.name,
					address: row.address || row.road_address
				});
				continue;
			}
			const { error: updateError } = await client
				.from("education_facilities")
				.update({
					lat: position.lat,
					lng: position.lng,
					updated_at: new Date().toISOString()
				})
				.eq("id", row.id);
			if (updateError) {
				result.failed.push({
					id: row.id,
					name: row.name,
					address: row.address || row.road_address,
					error: updateError
				});
				console.warn("교육시설 좌표 저장 실패:", row.name, updateError);
				if (updateError.code === "42501") {
					state.stopEducationFacilityLatLngBackfill = true;
					console.warn("권한 문제라 교육시설 좌표 저장을 즉시 중단합니다.", updateError);
					break;
				}
				continue;
			}
			result.success += 1;
		}
		console.info("교육시설 좌표 저장 완료:", result);
		return result;
	} finally {
		state.isEducationFacilityLatLngBackfillRunning = false;
	}
}

function stopEducationFacilityLatLngBackfill()
{
	state.stopEducationFacilityLatLngBackfill = true;
	console.warn("교육시설 좌표 저장 중단 요청됨. 진행 중인 주소 요청 1건이 끝나면 멈춥니다.");
}

