function isFacilityMapMarkerEvent(event)
{
	const target = event && event.target && typeof event.target.closest === "function"
		? event.target
		: null;
	return !!(target && target.closest(".education-facility-map-marker, .broker-office-map-marker"));
}

document.addEventListener("pointerdown", (event) => {
	if (!isFacilityMapMarkerEvent(event)) return;
	blockParcelMapClickFromFacilityMarker();
}, true);

