function positionDevelopmentFacilityFilterPanel()
{
	if (!developmentFacilityFilterPanel) return;
	const anchorBtn = mapEducationToolBtn || mapDevelopmentToolBtn;
	if (!anchorBtn) return;
	const rect = anchorBtn.getBoundingClientRect();
	const panelRect = developmentFacilityFilterPanel.getBoundingClientRect();
	const left = Math.max(8, rect.left - panelRect.width - 8);
	const top = Math.min(Math.max(8, rect.top - 12), window.innerHeight - panelRect.height - 8);
	developmentFacilityFilterPanel.style.left = left + "px";
	developmentFacilityFilterPanel.style.top = top + "px";
}

function ensureDevelopmentFacilityFilterPanel()
{
	if (developmentFacilityFilterPanel) return developmentFacilityFilterPanel;
	developmentFacilityFilterPanel = document.createElement("div");
	developmentFacilityFilterPanel.className = "education-facility-filter-panel development-facility-filter-panel";
	developmentFacilityFilterPanel.setAttribute("role", "dialog");
	developmentFacilityFilterPanel.setAttribute("aria-label", "개발 표시 선택");
	developmentFacilityFilterPanel.addEventListener("click", (event) => {
		event.stopPropagation();
		const clearBtn = event.target.closest("[data-development-clear]");
		if (clearBtn) {
			clearNationalLandPlanSelections();
			setFactoryRestrictionOverlayVisible(false);
			setSewerTreatmentAreaOverlayVisible(false);
			setCulturalHeritageProtectionOverlayVisible(false);
			setLivestockBreedingRestrictionOverlayVisible(false);
			return;
		}
		const nationalLandPlanBtn = event.target.closest("[data-national-land-plan-layer]");
		if (nationalLandPlanBtn) {
			const key = String(nationalLandPlanBtn.dataset.nationalLandPlanLayer || "");
			if (!NATIONAL_LAND_PLAN_DEVELOPMENT_OPTIONS.some((option) => option.key === key)) return;
			setNationalLandPlanOverlayVisible(key, !selectedNationalLandPlanDevelopmentLayers.has(key));
			return;
		}
		const layerBtn = event.target.closest("[data-development-layer]");
		if (!layerBtn) return;
		const isActive = !layerBtn.classList.contains("active");
		if (layerBtn.dataset.developmentLayer === "factory-restriction") setFactoryRestrictionOverlayVisible(isActive);
		if (layerBtn.dataset.developmentLayer === "sewer-treatment-area") setSewerTreatmentAreaOverlayVisible(isActive);
		if (layerBtn.dataset.developmentLayer === "cultural-heritage-protection") setCulturalHeritageProtectionOverlayVisible(isActive);
		if (layerBtn.dataset.developmentLayer === "livestock-breeding-restriction") setLivestockBreedingRestrictionOverlayVisible(isActive);
	});
	document.body.appendChild(developmentFacilityFilterPanel);
	return developmentFacilityFilterPanel;
}

