function ensureBrokerOfficeFilterPanel()
{
	if (brokerOfficeFilterPanel) return brokerOfficeFilterPanel;
	brokerOfficeFilterPanel = document.createElement("div");
	brokerOfficeFilterPanel.className = "education-facility-filter-panel broker-office-filter-panel";
	brokerOfficeFilterPanel.setAttribute("role", "dialog");
	brokerOfficeFilterPanel.setAttribute("aria-label", "중개 표시 선택");
	brokerOfficeFilterPanel.addEventListener("click", async (event) => {
		const option = event.target.closest("[data-broker-office-filter-option]");
		if (option) {
			event.preventDefault();
			event.stopPropagation();
			const key = option.dataset.brokerOfficeFilterOption || "all";
			if (key === "mine" || key === "office") {
				state.brokerListingMapScope = state.brokerListingMapScope === key ? "all" : key;
				state.brokerOfficeMapFilter = "none";
				state.isBrokerOfficesVisible = false;
				selectAllTopPropertyTypeFilters({ apply: false });
				clearBrokerOfficeOverlays();
				if (key === "mine") closeListingPanelsForBrokerMineScope();
				applyFilter();
				renderBrokerOfficeFilterPanel();
				updateBrokerOfficeToolActiveState();
				return;
			}
			const didResetBrokerListingScope = state.brokerListingMapScope !== "all";
			state.brokerListingMapScope = "all";
			const isSameActiveFilter = state.isBrokerOfficesVisible && state.brokerOfficeMapFilter === key;
			state.brokerOfficeMapFilter = isSameActiveFilter ? "none" : key;
			state.isBrokerOfficesVisible = !isSameActiveFilter;
			// 중개사 전문분야 선택은 매물 필터가 아니므로 열린 지역 목록과 선택 박스를 유지한다.
			// 내 매물/우리 사무소 범위에서 넘어온 경우에만 실제 매물 범위를 전체로 되돌린다.
			if (didResetBrokerListingScope) applyFilter();
			if (state.isBrokerOfficesVisible) {
				bringFacilityOverlayLayerToFront("broker");
				await renderBrokerOfficeOverlays();
			} else {
				clearBrokerOfficeOverlays();
			}
			renderBrokerOfficeFilterPanel();
			updateBrokerOfficeToolActiveState();
			return;
		}
		const clearBtn = event.target.closest("[data-broker-office-filter-clear]");
		if (clearBtn) {
			event.preventDefault();
			event.stopPropagation();
			const didResetBrokerListingScope = state.brokerListingMapScope !== "all";
			state.brokerOfficeMapFilter = "none";
			state.brokerListingMapScope = "all";
			state.isBrokerOfficesVisible = false;
			clearBrokerOfficeOverlays();
			if (didResetBrokerListingScope) applyFilter();
			renderBrokerOfficeFilterPanel();
			updateBrokerOfficeToolActiveState();
		}
	});
	document.body.appendChild(brokerOfficeFilterPanel);
	return brokerOfficeFilterPanel;
}

function syncPropertyBadgeStylePopover(popover, style)
{
	if (!popover) return;
	const normalized = {
		color: normalizePropertyBadgeStyleColor(style && style.color),
		textColor: normalizePropertyBadgeTextColor(style && style.textColor),
		textOpacity: normalizePropertyBadgeTextOpacity(style && style.textOpacity),
		opacity: normalizePropertyBadgeStyleOpacity(style && style.opacity)
	};
	popover.dataset.draftColor = normalized.color;
	popover.dataset.draftOpacity = String(normalized.opacity);
	popover.querySelectorAll("[data-property-badge-style-color]").forEach((button) => {
		const isActive = String(button.dataset.propertyBadgeStyleColor || "").toUpperCase() === normalized.color;
		button.classList.toggle("active", isActive);
		button.setAttribute("aria-pressed", isActive ? "true" : "false");
	});
	const opacityInput = popover.querySelector("[data-property-badge-style-opacity]");
	if (opacityInput) opacityInput.value = String(Math.round(normalized.opacity * 100));
	const opacityValue = popover.querySelector("[data-property-badge-style-opacity-value]");
	if (opacityValue) opacityValue.textContent = `${Math.round(normalized.opacity * 100)}%`;
	const preview = popover.querySelector("[data-property-badge-style-preview]");
	if (preview) {
		preview.style.background = hexToRgba(normalized.color, normalized.opacity);
		preview.style.color = getResolvedPropertyBadgeTextColor(normalized);
		preview.style.borderColor = getResolvedPropertyBadgeBorderColor(normalized);
	}
}

