function isPropertyBadgeStyleEditorPopoverOpen(mode = "")
{
	return !!(
		propertyBadgeStyleEditorPopover
		&& !propertyBadgeStyleEditorPopover.hidden
		&& (!mode || propertyBadgeStyleEditorPopover.dataset.editorMode === mode)
	);
}

function isAdminBoundaryStyleEditorPopoverOpen()
{
	return !!(adminBoundaryStyleEditorPopover && !adminBoundaryStyleEditorPopover.hidden);
}

function positionMapSettingsFilterPanel()
{
	if (!mapSettingsFilterPanel || !mapSettingsToolBtn || !isMapSettingsFilterPanelOpen()) return;
	const rect = mapSettingsToolBtn.getBoundingClientRect();
	const panelRect = mapSettingsFilterPanel.getBoundingClientRect();
	const left = Math.max(8, rect.left - panelRect.width - 8);
	// 5.002: 설정 버튼 왼쪽의 메뉴는 설정 버튼과 하단선을 정확히 맞춥니다.
	const top = Math.min(Math.max(8, rect.bottom - panelRect.height), window.innerHeight - panelRect.height - 8);
	mapSettingsFilterPanel.style.left = left + "px";
	mapSettingsFilterPanel.style.top = top + "px";
}

function positionPropertyBadgeStyleEditorPopover()
{
	if (!propertyBadgeStyleEditorPopover || !mapSettingsFilterPanel || !isPropertyBadgeStyleEditorPopoverOpen()) return;
	const panelRect = mapSettingsFilterPanel.getBoundingClientRect();
	const settingsButtonRect = mapSettingsToolBtn ? mapSettingsToolBtn.getBoundingClientRect() : panelRect;
	const editorRect = propertyBadgeStyleEditorPopover.getBoundingClientRect();
	const left = Math.max(8, panelRect.left - editorRect.width - 8);
	// 5.002: 색상 편집창도 같은 기준선에 맞춰 두 왼쪽 패널의 바닥이 내려가지 않게 합니다.
	const top = Math.min(Math.max(8, settingsButtonRect.bottom - editorRect.height), window.innerHeight - editorRect.height - 8);
	propertyBadgeStyleEditorPopover.style.left = left + "px";
	propertyBadgeStyleEditorPopover.style.top = top + "px";
}

function positionAdminBoundaryStyleEditorPopover()
{
	if (!adminBoundaryStyleEditorPopover || !mapSettingsFilterPanel || !isAdminBoundaryStyleEditorPopoverOpen()) return;
	const panelRect = mapSettingsFilterPanel.getBoundingClientRect();
	const settingsButtonRect = mapSettingsToolBtn ? mapSettingsToolBtn.getBoundingClientRect() : panelRect;
	const editorRect = adminBoundaryStyleEditorPopover.getBoundingClientRect();
	const left = Math.max(8, panelRect.left - editorRect.width - 8);
	const top = Math.min(Math.max(8, settingsButtonRect.bottom - editorRect.height), window.innerHeight - editorRect.height - 8);
	adminBoundaryStyleEditorPopover.style.left = left + "px";
	adminBoundaryStyleEditorPopover.style.top = top + "px";
}

function ensurePropertyBadgeStyleEditorPopover()
{
	if (propertyBadgeStyleEditorPopover) return propertyBadgeStyleEditorPopover;
	propertyBadgeStyleEditorPopover = document.createElement("div");
	propertyBadgeStyleEditorPopover.className = "property-badge-style-popover settings-property-badge-style-popover";
	propertyBadgeStyleEditorPopover.setAttribute("data-property-badge-style-popover", "");
	propertyBadgeStyleEditorPopover.setAttribute("role", "dialog");
	propertyBadgeStyleEditorPopover.setAttribute("aria-label", "원형 매물 뱃지 색상 변경");
	propertyBadgeStyleEditorPopover.hidden = true;
	propertyBadgeStyleEditorPopover.addEventListener("click", async (event) => {
		const colorOption = event.target.closest("[data-property-badge-style-color]");
		if (colorOption) {
			event.preventDefault();
			event.stopPropagation();
			syncPropertyBadgeStylePopover(propertyBadgeStyleEditorPopover, {
				...getPropertyBadgeStyle(),
				color: colorOption.dataset.propertyBadgeStyleColor,
				opacity: propertyBadgeStyleEditorPopover.dataset.draftOpacity
			});
			return;
		}
		const textColorOption = event.target.closest("[data-property-badge-text-style-color]");
		if (textColorOption) {
			event.preventDefault();
			event.stopPropagation();
			syncPropertyBadgeTextStylePopover(propertyBadgeStyleEditorPopover, {
				textColor: textColorOption.dataset.propertyBadgeTextStyleColor,
				textOpacity: propertyBadgeStyleEditorPopover.dataset.draftTextOpacity
			});
			return;
		}
		const borderColorOption = event.target.closest("[data-property-badge-border-style-color]");
		if (borderColorOption) {
			event.preventDefault();
			event.stopPropagation();
			syncPropertyBadgeBorderStylePopover(propertyBadgeStyleEditorPopover, {
				borderColor: borderColorOption.dataset.propertyBadgeBorderStyleColor,
				borderOpacity: propertyBadgeStyleEditorPopover.dataset.draftBorderOpacity
			});
			return;
		}
		const resetStyleBtn = event.target.closest("[data-property-badge-style-reset]");
		if (resetStyleBtn) {
			event.preventDefault();
			event.stopPropagation();
			syncPropertyBadgeStylePopover(propertyBadgeStyleEditorPopover, {
				...getPropertyBadgeStyle(),
				color: PROPERTY_BADGE_STYLE_DEFAULT.color,
				opacity: PROPERTY_BADGE_STYLE_DEFAULT.opacity
			});
			return;
		}
		const resetTextStyleBtn = event.target.closest("[data-property-badge-text-style-reset]");
		if (resetTextStyleBtn) {
			event.preventDefault();
			event.stopPropagation();
			syncPropertyBadgeTextStylePopover(propertyBadgeStyleEditorPopover, {
				textColor: PROPERTY_BADGE_STYLE_DEFAULT.textColor,
				textOpacity: PROPERTY_BADGE_STYLE_DEFAULT.textOpacity
			});
			return;
		}
		const resetBorderStyleBtn = event.target.closest("[data-property-badge-border-style-reset]");
		if (resetBorderStyleBtn) {
			event.preventDefault();
			event.stopPropagation();
			syncPropertyBadgeBorderStylePopover(propertyBadgeStyleEditorPopover, {
				borderColor: PROPERTY_BADGE_STYLE_DEFAULT.borderColor,
				borderOpacity: PROPERTY_BADGE_STYLE_DEFAULT.borderOpacity
			});
			return;
		}
		const cancelStyleBtn = event.target.closest("[data-property-badge-style-cancel]");
		if (cancelStyleBtn) {
			event.preventDefault();
			event.stopPropagation();
			closePropertyBadgeStyleEditorPopover();
			renderMapSettingsFilterPanel();
			syncMapToolPopoverZOrder(mapSettingsFilterPanel);
			return;
		}
		const applyStyleBtn = event.target.closest("[data-property-badge-style-apply]");
		if (!applyStyleBtn || applyStyleBtn.disabled) return;
		event.preventDefault();
		event.stopPropagation();
		applyStyleBtn.disabled = true;
		applyStyleBtn.textContent = "저장 중";
		try {
			const currentStyle = getPropertyBadgeStyle();
			const mode = propertyBadgeStyleEditorPopover.dataset.editorMode;
			const nextStyle = { ...currentStyle };
			if (mode === "text") {
				nextStyle.textColor = propertyBadgeStyleEditorPopover.dataset.draftTextColor;
				nextStyle.textOpacity = propertyBadgeStyleEditorPopover.dataset.draftTextOpacity;
			} else if (mode === "border") {
				nextStyle.borderColor = propertyBadgeStyleEditorPopover.dataset.draftBorderColor;
				nextStyle.borderOpacity = propertyBadgeStyleEditorPopover.dataset.draftBorderOpacity;
			} else {
				nextStyle.color = propertyBadgeStyleEditorPopover.dataset.draftColor;
				nextStyle.opacity = propertyBadgeStyleEditorPopover.dataset.draftOpacity;
			}
			await savePropertyBadgeStyleForCurrentUser(nextStyle);
			renderMapSettingsFilterPanel();
			syncMapToolPopoverZOrder(mapSettingsFilterPanel);
			applyStyleBtn.disabled = false;
			applyStyleBtn.textContent = "적용";
		} catch (error) {
			console.warn("원형 매물 뱃지 설정 저장 실패:", error);
			applyStyleBtn.disabled = false;
			applyStyleBtn.textContent = "적용";
			window.alert(error && error.message ? error.message : "설정을 저장하지 못했습니다.");
		}
	});
	propertyBadgeStyleEditorPopover.addEventListener("input", (event) => {
		const opacityInput = event.target.closest("[data-property-badge-style-opacity]");
		if (opacityInput) {
			syncPropertyBadgeStylePopover(propertyBadgeStyleEditorPopover, {
				...getPropertyBadgeStyle(),
				color: propertyBadgeStyleEditorPopover.dataset.draftColor,
				opacity: Number(opacityInput.value) / 100
			});
			return;
		}
		const textOpacityInput = event.target.closest("[data-property-badge-text-style-opacity]");
		if (textOpacityInput) {
			syncPropertyBadgeTextStylePopover(propertyBadgeStyleEditorPopover, {
				textColor: propertyBadgeStyleEditorPopover.dataset.draftTextColor,
				textOpacity: Number(textOpacityInput.value) / 100
			});
			return;
		}
		const borderOpacityInput = event.target.closest("[data-property-badge-border-style-opacity]");
		if (!borderOpacityInput) return;
		syncPropertyBadgeBorderStylePopover(propertyBadgeStyleEditorPopover, {
			borderColor: propertyBadgeStyleEditorPopover.dataset.draftBorderColor,
			borderOpacity: Number(borderOpacityInput.value) / 100
		});
	});
	document.body.appendChild(propertyBadgeStyleEditorPopover);
	return propertyBadgeStyleEditorPopover;
}

function ensureAdminBoundaryStyleEditorPopover()
{
	if (adminBoundaryStyleEditorPopover) return adminBoundaryStyleEditorPopover;
	adminBoundaryStyleEditorPopover = document.createElement("div");
	adminBoundaryStyleEditorPopover.className = "property-badge-style-popover settings-property-badge-style-popover admin-boundary-style-popover";
	adminBoundaryStyleEditorPopover.setAttribute("role", "dialog");
	adminBoundaryStyleEditorPopover.setAttribute("aria-label", "행정구역 경계 색상 변경");
	adminBoundaryStyleEditorPopover.hidden = true;
	adminBoundaryStyleEditorPopover.addEventListener("click", async (event) => {
		const colorOption = event.target.closest("[data-admin-boundary-style-color]");
		if (colorOption) {
			event.preventDefault();
			event.stopPropagation();
			syncAdminBoundaryStylePopover(adminBoundaryStyleEditorPopover, {
				color: colorOption.dataset.adminBoundaryStyleColor,
				opacity: adminBoundaryStyleEditorPopover.dataset.draftOpacity
			});
			return;
		}
		const resetStyleBtn = event.target.closest("[data-admin-boundary-style-reset]");
		if (resetStyleBtn) {
			event.preventDefault();
			event.stopPropagation();
			syncAdminBoundaryStylePopover(adminBoundaryStyleEditorPopover, ADMIN_BOUNDARY_STYLE_DEFAULT);
			return;
		}
		const cancelStyleBtn = event.target.closest("[data-admin-boundary-style-cancel]");
		if (cancelStyleBtn) {
			event.preventDefault();
			event.stopPropagation();
			closeAdminBoundaryStyleEditorPopover();
			renderMapSettingsFilterPanel();
			syncMapToolPopoverZOrder(mapSettingsFilterPanel);
			return;
		}
		const applyStyleBtn = event.target.closest("[data-admin-boundary-style-apply]");
		if (!applyStyleBtn || applyStyleBtn.disabled) return;
		event.preventDefault();
		event.stopPropagation();
		applyStyleBtn.disabled = true;
		applyStyleBtn.textContent = "저장 중";
		try {
			await saveAdminBoundaryStyleForCurrentUser({
				color: adminBoundaryStyleEditorPopover.dataset.draftColor,
				opacity: adminBoundaryStyleEditorPopover.dataset.draftOpacity
			});
			renderMapSettingsFilterPanel();
			syncMapToolPopoverZOrder(mapSettingsFilterPanel);
			applyStyleBtn.disabled = false;
			applyStyleBtn.textContent = "적용";
		} catch (error) {
			console.warn("행정구역 경계 설정 저장 실패:", error);
			applyStyleBtn.disabled = false;
			applyStyleBtn.textContent = "적용";
		}
	});
	adminBoundaryStyleEditorPopover.addEventListener("input", (event) => {
		const opacityInput = event.target.closest("[data-admin-boundary-style-opacity]");
		if (!opacityInput) return;
		syncAdminBoundaryStylePopover(adminBoundaryStyleEditorPopover, {
			color: adminBoundaryStyleEditorPopover.dataset.draftColor,
			opacity: Number(opacityInput.value) / 100
		});
	});
	document.body.appendChild(adminBoundaryStyleEditorPopover);
	return adminBoundaryStyleEditorPopover;
}

function openPropertyBadgeStyleEditorPopover(mode = "background")
{
	closeAdminBoundaryStyleEditorPopover();
	const editor = ensurePropertyBadgeStyleEditorPopover();
	const style = getPropertyBadgeStyle();
	const editorMode = mode === "text" || mode === "border" ? mode : "background";
	editor.dataset.editorMode = editorMode;
	editor.innerHTML = editorMode === "text"
		? renderPropertyBadgeTextStyleEditorHtml()
		: (editorMode === "border" ? renderPropertyBadgeBorderStyleEditorHtml() : renderPropertyBadgeStyleEditorHtml());
	if (editorMode === "text") {
		editor.dataset.draftTextColor = style.textColor;
		editor.dataset.draftTextOpacity = String(style.textOpacity);
		syncPropertyBadgeTextStylePopover(editor, style);
	} else if (editorMode === "border") {
		editor.dataset.draftBorderColor = style.borderColor;
		editor.dataset.draftBorderOpacity = String(style.borderOpacity);
		syncPropertyBadgeBorderStylePopover(editor, style);
	} else {
		editor.dataset.draftColor = style.color;
		editor.dataset.draftOpacity = String(style.opacity);
		syncPropertyBadgeStylePopover(editor, style);
	}
	editor.hidden = false;
	document.body.appendChild(editor);
	syncMapToolPopoverZOrder(editor);
	positionPropertyBadgeStyleEditorPopover();
	renderMapSettingsFilterPanel();
}

function openAdminBoundaryStyleEditorPopover()
{
	closePropertyBadgeStyleEditorPopover();
	const editor = ensureAdminBoundaryStyleEditorPopover();
	const style = getAdminBoundaryStylePreference();
	editor.innerHTML = renderAdminBoundaryStyleEditorHtml();
	editor.dataset.draftColor = style.color;
	editor.dataset.draftOpacity = String(style.opacity);
	editor.hidden = false;
	syncAdminBoundaryStylePopover(editor, style);
	document.body.appendChild(editor);
	syncMapToolPopoverZOrder(editor);
	positionAdminBoundaryStyleEditorPopover();
	renderMapSettingsFilterPanel();
}

function ensureMapSettingsFilterPanel()
{
	if (mapSettingsFilterPanel) return mapSettingsFilterPanel;
	mapSettingsFilterPanel = document.createElement("div");
	mapSettingsFilterPanel.className = "education-facility-filter-panel map-settings-filter-panel";
	mapSettingsFilterPanel.setAttribute("role", "dialog");
	mapSettingsFilterPanel.setAttribute("aria-label", "지도 설정");
	mapSettingsFilterPanel.addEventListener("click", (event) => {
		const option = event.target.closest("[data-map-settings-option]");
		if (!option || option.disabled) return;
		event.preventDefault();
		event.stopPropagation();
		const modeByOption = {
			"property-badge-style": "background",
			"property-badge-text-style": "text",
			"property-badge-border-style": "border"
		};
		const editorMode = modeByOption[option.dataset.mapSettingsOption];
		if (editorMode) {
			if (isPropertyBadgeStyleEditorPopoverOpen(editorMode)) {
				closePropertyBadgeStyleEditorPopover();
				renderMapSettingsFilterPanel();
				syncMapToolPopoverZOrder(mapSettingsFilterPanel);
			} else {
				openPropertyBadgeStyleEditorPopover(editorMode);
			}
			return;
		}
		if (option.dataset.mapSettingsOption === "admin-boundary-style") {
			if (isAdminBoundaryStyleEditorPopoverOpen()) {
				closeAdminBoundaryStyleEditorPopover();
				renderMapSettingsFilterPanel();
				syncMapToolPopoverZOrder(mapSettingsFilterPanel);
			} else {
				openAdminBoundaryStyleEditorPopover();
			}
		}
	});
	document.body.appendChild(mapSettingsFilterPanel);
	return mapSettingsFilterPanel;
}

