async function openDetailFromUrl({ replaceHistory = true } = {})
{
	const targetId = getDetailIdFromLocation();
	const hasExplicitDetailQuery = !!targetId;

	if (!hasExplicitDetailQuery || !targetId) {
		setSharedDetailMode(false);
		document.body.classList.remove("direct-detail-list-mode");
		return false;
	}

	setSharedDetailMode(false);

	let item = (state.all || []).find(v => normalizeItemId(v.id) === targetId);
	if (!item) {
		const seedItem = { id: targetId };
		const dbItem = await resolveDetailDataFromDatabase(seedItem);
		if (dbItem && dbItem !== seedItem && normalizeItemId(dbItem.id) === targetId) {
			item = dbItem;
		}
	}
	if (!item) {
		setSharedDetailMode(false);
		document.body.classList.remove("direct-detail-list-mode");
		return false;
	}

	const normalizedTargetId = normalizeItemId(item.id || targetId);
	if (normalizedTargetId) {
		const mergeIntoList = (list) => {
			const source = Array.isArray(list) ? [...list] : [];
			const index = source.findIndex(candidate => normalizeItemId(candidate && candidate.id) === normalizedTargetId);
			if (index >= 0) {
				source[index] = { ...source[index], ...item };
				return source;
			}
			return [item, ...source];
		};
		state.all = mergeIntoList(state.all);
		state.filtered = mergeIntoList(state.filtered);
	}

	closeEducationFacilityDetailForPropertyInteraction();
	if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
		await closeRoadviewPanelForPropertyInteraction();
	} else if (typeof hideRoadview === "function") {
		await hideRoadview();
	}
	document.body.classList.add("direct-detail-list-mode");
	document.body.classList.remove("sidebar-list-collapsed");
	state.selectionMode = "single";
	state.selectedClusterKey = null;
	state.selectedMarkerId = targetId;
	state.selectedMarkerIds = new Set([targetId]);
	lockListToItems([item]);
	openSidebarList();
	resetLeftListPagination([item]);
	propertyList.innerHTML = "";
	// 직접 공유 링크는 상세 조회로 이미 확보한 한 건을 왼쪽 목록에 즉시 표시한다.
	// 같은 ID의 목록용 중개사ㆍ썸네일 보강은 뒤에서 교체하되 첫 화면을 빈 패널로 기다리게 하지 않는다.
	await loadMoreLeftListItems({ sourceItems: [item], renderImmediately: true });
	setResultInfo("선택 매물 1건");
	setListInfo("총 1개 매물");
	highlightCard(targetId);
	updateMarkerSelection(targetId, [targetId]);

	if (detailScroll) detailScroll.scrollTop = 0;
	await openDetailPanel(item, { syncUrl: false, forceOpen: true, overlayPage: false });
	document.body.classList.add("direct-detail-list-mode");
	document.body.classList.remove("sidebar-list-collapsed");
	state.isListOpen = true;
	if (sidebar) sidebar.classList.add("expanded");
	updateSidebarWidth();
	if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
	if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
	if (typeof refreshMapLayout === "function") {
		refreshMapLayout();
		setTimeout(refreshMapLayout, 120);
	}

	if (replaceHistory) {
		syncDetailUrl(item.id, { replace: true });
	}

	if (detailScroll) detailScroll.scrollTop = 0;
	await focusProperty(item.id);

	setTimeout(() => {
		document.body.classList.add("direct-detail-list-mode");
		document.body.classList.remove("sidebar-list-collapsed");
		state.isListOpen = true;
		updateSidebarWidth();
		if (typeof syncMapFilterbarDetailHidden === "function") syncMapFilterbarDetailHidden();
		if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
		highlightCard(targetId);
		refreshClusterBadges();
	}, 0);

	return true;
}

async function moveMapToProperty(item)
{
	if (!item || !state.map || !window.kakao || !kakao.maps) return;
	const lat = Number(item.lat);
	const lng = Number(item.lng);
	if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;

	closeEducationFacilityDetailForPropertyInteraction();
	if (typeof closeRoadviewPanelForPropertyInteraction === "function") {
		await closeRoadviewPanelForPropertyInteraction();
	} else if (typeof hideRoadview === "function") {
		await hideRoadview();
	}
	const position = new kakao.maps.LatLng(lat, lng);
	state.map.panTo(position);
}

