async function refreshMySuiteFavoriteViewCounts(items)
{
	const rows = Array.isArray(items) ? items : [];
	const renderSeq = ++mySuiteFavoriteViewCountRenderSeq;
	if (!rows.length) return;
	const counts = {};
	const resolvedItemKeys = new Set();
	try {
		await loadSupabaseScript();
		const client = getMapListingsSupabaseClient();
		const itemKeys = [...new Set(rows.map(getItemViewKey).map(getViewCountKey).filter(Boolean))];
		if (client && itemKeys.length && !engagementCountRpcDisabled && typeof client.rpc === "function") {
			const { data, error } = await client.rpc("get_property_engagement_counts", {
				p_listing_ids: itemKeys
			});
			if (error) throw error;
			const rowMap = new Map((Array.isArray(data) ? data : []).map((row) => [
				getViewCountKey(row && row.listing_id),
				row
			]));
			const fetchedAt = Date.now();
			rows.forEach((item) => {
				const itemKey = getViewCountKey(getItemViewKey(item));
				const viewKey = getViewCountKey(getListingViewKey(item) || itemKey);
				const row = rowMap.get(itemKey);
				const views = Number(row && row.views);
				if (!itemKey || !viewKey || !Number.isFinite(views)) return;
				counts[viewKey] = Math.max(0, Math.trunc(views));
				resolvedItemKeys.add(itemKey);
				detailEngagementFetchedAtMap.set(itemKey, fetchedAt);
			});
		}
	} catch (error) {
		if (isMissingRpcError(error)) engagementCountRpcDisabled = true;
		else console.warn("관심 부동산 조회수 불러오기 실패:", error);
	}
	const fallbackRows = rows.filter((item) => !resolvedItemKeys.has(getViewCountKey(getItemViewKey(item))));
	const fallbackCounts = await fetchViewCounts(fallbackRows, { force: true });
	Object.assign(counts, fallbackCounts);
	if (renderSeq !== mySuiteFavoriteViewCountRenderSeq) return;
	viewMap = { ...viewMap, ...counts };
	Object.entries(counts).forEach(([viewKey, count]) => updateViewCountElements(viewKey, count));
}

function getListingPaginationItems(totalPages, currentPage)
{
	const pages = [];
	if (totalPages <= 9) {
		for (let i = 1; i <= totalPages; i += 1) pages.push(i);
		return pages;
	}
	pages.push(1);
	const start = Math.max(2, currentPage - 2);
	const end = Math.min(totalPages - 1, currentPage + 2);
	if (start > 2) pages.push("ellipsis");
	for (let i = start; i <= end; i += 1) pages.push(i);
	if (end < totalPages - 1) pages.push("ellipsis");
	pages.push(totalPages);
	return pages;
}

function setMySuiteFavoriteListingPage(value)
{
	const next = Math.floor(Number(value));
	if (!Number.isFinite(next) || next < 1) {
		mySuiteFavoritePage = 1;
		return;
	}
	mySuiteFavoritePage = next;
}

function getMySuiteFavoriteListingPage(totalPages)
{
	const maxPage = Math.max(1, Number(totalPages) || 1);
	if (!Number.isFinite(mySuiteFavoritePage) || mySuiteFavoritePage < 1) mySuiteFavoritePage = 1;
	if (mySuiteFavoritePage > maxPage) mySuiteFavoritePage = maxPage;
	return mySuiteFavoritePage;
}

function renderMySuiteFavoriteListingPagination(totalCount, totalPages, currentPage)
{
	if (totalCount <= MY_SUITE_FAVORITES_PER_PAGE || totalPages <= 1) return "";
	const items = getListingPaginationItems(totalPages, currentPage);
	return `
		<nav class="broker-listing-pagination" aria-label="관심 부동산 페이지">
			${items.map((item) => {
				if (item === "ellipsis") return '<span class="broker-listing-page-ellipsis">…</span>';
				const page = Number(item);
				return `<button type="button" class="broker-listing-page-btn ${page === currentPage ? "active" : ""}" data-favorite-listing-page="${page}" aria-current="${page === currentPage ? "page" : "false"}">${page}</button>`;
			}).join("")}
		</nav>
	`;
}

