				<input type="range" class="area-filter-range area-filter-range-max" id="favoriteAreaFilterMaxRange" min="0" max="${AREA_FILTER_MAX_M2}" step="1" value="${AREA_FILTER_MAX_M2}" aria-label="최대 면적" />
