	if (!input) return;
	const type = normalizeFavoriteFilterType(input.dataset.favoriteFilterOption);
	const value = getFavoriteFilterLabel(input.dataset.value);
	const targetSet = getFavoriteFilterTargetSet(type);
	if (input.checked) targetSet.add(value);
