	function escapeMySuiteHtml(value)
	{
		return String(value == null ? "" : value)
			.replace(/&/g, "&amp;")
			.replace(/</g, "&lt;")
			.replace(/>/g, "&gt;")
			.replace(/"/g, "&quot;")
			.replace(/'/g, "&#039;");
	}

	function formatMySuitePhone(value)
	{
		const digits = String(value || "").replace(/\D/g, "").slice(0, 11);
		if (!digits) return "";
		if (digits.length <= 3) return digits.length === 3 ? digits + "-" : digits;
		if (digits.length <= 7) return digits.slice(0, 3) + "-" + digits.slice(3) + (digits.length === 7 ? "-" : "");
		return digits.slice(0, 3) + "-" + digits.slice(3, 7) + "-" + digits.slice(7);
	}

	function bindMySuitePhoneInput(input)
	{
		if (!input || input.dataset.mySuitePhoneBound === "1") return;
		input.dataset.mySuitePhoneBound = "1";
		input.addEventListener("keydown", (event) => {
			if (event.key !== "Backspace") return;
			const start = input.selectionStart || 0;
			const end = input.selectionEnd || start;
			if (start !== end || start < 1 || input.value[start - 1] !== "-") return;
			event.preventDefault();
			const beforeDigits = input.value.slice(0, start - 1).replace(/\D/g, "");
			const afterDigits = input.value.slice(start).replace(/\D/g, "");
			const digits = (beforeDigits.slice(0, -1) + afterDigits).slice(0, 11);
			input.value = formatMySuitePhone(digits);
			const nextDigitCount = Math.max(0, beforeDigits.length - 1);
			let pos = 0;
			let seen = 0;
			while (pos < input.value.length && seen < nextDigitCount) {
				if (/\d/.test(input.value[pos])) seen += 1;
				pos += 1;
			}
			try { input.setSelectionRange(pos, pos); } catch (err) {}
		});
		input.addEventListener("input", () => {
			const formatted = formatMySuitePhone(input.value);
			input.value = formatted;
			try { input.setSelectionRange(formatted.length, formatted.length); } catch (err) {}
		});
		if (input.value) input.value = formatMySuitePhone(input.value);
	}

	const REALJEJU_PROFILE_PHOTO_MAX_DIMENSION = 500;
	const REALJEJU_PROFILE_PHOTO_JPEG_QUALITY = 0.80;
	const REALJEJU_PROFILE_PHOTO_FORCE_JPEG_MIN_BYTES = 150 * 1024;

	function getRealjejuSafeImageExt(file, fallback = "jpg")
	{
		const fromName = String(file && file.name || "")
			.split(".")
			.pop()
			.toLowerCase()
			.replace(/[^a-z0-9]/g, "");
		if (fromName) return fromName === "jpeg" ? "jpg" : fromName;
		const type = String(file && file.type || "").toLowerCase();
		if (type.includes("png")) return "png";
		if (type.includes("webp")) return "webp";
		if (type.includes("gif")) return "gif";
		if (type.includes("jpeg") || type.includes("jpg")) return "jpg";
		return fallback;
	}

	function loadRealjejuImageElement(src)
	{
		return new Promise((resolve, reject) => {
			const img = new Image();
			img.onload = () => resolve(img);
			img.onerror = reject;
			img.src = src;
		});
	}

	function canvasToRealjejuBlob(canvas, type, quality)
	{
		return new Promise((resolve) => {
			if (!canvas || typeof canvas.toBlob !== "function") return resolve(null);
			canvas.toBlob(resolve, type, quality);
		});
	}

	async function compressRealjejuProfilePhotoFile(file)
	{
		if (!file || !/^image\//.test(file.type || "") || String(file.type || "").toLowerCase().includes("svg")) return null;
		if (typeof document === "undefined") return null;
		let source = null;
		let objectUrl = "";
		try {
			if (typeof createImageBitmap === "function") {
				try {
					source = await createImageBitmap(file, { imageOrientation: "from-image" });
				} catch (bitmapErr) {
					source = null;
				}
			}
			if (!source && typeof URL !== "undefined" && typeof URL.createObjectURL === "function") {
				objectUrl = URL.createObjectURL(file);
				source = await loadRealjejuImageElement(objectUrl);
			}
			const width = source && (source.width || source.naturalWidth) || 0;
			const height = source && (source.height || source.naturalHeight) || 0;
			if (!width || !height) return null;
			const scale = Math.min(1, REALJEJU_PROFILE_PHOTO_MAX_DIMENSION / Math.max(width, height));
			const targetWidth = Math.max(1, Math.round(width * scale));
			const targetHeight = Math.max(1, Math.round(height * scale));
			const canvas = document.createElement("canvas");
			canvas.width = targetWidth;
			canvas.height = targetHeight;
			const ctx = canvas.getContext("2d", { alpha: false });
			if (!ctx) return null;
			ctx.fillStyle = "#ffffff";
			ctx.fillRect(0, 0, targetWidth, targetHeight);
			ctx.drawImage(source, 0, 0, targetWidth, targetHeight);
			const blob = await canvasToRealjejuBlob(canvas, "image/jpeg", REALJEJU_PROFILE_PHOTO_JPEG_QUALITY);
			const isPngSource = String(file.type || "").toLowerCase().includes("png") || /\.png$/i.test(String(file.name || ""));
			const shouldForceJpeg = isPngSource && (file.size >= REALJEJU_PROFILE_PHOTO_FORCE_JPEG_MIN_BYTES || Math.max(width, height) > REALJEJU_PROFILE_PHOTO_MAX_DIMENSION);
			if (!blob || !blob.size || (blob.size >= file.size && !shouldForceJpeg)) return null;
			return blob;
		} catch (err) {
			console.warn("프로필 사진 압축 실패:", err);
			return null;
		} finally {
			if (source && typeof source.close === "function") source.close();
			if (objectUrl && typeof URL !== "undefined" && typeof URL.revokeObjectURL === "function") {
				URL.revokeObjectURL(objectUrl);
			}
		}
	}

	async function prepareRealjejuProfilePhotoUpload(file)
	{
		const originalExt = getRealjejuSafeImageExt(file);
		const compressedBlob = await compressRealjejuProfilePhotoFile(file);
		if (compressedBlob) {
			return { body: compressedBlob, ext: "jpg", contentType: "image/jpeg" };
		}
		return { body: file, ext: originalExt, contentType: file && file.type ? file.type : undefined };
	}
	if (typeof window !== "undefined") {
		window.prepareRealjejuProfilePhotoUpload = prepareRealjejuProfilePhotoUpload;
	}

	async function uploadMySuiteProfilePhotoIfNeeded(client, userId)
	{
		if (!mySuiteProfilePhotoFile || !client || !userId) return mySuiteProfilePhotoUrl || "";
		const upload = await prepareRealjejuProfilePhotoUpload(mySuiteProfilePhotoFile);
		const ext = upload.ext || "jpg";
		const bucket = client.storage.from("profiles");
		const filePath = `${userId}/profile-${Date.now()}.${ext}`;
		try {
			const uploadOptions = {
				cacheControl: "3600",
				upsert: true
			};
			if (upload.contentType) uploadOptions.contentType = upload.contentType;
			const { data, error } = await bucket.upload(filePath, upload.body, uploadOptions);
			if (error) {
				console.warn("마이페이지 프로필 사진 업로드 실패:", error);
				return mySuiteProfilePhotoUrl || "";
			}
			const savedPath = data && data.path ? data.path : filePath;
			try {
				const { data: listData, error: listError } = await bucket.list(userId, { limit: 100, offset: 0, sortBy: { column: "created_at", order: "desc" } });
				if (!listError && Array.isArray(listData)) {
					const removeTargets = listData
						.map((item) => item && item.name ? `${userId}/${item.name}` : "")
						.filter((path) => path && path !== savedPath && /^.+\/profile-/i.test(path));
					if (removeTargets.length) {
						const { error: removeError } = await bucket.remove(removeTargets);
						if (removeError) console.warn("마이페이지 이전 프로필 사진 삭제 실패:", removeError);
					}
				}
			} catch (cleanupErr) {
				console.warn("마이페이지 이전 프로필 사진 정리 오류:", cleanupErr);
			}
			const { data: urlData } = bucket.getPublicUrl(savedPath);
			return urlData && urlData.publicUrl ? urlData.publicUrl : (mySuiteProfilePhotoUrl || "");
		} catch (err) {
			console.warn("마이페이지 프로필 사진 업로드 오류:", err);
			return mySuiteProfilePhotoUrl || "";
		}
	}

	async function fetchMySuiteProfileAndBrokerOffice()
	{
		const client = getRealjejuSupabaseClient();
		if (!client) return { user: null, profile: null, brokerOffice: null };
		const { data: userData } = await client.auth.getUser();
		const user = userData && userData.user ? userData.user : (window.realjejuCurrentAuthUser || (typeof currentRealjejuAuthUser !== "undefined" ? currentRealjejuAuthUser : null) || null);
		if (!user || !user.id) return { user: null, profile: null, brokerOffice: null };
		const { data: profile } = await client
			.from("profiles")
			.select("status, name, email, phone, role, role_request, profile_completed, profile_image")
			.eq("id", user.id)
			.maybeSingle();
		let brokerOffice = null;
		if (isRealjejuBrokerRole(profile && profile.role_request)) {
			try {
				const officeRows = await fetchMySuiteBrokerOfficeRows(client, user, profile || null);
				brokerOffice = pickCurrentRealjejuBrokerOffice(officeRows, user);
			} catch (err) {
				brokerOffice = null;
			}
		}
		return { user, profile: profile || null, brokerOffice };
	}

