	function syncRealjejuMySuitePanelFooter(tabKey)
	{
		const inner = document.querySelector("#mySuitePanel > .my-suite-inner");
		if (!inner) return;
		const currentFooter = inner.querySelector(":scope > footer");
		const shouldUseAccountFooter = tabKey === "inquiries";
		if (shouldUseAccountFooter) {
			if (currentFooter && currentFooter.classList.contains("account-page-common-footer")) return;
			const commonFooter = getRealjejuMyInfoCommonFooterElement();
			if (!commonFooter) return;
			if (currentFooter) currentFooter.replaceWith(commonFooter);
			else inner.appendChild(commonFooter);
			return;
		}
		if (!currentFooter || !currentFooter.classList.contains("account-page-common-footer")) return;
		currentFooter.replaceWith(getRealjejuMySuiteMiniFooterElement());
	}

