		window.realjejuRenderMySuiteFavoritesContent = renderMySuiteFavoritesContent;

		function renderMySuiteBasicContent(key)
		{
			const content = document.getElementById("mySuiteContent");
			if (!content) return;
		const copy = mySuiteTabCopy[key] || mySuiteTabCopy.favorites;
		content.className = key === "reports" ? "my-suite-content my-suite-reports-content" : "my-suite-content";
		content.innerHTML = `
			<h2 class="my-suite-content-title" id="mySuiteContentTitle">${escapeMySuiteHtml(copy[0])}</h2>
			<p class="my-suite-content-desc" id="mySuiteContentDesc">${escapeMySuiteHtml(copy[1])}</p>
			`;
		}

		const REALJEJU_EMPTY_BROKER_LIMITS = Object.freeze({
			listings: 0,
			premium: 0,
			relist: 0,
			contracts: 0
		});
		const REALJEJU_EMPTY_BROKER_USAGE = Object.freeze({
			listings: 0,
			premium: 0,
			relist: 0,
			contracts: 0
		});
		const REALJEJU_PAYMENT_PLAN_COUPON_KEYS = Object.freeze(["starter", "premium", "pro"]);
		let realjejuCurrentPaymentPlanState = {
			loaded: false,
			userId: "",
			key: "none",
			label: "이용권 없음",
			status: "inactive",
			start: "",
			end: "",
			periodText: "이용권 정보 확인 중",
			active: false,
			nextPlan: null,
			scheduledPlans: [],
			limits: { ...REALJEJU_EMPTY_BROKER_LIMITS },
			baseLimits: { ...REALJEJU_EMPTY_BROKER_LIMITS },
			quotaGrants: [],
			quotaGrantsLoaded: false,
			usage: { ...REALJEJU_EMPTY_BROKER_USAGE },
			coupons: {},
			couponOrder: [],
			couponGroups: [],
			couponsLoaded: false
		};
		let realjejuPaymentPlanLoadPromise = null;

		function formatRealjejuEntitlementDate(value)
		{
			if (value === null || value === undefined || value === "" || value === 0 || value === "0") return "";
			const date = new Date(value);
			if (Number.isNaN(date.getTime())) return "";
			if (date.getUTCFullYear() <= 1970) return "";
			const parts = new Intl.DateTimeFormat("ko-KR", {
				timeZone: "Asia/Seoul",
				year: "numeric",
				month: "2-digit",
				day: "2-digit"
			}).formatToParts(date);
			const getPart = (type) => parts.find((part) => part.type === type)?.value || "";
			return `${getPart("year")}.${getPart("month")}.${getPart("day")}`;
		}

		function normalizeRealjejuPaymentPlanState(
			value,
			userId,
			quotaGrantRows = null,
			couponRows = null,
			scheduledPlanRows = null
		)
		{
			let row = value;
			if (Array.isArray(row)) row = row[0] || null;
			if (typeof row === "string") {
				try {
					row = JSON.parse(row);
				} catch (_) {
					row = null;
				}
			}
			row = row && typeof row === "object" ? row : {};
			const rawLimits = row.limits && typeof row.limits === "object" ? row.limits : {};
			const rawBaseLimits = row.base_limits && typeof row.base_limits === "object" ? row.base_limits : {};
			const rawUsage = row.usage && typeof row.usage === "object" ? row.usage : {};
			const rawCoupons = row.coupons && typeof row.coupons === "object" ? row.coupons : {};
			const rawNextPlan = row.next_plan && typeof row.next_plan === "object" ? row.next_plan : null;
			const start = formatRealjejuEntitlementDate(row.starts_at);
			const end = formatRealjejuEntitlementDate(row.ends_at);
			const periodText = start && end ? `${start} ~ ${end}` : (start || end || "기간 미설정");
			const rawScheduledPlans = Array.isArray(scheduledPlanRows)
				? [...scheduledPlanRows]
				: (Array.isArray(row.scheduled_plans) ? [...row.scheduled_plans] : []);
			if (!rawScheduledPlans.length && rawNextPlan) rawScheduledPlans.push(rawNextPlan);
			const scheduledPlans = rawScheduledPlans.map((rawPlan) => {
				const nextStart = formatRealjejuEntitlementDate(rawPlan && rawPlan.starts_at);
				const nextEnd = formatRealjejuEntitlementDate(rawPlan && rawPlan.ends_at);
				return {
					key: String(rawPlan && rawPlan.plan_key || ""),
					label: String(rawPlan && rawPlan.plan_label || "다음 이용권"),
					status: String(rawPlan && rawPlan.status || "scheduled"),
					start: nextStart,
					end: nextEnd,
					periodText: nextStart && nextEnd ? `${nextStart} ~ ${nextEnd}` : (nextStart || nextEnd || "기간 미설정")
				};
			}).filter((plan) => plan.key);
			const nextPlan = scheduledPlans[0] || null;
			const now = Date.now();
			const quotaGrantsLoaded = Array.isArray(quotaGrantRows);
			const couponRowsLoaded = Array.isArray(couponRows);
			const couponCounts = {};
			const couponOrder = [];
			const couponGroupsByKey = new Map();
			(couponRowsLoaded ? couponRows : []).forEach((coupon) => {
				const productKey = String(coupon && coupon.product_key || "").trim();
				if (!productKey) return;
				const isPlanCoupon = REALJEJU_PAYMENT_PLAN_COUPON_KEYS.includes(productKey);
				const durationDays = isPlanCoupon
					? Math.max(1, normalizeRealjejuNonnegativeCount(coupon && coupon.duration_days) || 30)
					: (normalizeRealjejuNonnegativeCount(coupon && coupon.duration_days) || null);
				const groupKey = isPlanCoupon ? `${productKey}:${durationDays}` : productKey;
				couponCounts[productKey] = normalizeRealjejuNonnegativeCount(couponCounts[productKey]) + 1;
				if (!couponOrder.includes(groupKey)) couponOrder.push(groupKey);
				const currentGroup = couponGroupsByKey.get(groupKey);
				if (currentGroup) {
					currentGroup.count += 1;
					return;
				}
				couponGroupsByKey.set(groupKey, {
					key: groupKey,
					productKey,
					durationDays,
					count: 1
				});
			});
			const fallbackCoupons = Object.fromEntries(Object.entries(rawCoupons).map(([key, count]) => [
				String(key),
				normalizeRealjejuNonnegativeCount(count)
			]));
			if (!couponRowsLoaded) {
				Object.entries(fallbackCoupons).forEach(([productKey, count]) => {
					if (count < 1) return;
					const isPlanCoupon = REALJEJU_PAYMENT_PLAN_COUPON_KEYS.includes(productKey);
					const durationDays = isPlanCoupon ? 30 : null;
					const groupKey = isPlanCoupon ? `${productKey}:${durationDays}` : productKey;
					couponOrder.push(groupKey);
					couponGroupsByKey.set(groupKey, {
						key: groupKey,
						productKey,
						durationDays,
						count
					});
				});
			}
			const quotaGrants = quotaGrantsLoaded ? quotaGrantRows.reduce((grants, grant) => {
				const quotaType = String(grant?.quota_type || "");
				const amount = normalizeRealjejuNonnegativeCount(grant?.amount);
				const validFrom = String(grant?.valid_from || "");
				const validUntil = String(grant?.valid_until || "");
				const validFromTime = validFrom ? Date.parse(validFrom) : Number.NaN;
				const validUntilTime = validUntil ? Date.parse(validUntil) : Number.NaN;
				if (!Object.prototype.hasOwnProperty.call(REALJEJU_EMPTY_BROKER_LIMITS, quotaType) || amount < 1) return grants;
				if (Number.isFinite(validFromTime) && validFromTime > now) return grants;
				if (Number.isFinite(validUntilTime) && validUntilTime < now) return grants;
				grants.push({ quotaType, amount, validUntil });
				return grants;
			}, []) : [];
			return {
				loaded: true,
				userId: String(userId || row.user_id || ""),
				key: String(row.plan_key || "none"),
				label: String(row.plan_label || "이용권 없음"),
				status: String(row.status || "inactive"),
				start,
				end,
				periodText,
				active: row.active === true,
				nextPlan,
				scheduledPlans,
				limits: {
					listings: normalizeRealjejuNonnegativeCount(rawLimits.listings),
					premium: normalizeRealjejuNonnegativeCount(rawLimits.premium),
					relist: normalizeRealjejuNonnegativeCount(rawLimits.relist),
					contracts: normalizeRealjejuNonnegativeCount(rawLimits.contracts)
				},
				baseLimits: {
					listings: normalizeRealjejuNonnegativeCount(rawBaseLimits.listings),
					premium: normalizeRealjejuNonnegativeCount(rawBaseLimits.premium),
					relist: normalizeRealjejuNonnegativeCount(rawBaseLimits.relist),
					contracts: normalizeRealjejuNonnegativeCount(rawBaseLimits.contracts)
				},
				quotaGrants,
				quotaGrantsLoaded,
				usage: {
					listings: normalizeRealjejuNonnegativeCount(rawUsage.listings),
					premium: normalizeRealjejuNonnegativeCount(rawUsage.premium),
					relist: normalizeRealjejuNonnegativeCount(rawUsage.relist),
					contracts: normalizeRealjejuNonnegativeCount(rawUsage.contracts)
				},
				coupons: couponRowsLoaded ? couponCounts : fallbackCoupons,
				couponOrder,
				couponGroups: Array.from(couponGroupsByKey.values()),
				couponsLoaded: true
			};
		}

		function resetRealjejuPaymentPlanState()
		{
			realjejuCurrentPaymentPlanState = {
				loaded: false,
				userId: "",
				key: "none",
				label: "이용권 없음",
				status: "inactive",
				start: "",
				end: "",
				periodText: "로그인 후 확인",
				active: false,
				nextPlan: null,
				scheduledPlans: [],
				limits: { ...REALJEJU_EMPTY_BROKER_LIMITS },
				baseLimits: { ...REALJEJU_EMPTY_BROKER_LIMITS },
				quotaGrants: [],
				quotaGrantsLoaded: false,
				usage: { ...REALJEJU_EMPTY_BROKER_USAGE },
				coupons: {},
				couponOrder: [],
				couponGroups: [],
				couponsLoaded: false
			};
		}

		async function refreshRealjejuPaymentPlanState(options = {})
		{
			const client = typeof getRealjejuSupabaseClient === "function" ? getRealjejuSupabaseClient() : null;
			if (!client) {
				resetRealjejuPaymentPlanState();
				applyRealjejuPaymentPlanState(document);
				return realjejuCurrentPaymentPlanState;
			}
			if (realjejuPaymentPlanLoadPromise && options.force !== true) return realjejuPaymentPlanLoadPromise;

			realjejuPaymentPlanLoadPromise = (async () => {
				let user = window.realjejuCurrentAuthUser || (typeof currentRealjejuAuthUser !== "undefined" ? currentRealjejuAuthUser : null) || null;
				if (!user || !user.id) {
					const { data: userData, error: userError } = await client.auth.getUser();
					if (userError) throw userError;
					user = userData && userData.user ? userData.user : null;
				}
				if (!user || !user.id) {
					resetRealjejuPaymentPlanState();
					applyRealjejuPaymentPlanState(document);
					return realjejuCurrentPaymentPlanState;
				}
				if (
					options.force !== true
					&& realjejuCurrentPaymentPlanState.loaded
					&& realjejuCurrentPaymentPlanState.userId === String(user.id)
				) {
					return realjejuCurrentPaymentPlanState;
				}
				const { data, error } = await client.rpc("get_my_broker_entitlement");
				if (error) throw error;
				let quotaGrantRows = null;
				let couponRows = null;
				let scheduledPlanRows = null;
				const [
					{ data: grantData, error: grantError },
					{ data: couponData, error: couponError },
					{ data: scheduleData, error: scheduleError }
				] = await Promise.all([
					client
						.from("broker_quota_grants")
						.select("quota_type, amount, valid_from, valid_until")
						.eq("user_id", user.id)
						.eq("status", "active"),
					client
						.from("broker_coupons")
						.select("id, product_key, duration_days, created_at")
						.eq("user_id", user.id)
						.eq("status", "available")
						.order("created_at", { ascending: true })
						.order("id", { ascending: true })
						.limit(500),
					client
						.from("broker_plan_schedule")
						.select("id, plan_key, plan_label, starts_at, ends_at, status, created_at")
						.eq("user_id", user.id)
						.eq("status", "scheduled")
						.gt("ends_at", new Date().toISOString())
						.order("starts_at", { ascending: true })
						.order("created_at", { ascending: true })
						.order("id", { ascending: true })
				]);
				if (!grantError) quotaGrantRows = Array.isArray(grantData) ? grantData : [];
				if (!couponError) couponRows = Array.isArray(couponData) ? couponData : [];
				if (!scheduleError) scheduledPlanRows = Array.isArray(scheduleData) ? scheduleData : [];
				realjejuCurrentPaymentPlanState = normalizeRealjejuPaymentPlanState(
					data,
					user.id,
					quotaGrantRows,
					couponRows,
					scheduledPlanRows
				);
				applyRealjejuPaymentPlanState(document);
				return realjejuCurrentPaymentPlanState;
			})().catch((error) => {
				console.error("중개사 이용권 DB 조회 실패:", error);
				resetRealjejuPaymentPlanState();
				realjejuCurrentPaymentPlanState.loaded = true;
				realjejuCurrentPaymentPlanState.periodText = "이용권 DB 연결 필요";
				applyRealjejuPaymentPlanState(document);
				return realjejuCurrentPaymentPlanState;
			}).finally(() => {
				realjejuPaymentPlanLoadPromise = null;
			});
			return realjejuPaymentPlanLoadPromise;
		}
		window.refreshRealjejuPaymentPlanState = refreshRealjejuPaymentPlanState;

		function getRealjejuCurrentPaymentPlanState()
		{
			return realjejuCurrentPaymentPlanState;
		}

		function getRealjejuActivePaymentLimits()
		{
			const state = getRealjejuCurrentPaymentPlanState();
			if (!state.active) return { listings: 0, premium: 0, relist: 0, contracts: 0 };
			return state.limits || { listings: 0, premium: 0, relist: 0, contracts: 0 };
		}

		function hasRealjejuActivePaymentPlan()
		{
			return getRealjejuCurrentPaymentPlanState().active;
		}

		function guardRealjejuActivePaymentPlan(title)
		{
			if (hasRealjejuActivePaymentPlan()) return true;
			openAuthErrorModal("이용권 기간이 만료되었습니다.\n이용권 결제 후 이용해 주세요.", title || "이용권", null);
			return false;
		}

		function getRealjejuPaymentPlanButtonHtml(planKey)
		{
			const state = getRealjejuCurrentPaymentPlanState();
			const isCurrent = state.active && state.key === planKey;
			const className = isCurrent ? "payment-plan-btn is-current" : "payment-plan-btn";
			const attrs = ' aria-disabled="false"';
			const label = isCurrent ? "현재 플랜" : "이용권 선택";
			return `<button type="button" class="${className}" data-plan="${planKey}"${attrs}>${label}</button>`;
		}

		function getRealjejuPaymentPlanPeriodHtml()
		{
			return "";
		}

