		function renderRealjejuPaymentAddonShops(root = document)
		{
			const scope = root && root.querySelectorAll ? root : document;
			scope.querySelectorAll("[data-payment-addon-grid]").forEach((grid) => {
				if (grid.dataset.paymentAddonRendered === "true") return;
				grid.innerHTML = getRealjejuPaymentAddonCardsHtml();
				grid.dataset.paymentAddonRendered = "true";
			});
		}

		function applyRealjejuPaymentAddonEligibility(scope, state)
		{
			const eligible = !!(state.active && (state.key === "premium" || state.key === "pro"));
			scope.querySelectorAll("[data-addon-purchase-card]").forEach((card) => {
				card.classList.toggle("is-unavailable", !eligible);
				const button = card.querySelector("[data-addon-purchase-button]");
				if (!button) return;
				button.disabled = !eligible;
				button.setAttribute("aria-disabled", eligible ? "false" : "true");
				button.textContent = eligible ? "구매하기" : "이용권 필요";
			});
		}

		function getRealjejuPaymentQuotaGrantGroups(state, quotaType)
		{
			if (!state.active) return [];
			const groups = new Map();
			(state.quotaGrants || []).forEach((grant) => {
				if (grant.quotaType !== quotaType) return;
				const expiresOn = formatRealjejuEntitlementDate(grant.validUntil);
				const key = expiresOn || "no-expiry";
				const current = groups.get(key) || { amount: 0, expiresOn };
				current.amount += normalizeRealjejuNonnegativeCount(grant.amount);
				groups.set(key, current);
			});
			const rows = Array.from(groups.values()).filter((group) => group.amount > 0);
			if (!rows.length && state.quotaGrantsLoaded !== true) {
				const total = normalizeRealjejuNonnegativeCount(state.limits?.[quotaType]);
				const base = normalizeRealjejuNonnegativeCount(state.baseLimits?.[quotaType]);
				if (total > base) rows.push({ amount: total - base, expiresOn: "" });
			}
			return rows.sort((left, right) => {
				if (!left.expiresOn) return 1;
				if (!right.expiresOn) return -1;
				return left.expiresOn.localeCompare(right.expiresOn);
			});
		}

		function renderRealjejuPaymentQuotaGrantDetails(summary, state)
		{
			["listings", "relist", "premium", "contracts"].forEach((quotaType) => {
				const item = summary.querySelector(`[data-payment-current-limit-item="${quotaType}"]`);
				const list = summary.querySelector(`[data-payment-current-addons="${quotaType}"]`);
				if (!list) return;
				list.replaceChildren();
				const groups = getRealjejuPaymentQuotaGrantGroups(state, quotaType);
				groups.forEach((group) => {
					const row = document.createElement("span");
					row.className = "payment-current-addon-item";
					const amount = document.createElement("b");
					amount.textContent = `+${group.amount.toLocaleString("ko-KR")}건`;
					row.appendChild(amount);
					if (group.expiresOn) row.appendChild(document.createTextNode(` · ${group.expiresOn}까지`));
					list.appendChild(row);
				});
				list.hidden = groups.length === 0;
				if (item) item.classList.toggle("has-addons", groups.length > 0);
			});
		}

		function renderRealjejuPaymentScheduledPlans(summary, state)
		{
			const list = summary.querySelector("[data-payment-next-plans]");
			if (!list) return;
			const scheduledPlans = Array.isArray(state.scheduledPlans) && state.scheduledPlans.length
				? state.scheduledPlans
				: (state.nextPlan ? [state.nextPlan] : []);
			list.innerHTML = scheduledPlans.map((plan) => `
				<div class="payment-next-plan-row" data-payment-next-plan>
					<div class="payment-current-plan-main">
						<span class="payment-current-label">다음 이용권</span>
						<div class="payment-current-plan-name-row">
							<strong>${escapeHtml(plan.label || "다음 이용권")}</strong>
							<span class="payment-current-status is-scheduled">예약중</span>
						</div>
					</div>
					<div class="payment-current-date-box">
						<span>플랜 이용기간</span>
						<strong>${escapeHtml(plan.periodText || "기간 미설정")}</strong>
					</div>
				</div>
			`).join("");
			list.hidden = scheduledPlans.length === 0;
		}

		function applyRealjejuPaymentPlanState(root = document)
		{
			const scope = root && root.querySelector ? root : document;
			const state = getRealjejuCurrentPaymentPlanState();
			scope.querySelectorAll(".payment-plan-btn[data-plan]").forEach((btn) => {
				const planKey = btn.getAttribute("data-plan");
				const isCurrent = state.active && state.key === planKey;
				btn.classList.remove("is-secondary");
				btn.classList.toggle("is-current", isCurrent);
				btn.disabled = false;
				btn.setAttribute("aria-disabled", "false");
				btn.textContent = isCurrent ? "현재 플랜" : "이용권 선택";
			});
			scope.querySelectorAll(".payment-plan-period").forEach((period) => period.remove());
			scope.querySelectorAll("[data-payment-current-summary]").forEach((summary) => {
				const name = summary.querySelector("[data-payment-current-plan-name]");
				const period = summary.querySelector("[data-payment-current-period]");
				const periodBox = summary.querySelector(".payment-current-date-box");
				const status = summary.querySelector("[data-payment-current-status]");
				const hasPlanPeriod = state.loaded
					&& state.key !== "none"
					&& Boolean(state.start || state.end);
				if (name) name.textContent = state.loaded ? state.label : "이용권 확인 중";
				if (period) period.textContent = hasPlanPeriod ? state.periodText : "";
				if (periodBox) periodBox.hidden = state.loaded && !hasPlanPeriod;
				if (status) {
					const statusText = !state.loaded
						? "확인중"
						: (state.active ? "이용중" : (state.status === "expired" ? "만료" : "미사용"));
					status.textContent = statusText;
					status.classList.toggle("is-expired", state.loaded && !state.active);
				}
				renderRealjejuPaymentScheduledPlans(summary, state);
				const currentLimits = state.limits || {};
				const limitValues = {
					listings: Number(currentLimits.listings) || 0,
					relist: Number(currentLimits.relist) || 0,
					premium: Number(currentLimits.premium) || 0,
					contracts: Number(currentLimits.contracts) || 0
				};
				Object.entries(limitValues).forEach(([key, value]) => {
					const limit = summary.querySelector(`[data-payment-current-limit="${key}"]`);
					if (limit) limit.textContent = `${Math.max(0, value).toLocaleString("ko-KR")}건`;
				});
				renderRealjejuPaymentQuotaGrantDetails(summary, state);
			});
			scope.querySelectorAll(".payment-coupon-use-btn[data-coupon-plan]").forEach((button) => {
				const productKey = String(button.dataset.couponPlan || "");
				button.dataset.couponCount = String(normalizeRealjejuNonnegativeCount(state.coupons?.[productKey]));
				syncRealjejuPaymentCouponCountBadge(button);
			});
			syncRealjejuPaymentCouponLayout(scope, state);
			applyRealjejuPaymentAddonEligibility(scope, state);
		}

		function syncRealjejuPaymentCouponCountBadge(button)
		{
			if (!button || typeof button.closest !== "function") return;
			const card = button.closest(".payment-coupon-card");
			if (!card) return;
			const parsedCount = Number.parseInt(
				String(button.dataset.couponCount ?? card.dataset.couponCount ?? "0"),
				10
			);
			const count = Number.isFinite(parsedCount) && parsedCount >= 0 ? parsedCount : 0;
			let badge = card.querySelector(".payment-coupon-count");
			if (!badge) {
				badge = document.createElement("div");
				badge.className = "payment-coupon-count";
				const icon = document.createElement("i");
				icon.className = "fa-solid fa-ticket";
				icon.setAttribute("aria-hidden", "true");
				const value = document.createElement("span");
				value.setAttribute("data-payment-coupon-count-value", "");
				value.setAttribute("aria-hidden", "true");
				badge.append(icon, value);
				card.appendChild(badge);
			}
			badge.setAttribute("aria-label", `보유 쿠폰 ${count.toLocaleString("ko-KR")}개`);
			const value = badge.querySelector("[data-payment-coupon-count-value]");
			if (value) value.textContent = `× ${count.toLocaleString("ko-KR")}`;
			button.disabled = count < 1;
			button.setAttribute("aria-disabled", count < 1 ? "true" : "false");
			button.textContent = count < 1 ? "보유 쿠폰 없음" : "사용하기";
		}

		function bindRealjejuDynamicPaymentCouponButton(button)
		{
			if (!button || button.dataset.realjejuDynamicCouponBound === "true") return;
			button.dataset.realjejuDynamicCouponBound = "true";
			button.dataset.paymentCouponButtonBound = "true";
			button.dataset.mySuiteCouponButtonBound = "true";
			button.addEventListener("click", async () => {
				await useRealjejuBrokerCoupon(button);
			});
		}

		function configureRealjejuPlanCouponCard(card, group)
		{
			if (!card || !group) return null;
			const productKey = String(group.productKey || "").trim();
			const durationDays = Math.max(1, normalizeRealjejuNonnegativeCount(group.durationDays) || 30);
			const count = normalizeRealjejuNonnegativeCount(group.count);
			const planLabel = getRealjejuPaymentProductLabel(productKey);
			const kind = card.querySelector(".payment-coupon-kind");
			const title = card.querySelector("h2");
			const description = card.querySelector(".payment-coupon-desc");
			const button = card.querySelector(".payment-coupon-use-btn[data-coupon-plan]");
			if (kind) kind.textContent = `${durationDays.toLocaleString("ko-KR")}일 이용권`;
			if (title) title.textContent = `${planLabel} ${durationDays.toLocaleString("ko-KR")}일 이용권`;
			if (description) {
				const descriptions = {
					starter: `일반매물 100건과 하루 재등록 20건, 중개사홈을 ${durationDays.toLocaleString("ko-KR")}일 동안 이용할 수 있습니다.`,
					premium: `일반매물 300건, 하루 재등록 50건, 중개사홈, 프리미엄 매물 20건을 ${durationDays.toLocaleString("ko-KR")}일 동안 이용할 수 있습니다.`,
					pro: `일반매물 500건, 하루 재등록 100건, 중개사홈, 프리미엄 매물 50건을 ${durationDays.toLocaleString("ko-KR")}일 동안 이용할 수 있습니다.`
				};
				description.textContent = descriptions[productKey] || description.textContent;
			}
			if (button) {
				button.dataset.couponPlan = productKey;
				button.dataset.couponDurationDays = String(durationDays);
				button.dataset.couponCount = String(count);
				bindRealjejuDynamicPaymentCouponButton(button);
				syncRealjejuPaymentCouponCountBadge(button);
			}
			card.dataset.paymentDynamicPlanCoupon = "true";
			card.hidden = false;
			return card;
		}

		function configureRealjejuQuotaCouponCard(card, group)
		{
			if (!card || !group) return null;
			const productKey = String(group.productKey || "").trim();
			const count = normalizeRealjejuNonnegativeCount(group.count);
			const button = card.querySelector(".payment-coupon-use-btn[data-coupon-plan]");
			const title = card.querySelector("h2");
			if (!productKey || !button) return null;
			if (title) title.textContent = getRealjejuPaymentProductLabel(productKey);
			button.dataset.couponPlan = productKey;
			button.dataset.couponCount = String(count);
			if (normalizeRealjejuNonnegativeCount(group.durationDays) > 0) {
				button.dataset.couponDurationDays = String(normalizeRealjejuNonnegativeCount(group.durationDays));
			} else {
				delete button.dataset.couponDurationDays;
			}
			bindRealjejuDynamicPaymentCouponButton(button);
			syncRealjejuPaymentCouponCountBadge(button);
			card.dataset.paymentDynamicQuotaCoupon = "true";
			card.hidden = false;
			return card;
		}

		function syncRealjejuPaymentCouponLayout(root, state)
		{
			const scope = root && root.querySelectorAll ? root : document;
			const owners = [
				...(scope.matches && scope.matches(".payment-page-panel, .my-suite-payment-content") ? [scope] : []),
				...scope.querySelectorAll(".payment-page-panel, .my-suite-payment-content")
			];
			owners.forEach((owner) => {
				const primaryPanel = owner.querySelector(
					'.payment-account-card > [data-payment-panel="coupons"], .payment-account-card > [data-my-suite-payment-panel="coupons"]'
				);
				if (!primaryPanel) return;
				const grid = primaryPanel.querySelector(".payment-coupon-card-wrap");
				if (!grid) return;
				grid.setAttribute("data-payment-available-coupons-grid", "");
				owner.querySelectorAll("[data-payment-dynamic-plan-coupon]").forEach((card) => card.remove());

				const cardByProduct = new Map();
				const planTemplateByProduct = new Map();
				owner.querySelectorAll(".payment-coupon-use-btn[data-coupon-plan]").forEach((button) => {
					const productKey = String(button.dataset.couponPlan || "").trim();
					const card = button.closest(".payment-coupon-card");
					if (!productKey || !card) return;
					if (REALJEJU_PAYMENT_PLAN_COUPON_KEYS.includes(productKey)) {
						if (!planTemplateByProduct.has(productKey)) planTemplateByProduct.set(productKey, card);
						return;
					}
					if (!cardByProduct.has(productKey)) cardByProduct.set(productKey, card);
				});

				planTemplateByProduct.forEach((card) => {
					card.hidden = true;
				});
				cardByProduct.forEach((card) => {
					card.hidden = true;
				});

				const couponGroups = Array.isArray(state && state.couponGroups) ? state.couponGroups : [];
				const visibleCards = [];
				const usedNonPlanProducts = new Set();
				couponGroups.forEach((group) => {
					const productKey = String(group && group.productKey || "").trim();
					const count = normalizeRealjejuNonnegativeCount(group && group.count);
					if (!productKey || count < 1) return;
					if (REALJEJU_PAYMENT_PLAN_COUPON_KEYS.includes(productKey)) {
						const template = planTemplateByProduct.get(productKey);
						if (!template) return;
						const card = configureRealjejuPlanCouponCard(template.cloneNode(true), group);
						if (card) visibleCards.push(card);
						return;
					}
					if (usedNonPlanProducts.has(productKey)) return;
					let card = cardByProduct.get(productKey);
					if (!card) {
						const productFamily = productKey.split("-", 1)[0];
						const templateEntry = Array.from(cardByProduct.entries()).find(([key]) => key.split("-", 1)[0] === productFamily);
						if (!templateEntry) return;
						card = configureRealjejuQuotaCouponCard(templateEntry[1].cloneNode(true), group);
						if (!card) return;
					}
					const button = card.querySelector(".payment-coupon-use-btn[data-coupon-plan]");
					if (button) {
						button.dataset.couponCount = String(count);
						if (normalizeRealjejuNonnegativeCount(group.durationDays) > 0) {
							button.dataset.couponDurationDays = String(normalizeRealjejuNonnegativeCount(group.durationDays));
						} else {
							delete button.dataset.couponDurationDays;
						}
						syncRealjejuPaymentCouponCountBadge(button);
					}
					card.hidden = false;
					visibleCards.push(card);
					usedNonPlanProducts.add(productKey);
				});
				visibleCards.forEach((card) => grid.appendChild(card));

				owner.querySelectorAll(".payment-addon-coupon-shop").forEach((section) => {
					section.hidden = true;
				});

				let empty = primaryPanel.querySelector(".payment-coupon-empty");
				if (!empty) {
					empty = document.createElement("p");
					empty.className = "payment-coupon-empty";
					empty.textContent = "현재 이용 가능한 쿠폰이 없습니다.";
					primaryPanel.insertBefore(empty, primaryPanel.firstChild);
				}
				const loaded = state && state.couponsLoaded === true;
				empty.hidden = !loaded || visibleCards.length > 0;
				grid.hidden = visibleCards.length === 0;
			});
		}

		async function applyRealjejuBrokerCoupon(button, applyMode = "after_current")
		{
			if (!button || button.disabled) return false;
			const productKey = String(button.dataset.couponPlan || "").trim();
			if (!productKey) return false;
			const client = typeof getRealjejuSupabaseClient === "function" ? getRealjejuSupabaseClient() : null;
			if (!client) {
				openAuthErrorModal("Supabase 연결 설정을 확인하세요.", "쿠폰 사용", button);
				return false;
			}
			button.disabled = true;
			try {
				const durationDays = normalizeRealjejuNonnegativeCount(button.dataset.couponDurationDays);
				const isPlanCoupon = REALJEJU_PAYMENT_PLAN_COUPON_KEYS.includes(productKey);
				const rpcParams = { p_product_key: productKey };
				if (isPlanCoupon) {
					rpcParams.p_duration_days = Math.max(1, durationDays || 30);
					rpcParams.p_apply_mode = applyMode === "immediate" ? "immediate" : "after_current";
				} else if (durationDays > 0) {
					rpcParams.p_duration_days = durationDays;
				}
				const { data, error } = await client.rpc("use_my_broker_coupon", rpcParams);
				if (error) throw error;
				await refreshRealjejuPaymentPlanState({ force: true });
				void loadRealjejuPaymentHistory(document);
				const applied = data && typeof data === "object" ? data.applied : null;
				const scheduled = applied && applied.scheduled === true;
				const successMessage = scheduled
					? "쿠폰을 사용했습니다.\n다음 이용권으로 예약되었습니다."
					: (applyMode === "immediate" && isPlanCoupon
						? "쿠폰을 사용했습니다.\n새 이용권이 지금부터 적용되며 기존 이용권의 잔여 기간은 이후 다시 이어집니다."
						: "쿠폰을 사용했습니다.\n이용권과 사용 가능 한도에 반영되었습니다.");
				openAuthErrorModal(successMessage, "쿠폰 사용", null);
				return true;
			} catch (error) {
				console.error("쿠폰 사용 실패:", error);
				openAuthErrorModal(
					`쿠폰 사용에 실패했습니다${typeof formatAdminRpcError === "function" ? formatAdminRpcError(error) : ""}.\nsql/basic_contract_storage_coupon_5.159.sql 적용 상태를 확인하세요.`,
					"쿠폰 사용",
					button
				);
				return false;
			} finally {
				syncRealjejuPaymentCouponCountBadge(button);
			}
		}

		function openRealjejuCouponApplyModeModal(button, currentPlan, targetPlan)
		{
			if (typeof openAuthConfirmModal !== "function") {
				return applyRealjejuBrokerCoupon(button, "after_current");
			}
			const currentShortLabel = String(currentPlan?.label || "현재 이용권").replace(/\s*플랜\s*$/, "");
			const targetShortLabel = String(targetPlan || "새 이용권").replace(/\s*플랜\s*$/, "");
			openAuthConfirmModal(
				"",
				"쿠폰 사용",
				() => {
					const selected = document.querySelector('input[name="realjejuCouponApplyMode"]:checked');
					return applyRealjejuBrokerCoupon(button, selected && selected.value === "immediate" ? "immediate" : "after_current");
				},
				() => {
					if (typeof button.focus === "function") button.focus();
				}
			);
			const message = document.getElementById("authErrorMessage");
			if (!message) return true;
			message.replaceChildren();
			const content = document.createElement("span");
			content.className = "coupon-apply-mode-content";
			content.innerHTML = `
				<span class="coupon-apply-mode-intro">쿠폰 적용 방식을 선택하세요.</span>
				<label class="coupon-apply-mode-option">
					<input type="radio" name="realjejuCouponApplyMode" value="after_current" checked>
					<span>현재 이용권 종료 후 사용</span>
				</label>
				<label class="coupon-apply-mode-option">
					<input type="radio" name="realjejuCouponApplyMode" value="immediate">
					<span>지금부터 사용</span>
				</label>
				<span class="coupon-apply-mode-note">${escapeHtml(currentShortLabel)} 잔여 기간은 ${escapeHtml(targetShortLabel)} 이용 종료 후 다시 이어집니다.</span>
			`;
			message.appendChild(content);
			return true;
		}

		async function useRealjejuBrokerCoupon(button)
		{
			if (!button || button.disabled) return false;
			const card = button.closest(".payment-coupon-card");
			const couponTitle = String(card && card.querySelector("h2")?.textContent || "선택한 쿠폰").trim();
			const durationDays = normalizeRealjejuNonnegativeCount(button.dataset.couponDurationDays);
			const productKey = String(button.dataset.couponPlan || "").trim();
			const durationLine = durationDays > 0
				? `적용 기간 ${durationDays.toLocaleString("ko-KR")}일`
				: (productKey.startsWith("storage-") ? "적용 기간 제한 없음" : "");
			const planState = getRealjejuCurrentPaymentPlanState();
			const isDifferentActivePlan = REALJEJU_PAYMENT_PLAN_COUPON_KEYS.includes(productKey)
				&& planState.active
				&& planState.key !== productKey;
			if (isDifferentActivePlan) {
				return openRealjejuCouponApplyModeModal(
					button,
					planState,
					getRealjejuPaymentProductLabel(productKey)
				);
			}
			const message = [
				couponTitle,
				durationLine,
				"",
				"쿠폰을 사용하시겠습니까?"
			].filter((line, index, rows) => line || (index > 0 && rows[index - 1])).join("\n");
			if (typeof openAuthConfirmModal === "function") {
				openAuthConfirmModal(
					message,
					"쿠폰 사용",
					() => applyRealjejuBrokerCoupon(button, "after_current"),
					() => {
						if (typeof button.focus === "function") button.focus();
					}
				);
				return true;
			}
			if (window.confirm(message)) return applyRealjejuBrokerCoupon(button, "after_current");
			return false;
		}

		function getRealjejuPaymentProductLabel(productKey)
		{
			const labels = {
				starter: "베이직 플랜",
				premium: "프리미엄 플랜",
				pro: "프로 플랜",
				"premium-10": "프리미엄 매물 10건",
				"relist-10": "오늘 날짜 갱신권 10건",
				"relist-50": "오늘 날짜 갱신권 50건",
				"storage-100": "계약서 보관 100건"
			};
			return labels[String(productKey || "")] || String(productKey || "-");
		}

		function getRealjejuCouponHistoryProductLabel(row)
		{
			const quotaType = String(row?.quota_type || "");
			const amount = normalizeRealjejuNonnegativeCount(row?.amount);
			if (quotaType === "premium") return `프리미엄 매물 ${amount.toLocaleString("ko-KR")}건`;
			if (quotaType === "relist") return `오늘 날짜 갱신권 ${amount.toLocaleString("ko-KR")}건`;
			if (quotaType === "contracts") return `계약서 보관 ${amount.toLocaleString("ko-KR")}건`;
			if (quotaType === "listings") return `일반매물 ${amount.toLocaleString("ko-KR")}건`;
			const planKey = String(row?.plan_key || row?.product_key || "");
			const durationDays = Math.max(1, normalizeRealjejuNonnegativeCount(row?.duration_days) || 30);
			if (["starter", "premium", "pro"].includes(planKey)) {
				return `${getRealjejuPaymentProductLabel(planKey)} ${durationDays.toLocaleString("ko-KR")}일 이용권`;
			}
			return getRealjejuPaymentProductLabel(row?.product_key);
		}

		async function loadRealjejuPaymentHistory(root = document)
		{
			const scope = root && root.querySelectorAll ? root : document;
			const bodies = Array.from(scope.querySelectorAll(".payment-history-table tbody"));
			if (!bodies.length) return;
			const client = typeof getRealjejuSupabaseClient === "function" ? getRealjejuSupabaseClient() : null;
			if (!client) return;
			bodies.forEach((body) => {
				body.innerHTML = '<tr class="payment-empty-row"><td colspan="6">이용 내역을 불러오는 중입니다.</td></tr>';
			});
			try {
				const [paymentResult, couponResult] = await Promise.all([
					client
						.from("broker_payments")
						.select("id, order_id, payment_key, product_key, amount, currency, status, paid_at, created_at")
						.order("created_at", { ascending: false })
						.limit(100),
					client
						.from("broker_coupons")
						.select("id, product_key, plan_key, quota_type, amount, duration_days, status, used_at")
						.eq("status", "used")
						.not("used_at", "is", null)
						.order("used_at", { ascending: false })
						.limit(100)
				]);
				if (paymentResult.error) throw paymentResult.error;
				if (couponResult.error) throw couponResult.error;
				const paymentRows = Array.isArray(paymentResult.data) ? paymentResult.data : [];
				const couponRows = Array.isArray(couponResult.data) ? couponResult.data : [];
				const rows = [
					...paymentRows.map((row) => ({ kind: "payment", row, usedAt: row.paid_at || row.created_at })),
					...couponRows.map((row) => ({ kind: "coupon", row, usedAt: row.used_at }))
				].sort((left, right) => {
					const rightTime = Date.parse(right.usedAt || "") || 0;
					const leftTime = Date.parse(left.usedAt || "") || 0;
					return rightTime - leftTime;
				}).slice(0, 100);
				const html = rows.length ? rows.map((entry) => {
					const row = entry.row;
					if (entry.kind === "coupon") {
						const dateLabel = formatRealjejuEntitlementDate(entry.usedAt) || "-";
						return `<tr>
							<td>${escapeMySuiteHtml(dateLabel)}</td>
							<td>${escapeMySuiteHtml(getRealjejuCouponHistoryProductLabel(row))}</td>
							<td>쿠폰 사용</td>
							<td>0원</td>
							<td>적용완료</td>
							<td>-</td>
						</tr>`;
					}
					const paidAt = row.paid_at || row.created_at;
					const dateLabel = formatRealjejuEntitlementDate(paidAt) || "-";
					const amount = `${normalizeRealjejuNonnegativeCount(row.amount).toLocaleString("ko-KR")}원`;
					const statusLabel = {
						ready: "결제대기",
						paid: "결제완료",
						cancelled: "취소",
						refunded: "환불",
						failed: "실패"
					}[String(row.status || "")] || String(row.status || "-");
					return `<tr>
						<td>${escapeMySuiteHtml(dateLabel)}</td>
						<td>${escapeMySuiteHtml(getRealjejuPaymentProductLabel(row.product_key))}</td>
						<td>결제</td>
						<td>${escapeMySuiteHtml(amount)}</td>
						<td>${escapeMySuiteHtml(statusLabel)}</td>
						<td>${row.payment_key ? escapeMySuiteHtml(row.order_id || "-") : "-"}</td>
					</tr>`;
				}).join("") : '<tr class="payment-empty-row"><td colspan="6">아직 이용 내역이 없습니다.</td></tr>';
				bodies.forEach((body) => {
					body.innerHTML = html;
				});
			} catch (error) {
				console.error("이용 내역 DB 조회 실패:", error);
				bodies.forEach((body) => {
					body.innerHTML = '<tr class="payment-empty-row"><td colspan="6">이용 내역을 불러오지 못했습니다.</td></tr>';
				});
			}
		}

			window.realjejuHasActivePaymentPlan = hasRealjejuActivePaymentPlan;
			window.realjejuGetCurrentPaymentPlanState = getRealjejuCurrentPaymentPlanState;
			window.realjejuGetActivePaymentLimits = getRealjejuActivePaymentLimits;
			window.realjejuGuardActivePaymentPlan = guardRealjejuActivePaymentPlan;
			window.realjejuApplyPaymentPlanState = applyRealjejuPaymentPlanState;
			window.realjejuRefreshPaymentPlanState = refreshRealjejuPaymentPlanState;
			window.realjejuRenderPaymentAddonShops = renderRealjejuPaymentAddonShops;
			window.realjejuSyncPaymentCouponCountBadge = syncRealjejuPaymentCouponCountBadge;
			window.realjejuUseBrokerCoupon = useRealjejuBrokerCoupon;
			window.realjejuLoadPaymentHistory = loadRealjejuPaymentHistory;

		function bindMySuitePaymentContent()
		{
			const content = document.getElementById("mySuiteContent");
			if (!content) return;
		content.querySelectorAll("[data-my-suite-payment-tab]").forEach((btn) => {
			if (btn.dataset.mySuitePaymentBound === "true") return;
			btn.dataset.mySuitePaymentBound = "true";
			btn.addEventListener("click", () => {
				const target = btn.getAttribute("data-my-suite-payment-tab");
				content.querySelectorAll("[data-my-suite-payment-tab]").forEach((tab) => {
					const active = tab === btn;
					tab.classList.toggle("active", active);
					tab.setAttribute("aria-selected", active ? "true" : "false");
				});
				content.querySelectorAll("[data-my-suite-payment-panel]").forEach((panel) => {
					panel.classList.toggle("active", panel.getAttribute("data-my-suite-payment-panel") === target);
				});
				if (target === "history") void loadRealjejuPaymentHistory(content);
			});
		});
		content.querySelectorAll(".payment-plan-btn[data-plan], .payment-extra-item, [data-addon-purchase-button]").forEach((btn) => {
			if (btn.dataset.mySuitePaymentButtonBound === "true") return;
			btn.dataset.mySuitePaymentButtonBound = "true";
			btn.addEventListener("click", () => {
				if (btn.disabled) return;
				alert("토스페이먼츠 연동 준비중입니다. 테스트 결제 연결 후 실제 결제가 가능합니다.");
			});
		});
		content.querySelectorAll(".payment-coupon-use-btn").forEach((btn) => {
			syncRealjejuPaymentCouponCountBadge(btn);
			if (btn.dataset.mySuiteCouponButtonBound === "true") return;
			btn.dataset.mySuiteCouponButtonBound = "true";
			btn.addEventListener("click", async () => {
				await useRealjejuBrokerCoupon(btn);
			});
		});
		content.querySelectorAll(".payment-history-refresh").forEach((button) => {
			if (button.dataset.paymentHistoryBound === "true") return;
			button.dataset.paymentHistoryBound = "true";
			button.addEventListener("click", () => void loadRealjejuPaymentHistory(content));
		});
		const inquiryBtn = content.querySelector("[data-my-suite-payment-inquiry]");
		if (inquiryBtn && inquiryBtn.dataset.mySuitePaymentInquiryBound !== "true") {
			inquiryBtn.dataset.mySuitePaymentInquiryBound = "true";
			inquiryBtn.addEventListener("click", () => {
				if (window.realjejuRouter && typeof window.realjejuRouter.navigate === "function") {
					window.realjejuRouter.navigate("/mypage/inquiries");
					return;
				}
				openMySuitePage("inquiries");
			});
		}
	}

