	async function resolveBrokerOfficeAddressLatLng(address)
	{
		const query = String(address || "").trim();
		if (!query || !window.kakao || !kakao.maps || !kakao.maps.services) return null;
		const geocoder = null;
		const queries = buildSubAddressSearchQueries(query);
		for (const q of queries) {
			const found = await searchAddressByGeocoder(geocoder, q);
			if (found) {
				const lat = Number(found.y);
				const lng = Number(found.x);
				if (Number.isFinite(lat) && Number.isFinite(lng)) return { lat, lng };
			}
		}
		if (kakao.maps.services.Places) {
			const places = new kakao.maps.services.Places();
			for (const q of queries) {
				const found = await searchAddressByKeyword(places, q);
				if (found) {
					const lat = Number(found.y);
					const lng = Number(found.x);
					if (Number.isFinite(lat) && Number.isFinite(lng)) return { lat, lng };
				}
			}
		}
		return null;
	}

	async function saveBrokerOfficeLocationSnapshot(client, payload)
	{
		if (!client || !payload) return;
		const officeName = String(payload.office_name || "").trim();
		const officeAddress = String(payload.office_address || "").trim();
		if (!officeName || !officeAddress) return;
		const rawLat = Number(payload.lat);
		const rawLng = Number(payload.lng);
		const resolved = Number.isFinite(rawLat) && Number.isFinite(rawLng)
			? { lat: rawLat, lng: rawLng }
			: await resolveBrokerOfficeAddressLatLng(officeAddress);
		const row = {
			user_id: payload.user_id || null,
			agency_id: payload.agency_id || null,
			broker_name: String(payload.broker_name || "").trim() || null,
			office_name: officeName,
			phone: String(payload.phone || "").trim() || null,
			office_address: officeAddress,
			...(resolved ? { lat: resolved.lat, lng: resolved.lng } : {}),
			updated_at: new Date().toISOString()
		};
		try {
			const { error } = await client
				.from("broker_office_locations")
				.upsert(row, { onConflict: "user_id" });
			if (error) throw error;
		} catch (error) {
			console.warn("중개사무소 위치 최소정보 저장 실패:", error);
		}
	}

	async function saveAgencyLatLngSnapshot(client, payload)
	{
		if (!client || !payload) return null;
		const agencyId = normalizeItemId(payload.agency_id || payload.agencyId || payload.id || "");
		if (!agencyId) return null;
		let resolved = normalizeJejuLatLngPair(payload.lat, payload.lng);
		if (!resolved) {
			const officeAddress = String(payload.office_address || payload.address || "").trim();
			if (!officeAddress) return null;
			resolved = await resolveBrokerOfficeAddressLatLng(officeAddress);
		}
		if (!resolved) return null;
		try {
			const { error } = await client
				.from("agencies")
				.update({
					lat: resolved.lat,
					lng: resolved.lng,
					updated_at: new Date().toISOString()
				})
				.eq("id", agencyId);
			if (error) throw error;
			return resolved;
		} catch (error) {
			try {
				const { error: rpcError } = await client.rpc("save_agency_lat_lng", {
					p_agency_id: agencyId,
					p_lat: resolved.lat,
					p_lng: resolved.lng
				});
				if (rpcError) throw rpcError;
				return resolved;
			} catch (rpcError) {
				console.warn("agencies.lat/lng 저장 실패: sql/agencies_lat_lng_3.809.sql 실행이 필요합니다.", {
					updateError: error,
					rpcError
				});
				return null;
			}
		}
	}

	window.saveBrokerOfficeLocationSnapshot = saveBrokerOfficeLocationSnapshot;
	window.saveAgencyLatLngSnapshot = saveAgencyLatLngSnapshot;

