	function closeDealFilterMenu()
	{
		if (!dealFilterDropdown || !dealFilterTrigger) return;
		dealFilterDropdown.classList.remove("open");
		dealFilterTrigger.setAttribute("aria-expanded", "false");
		if (typeof syncFloatingMapFilterMenus === "function") syncFloatingMapFilterMenus();
	}

	function getCompactMapFilterLabel(labels, fallback, maxVisible = 2)
	{
		const list = Array.isArray(labels) ? labels.filter(Boolean) : [];
		if (!list.length) return fallback;
		const displayList = list.map(label => label === "원룸 / 투룸" ? "원룸" : label);
		if (displayList.length <= maxVisible) return displayList.join(", ");
		return `${displayList.slice(0, maxVisible).join(", ")} +${displayList.length - maxVisible}`;
	}

	function syncDealFilterUI()
	{
		if (!dealFilterDropdown) return;
		const dealOrder = ["매매", "전세", "월세", "년세"];
		const selectedDealSet = selectedDeal instanceof Set ? selectedDeal : new Set();
		const activeLabels = dealOrder.filter(deal => selectedDealSet.has(deal) || (deal === "년세" && selectedDealSet.has("연세")));
		selectedDealSet.forEach((deal) => {
			if (!dealOrder.includes(deal) && deal !== "연세") activeLabels.push(deal);
		});
		const hasActive = activeLabels.length > 0;
		dealFilterDropdown.classList.toggle("has-active", hasActive);
		if (dealFilterLabel) dealFilterLabel.textContent = getCompactMapFilterLabel(activeLabels, "가격 유형", 2);

		(dealButtons || []).forEach(input => {
			const value = input.dataset.value || "";
			if (value === "all" || value === "전체") {
				input.checked = false;
			} else {
				input.checked = hasActive && selectedDeal.has(value);
			}
		});
	}

	if (typeof window !== "undefined") {
		window.realjejuSyncDealFilterUI = syncDealFilterUI;
	}

	function closeTypeFilterMenu()
	{
		if (!typeFilterDropdown || !typeFilterTrigger) return;
		typeFilterDropdown.classList.remove("open");
		typeFilterTrigger.setAttribute("aria-expanded", "false");
		if (typeof syncFloatingMapFilterMenus === "function") syncFloatingMapFilterMenus();
	}

	function syncTypeFilterUI()
	{
		if (!typeFilterDropdown) return;
		ensureTypeFilterHasSelection();
		const activeLabels = selectedType instanceof Set ? Array.from(selectedType) : [];
		const hasActive = activeLabels.length > 0;
		typeFilterDropdown.classList.toggle("has-active", hasActive);
		if (typeFilterLabel) typeFilterLabel.textContent = getCompactMapFilterLabel(activeLabels, "매물 유형", 2);

		(typeButtons || []).forEach(input => {
			const value = input.dataset.value || "";
			if (value === "all" || value === "전체") {
				input.checked = false;
			} else {
				input.checked = hasActive && selectedType.has(value);
			}
		});
	}

	if (typeof window !== "undefined") {
		window.realjejuSyncTypeFilterUI = syncTypeFilterUI;
	}

	function closeDealMethodFilterMenu()
	{
		if (!dealMethodFilterDropdown || !dealMethodFilterTrigger) return;
		dealMethodFilterDropdown.classList.remove("open");
		dealMethodFilterTrigger.setAttribute("aria-expanded", "false");
		if (typeof syncFloatingMapFilterMenus === "function") syncFloatingMapFilterMenus();
	}

	function closePriceFilterMenu()
	{
		if (!priceFilterDropdown || !priceFilterTrigger) return;
		priceFilterDropdown.classList.remove("open");
		priceFilterTrigger.setAttribute("aria-expanded", "false");
		if (typeof syncFloatingMapFilterMenus === "function") syncFloatingMapFilterMenus();
	}

	function closeAreaFilterMenu()
	{
		if (!areaFilterDropdown || !areaFilterTrigger) return;
		areaFilterDropdown.classList.remove("open");
		areaFilterTrigger.setAttribute("aria-expanded", "false");
		if (typeof syncFloatingMapFilterMenus === "function") syncFloatingMapFilterMenus();
	}

	function closeLandTypeFilterMenu()
	{
		if (!landTypeFilterDropdown || !landTypeFilterTrigger) return;
		landTypeFilterDropdown.classList.remove("open");
		landTypeFilterTrigger.setAttribute("aria-expanded", "false");
		if (typeof syncFloatingMapFilterMenus === "function") syncFloatingMapFilterMenus();
	}

	function closeLandUseZoneFilterMenu()
	{
		if (!landUseZoneFilterDropdown || !landUseZoneFilterTrigger) return;
		landUseZoneFilterDropdown.classList.remove("open");
		landUseZoneFilterTrigger.setAttribute("aria-expanded", "false");
		if (typeof syncFloatingMapFilterMenus === "function") syncFloatingMapFilterMenus();
	}

	function closeRoomBathFilterMenu()
	{
		if (!roomBathFilterDropdown || !roomBathFilterTrigger) return;
		roomBathFilterDropdown.classList.remove("open");
		roomBathFilterTrigger.setAttribute("aria-expanded", "false");
		if (typeof syncFloatingMapFilterMenus === "function") syncFloatingMapFilterMenus();
	}

	function closeFloorDirectionFilterMenu()
	{
		if (!floorDirectionFilterDropdown || !floorDirectionFilterTrigger) return;
		floorDirectionFilterDropdown.classList.remove("open");
		floorDirectionFilterTrigger.setAttribute("aria-expanded", "false");
		if (typeof syncFloatingMapFilterMenus === "function") syncFloatingMapFilterMenus();
	}

	function syncDealMethodFilterUI()
	{
		if (!dealMethodFilterDropdown) return;
		const method = selectedDealMethod || "all";
		const hasActive = method !== "all";
		dealMethodFilterDropdown.classList.toggle("has-active", hasActive);

		if (dealMethodFilterLabel) {
			dealMethodFilterLabel.textContent = method === "broker"
			? "공인중개사 매물"
			: method === "direct"
			? "개인직거래 매물"
			: "거래 방식";
		}

		(dealMethodInputs || []).forEach(input => {
			input.checked = (input.value || "all") === method;
		});
	}

	if (typeof window !== "undefined") {
		window.realjejuSyncDealMethodFilterUI = syncDealMethodFilterUI;
	}

	function getActivePriceFilterDeals()
	{
		const order = ["매매", "전세", "월세", "년세"];
		const active = selectedDeal instanceof Set ? order.filter(deal => selectedDeal.has(deal) || (deal === "년세" && selectedDeal.has("연세"))) : [];
		return active.length ? active : ["매매"];
	}

	function formatPriceFilterValue(value, config)
	{
		const num = Number(value);
		if (!Number.isFinite(num)) return "";
		if (config && config.unit === "eok") return formatPriceFilterManwon(num);
		return `${Math.round(num).toLocaleString("ko-KR")}만`;
	}

	function formatPriceFilterManwon(value)
	{
		const num = Math.round(Number(value));
		if (!Number.isFinite(num) || num <= 0) return "";
		if (num >= 10000) {
			const eok = Math.floor(num / 10000);
			const rest = Math.round(num % 10000);
			return rest ? `${eok.toLocaleString("ko-KR")}억 ${rest.toLocaleString("ko-KR")}만` : `${eok.toLocaleString("ko-KR")}억`;
		}
		return `${num.toLocaleString("ko-KR")}만`;
	}

	function getPriceFilterSummary(config)
	{
		if (!config || !isPriceFilterRangeActive(config)) return "전체";
		const { min, max } = getPriceFilterEffectiveRangeValues(config);
		if (min > 0 && Number.isFinite(max)) return `${formatPriceFilterValue(min, config)}~${formatPriceFilterValue(max, config)}`;
		if (min > 0) return `${formatPriceFilterValue(min, config)} 이상`;
		return `${formatPriceFilterValue(max, config)} 이하`;
	}

	function renderPriceFilterScale(config)
	{
		if (!config || !Array.isArray(config.ticks)) return "";
		const lastIndex = Math.max(1, config.ticks.length - 1);
		return config.ticks.map((tick, index) => {
			const left = (index / lastIndex) * 100;
			return `<span style="left:${Math.max(0, Math.min(100, left))}%">${tick.label}</span>`;
		}).join("");
	}

	function renderPriceFilterPanel(deal)
	{
		const config = getPriceFilterConfigForDeal(deal);
		if (!config) return "";
		const { min, max } = getPriceFilterRangeValues(config);
		const left = config.max ? (min / config.max) * 100 : 0;
		const right = config.max ? (max / config.max) * 100 : 0;
		const active = isPriceFilterRangeActive(config);
		return `
			<div class="price-filter-panel" data-price-filter-panel="${config.key}" data-price-filter-deal="${deal}">
				<div class="price-filter-summary-row">
					<strong class="price-filter-summary-label">${config.label}</strong>
					<span class="price-filter-summary">${getPriceFilterSummary(config)}</span>
					<button type="button" class="price-filter-icon-btn price-filter-edit-btn" data-price-filter-edit="${config.key}" aria-label="${config.label} 직접 입력">
						<i class="fa-solid fa-pen" aria-hidden="true"></i>
					</button>
					<button type="button" class="price-filter-icon-btn price-filter-reset-btn ${active ? "is-visible" : ""}" data-price-filter-reset="${config.key}" aria-label="${config.label} 초기화" aria-hidden="${active ? "false" : "true"}" tabindex="${active ? "0" : "-1"}">
						<i class="fa-solid fa-rotate-right" aria-hidden="true"></i>
					</button>
				</div>
				<div class="price-filter-slider-wrap">
					<div class="price-filter-slider-rail" data-price-filter-rail="${config.key}">
						<div class="price-filter-slider-fill" style="left:${Math.max(0, left)}%;width:${Math.max(0, right - left)}%"></div>
						<input type="range" class="price-filter-range price-filter-range-min" data-price-filter-key="${config.key}" data-price-filter-handle="min" min="0" max="${config.max}" step="1" value="${min}" aria-label="최소 ${config.label}" />
						<input type="range" class="price-filter-range price-filter-range-max" data-price-filter-key="${config.key}" data-price-filter-handle="max" min="0" max="${config.max}" step="1" value="${max}" aria-label="최대 ${config.label}" />
					</div>
					<div class="price-filter-scale">${renderPriceFilterScale(config)}</div>
				</div>
			</div>
		`;
	}

	function syncPriceFilterTriggerState()
	{
		if (!priceFilterDropdown) return;
		const activeDeals = getActivePriceFilterDeals();
		const activeLabels = activeDeals
			.map(deal => getPriceFilterConfigForDeal(deal))
			.filter(config => config && isPriceFilterRangeActive(config))
			.map(config => `${config.label} ${getPriceFilterSummary(config)}`);
		const hasActive = activeLabels.length > 0;
		priceFilterDropdown.classList.toggle("has-active", hasActive);
		if (priceFilterLabel) {
			priceFilterLabel.textContent = getCompactMapFilterLabel(activeLabels, "가격", 1);
		}
	}

	function syncPriceFilterUI()
	{
		if (!priceFilterDropdown) return;
		syncPriceFilterTriggerState();
		const panelHtml = getActivePriceFilterDeals().map(renderPriceFilterPanel).join("");
		if (priceFilterOptions) {
			priceFilterOptions.innerHTML = `<h3 class="price-filter-panel-title">가격</h3>${panelHtml}`;
			bindPriceFilterControls(priceFilterOptions);
		}
		if (allPriceFilterOptions) {
			allPriceFilterOptions.innerHTML = panelHtml;
			bindPriceFilterControls(allPriceFilterOptions);
		}
	}

	if (typeof window !== "undefined") {
		window.realjejuSyncPriceFilterUI = syncPriceFilterUI;
	}

	function setPriceFilterRangeFromValues(key, minValue, maxValue, options = {})
	{
		const config = Object.values(PRICE_FILTER_CONFIG).find(item => item.key === key);
		if (!config) return;
		let min = Number(minValue);
		let max = Number(maxValue);
		if (!Number.isFinite(min)) min = 0;
		if (!Number.isFinite(max)) max = config.max;
		if (min > max && !(options.keepManualMin && !options.keepManualMax)) [min, max] = [max, min];
		const rawMin = Math.max(0, min);
		const rawMax = Math.max(0, max);
		const sliderMin = Math.max(0, Math.min(config.max, rawMin));
		const sliderMax = Math.max(0, Math.min(config.max, rawMax));
		selectedPriceRanges[key] = {
			min: options.keepManualMin ? (rawMin <= 0 ? null : rawMin) : (sliderMin <= 0 ? null : sliderMin),
			max: options.keepManualMax ? rawMax : (sliderMax >= config.max ? null : sliderMax)
		};
	}

	function isPriceFilterPanelInsideAllDropdown(panel)
	{
		if (!panel || typeof panel.closest !== "function") return false;
		if (panel.closest("#allFilterDropdown")) return true;
		const floatingMenu = panel.closest(".map-filter-floating-menu.all-filter-menu, .all-filter-menu[data-map-filter-owner='allFilterDropdown']");
		return !!(floatingMenu && floatingMenu.getAttribute("data-map-filter-owner") === "allFilterDropdown");
	}

	function keepAllFilterMenuOpen()
	{
		const dropdown = document.getElementById("allFilterDropdown");
		const trigger = document.getElementById("allFilterTrigger");
		keepMapFilterMenuOpen(dropdown, trigger);
	}

	function applyPriceFilterChange(options = {})
	{
		syncPriceFilterUI();
		if (options.keepAllDropdown) keepAllFilterMenuOpen();
		else keepMapFilterMenuOpen(priceFilterDropdown, priceFilterTrigger);
		state.initialRandomListActive = false;
		resetFilterSelectionState();
		scrollListToTop();
		applyFilter();
		if (options.keepAllDropdown) keepAllFilterMenuOpen();
		else keepMapFilterMenuOpen(priceFilterDropdown, priceFilterTrigger);
		syncLeftAllButtonToMapFilters();
	}

	function syncPriceFilterPanelState(panel, config)
	{
		if (!panel || !config) return;
		const { min, max } = getPriceFilterRangeValues(config);
		const left = config.max ? (min / config.max) * 100 : 0;
		const right = config.max ? (max / config.max) * 100 : 0;
		const fill = panel.querySelector(".price-filter-slider-fill");
		if (fill) {
			fill.style.left = `${Math.max(0, left)}%`;
			fill.style.width = `${Math.max(0, right - left)}%`;
		}
		const summary = panel.querySelector(".price-filter-summary");
		if (summary) summary.textContent = getPriceFilterSummary(config);
		const active = isPriceFilterRangeActive(config);
		const resetBtn = panel.querySelector("[data-price-filter-reset]");
		if (resetBtn) {
			resetBtn.classList.toggle("is-visible", active);
			resetBtn.setAttribute("aria-hidden", active ? "false" : "true");
			resetBtn.tabIndex = active ? 0 : -1;
		}
	}

	function getPriceFilterThumbGapValue(panel, config)
	{
		if (!panel || !config) return 1;
		const rail = panel.querySelector(".price-filter-slider-rail");
		const railWidth = rail ? rail.getBoundingClientRect().width : 0;
		if (!railWidth || !Number.isFinite(config.max) || config.max <= 0) return 1;
		const rawGap = (FILTER_RANGE_THUMB_GAP_PX / railWidth) * config.max;
		return Math.max(1, rawGap);
	}

	function updatePriceFilterRangeFromEvent(event)
	{
		const input = event && event.target ? event.target : null;
		const key = input ? input.getAttribute("data-price-filter-key") : "";
		const config = Object.values(PRICE_FILTER_CONFIG).find(item => item.key === key);
		if (!input || !config) return null;
		const panel = input.closest("[data-price-filter-panel]");
		const minInput = panel ? panel.querySelector('.price-filter-range[data-price-filter-handle="min"]') : null;
		const maxInput = panel ? panel.querySelector('.price-filter-range[data-price-filter-handle="max"]') : null;
		if (!minInput || !maxInput) return null;
		const gap = getPriceFilterThumbGapValue(panel, config);
		let min = Number(minInput.value);
		let max = Number(maxInput.value);
		if (!Number.isFinite(min)) min = 0;
		if (!Number.isFinite(max)) max = config.max;
		if (input === minInput) {
			min = Math.min(min, Math.max(0, max - gap));
		} else {
			max = Math.max(max, Math.min(config.max, min + gap));
		}
		minInput.value = String(min);
		maxInput.value = String(max);
		setPriceFilterRangeFromValues(key, min, max);
		return { panel, config };
	}

	function handlePriceFilterRangeInput(event)
	{
		const result = updatePriceFilterRangeFromEvent(event);
		if (!result) return;
		syncPriceFilterPanelState(result.panel, result.config);
	}

	function handlePriceFilterRangeCommit(event)
	{
		const result = updatePriceFilterRangeFromEvent(event);
		if (!result) return;
		applyPriceFilterChange({ keepAllDropdown: isPriceFilterPanelInsideAllDropdown(result.panel) });
	}

	function getPriceFilterValueFromTrackPointer(event, rail, config)
	{
		if (!event || !rail || !config) return 0;
		const rect = rail.getBoundingClientRect();
		const width = Math.max(1, rect.width);
		const ratio = Math.max(0, Math.min(1, (event.clientX - rect.left) / width));
		return Math.max(0, Math.min(config.max, ratio * config.max));
	}

	function isPriceFilterPointerNearHandle(event, rail, config, minInput, maxInput)
	{
		if (!event || !rail || !config || !minInput || !maxInput) return false;
		const rect = rail.getBoundingClientRect();
		const width = Math.max(1, rect.width);
		const maxValue = Number.isFinite(config.max) && config.max > 0 ? config.max : 1;
		const pointerX = event.clientX;
		const handleRadius = Math.max(18, FILTER_RANGE_THUMB_GAP_PX * 0.5);
		return [minInput, maxInput].some(input => {
			const value = Number(input.value);
			const safeValue = Number.isFinite(value) ? Math.max(0, Math.min(maxValue, value)) : 0;
			const handleX = rect.left + (safeValue / maxValue) * width;
			return Math.abs(pointerX - handleX) <= handleRadius;
		});
	}

	let activePriceFilterTrackContext = null;

	function setFilterTrackCursorForHandle(event, rail, input, maxValue)
	{
		if (!document.body || !event || !rail || !input) return;
		const rect = rail.getBoundingClientRect();
		const width = Math.max(1, rect.width);
		const safeMax = Number.isFinite(maxValue) && maxValue > 0 ? maxValue : 1;
		const value = Number(input.value);
		const safeValue = Number.isFinite(value) ? Math.max(0, Math.min(safeMax, value)) : 0;
		const handleX = rect.left + (safeValue / safeMax) * width;
		const handleY = rect.top + rect.height / 2;
		const withinX = Math.abs(event.clientX - handleX) <= 13;
		const withinY = Math.abs(event.clientY - handleY) <= 34;
		document.body.classList.toggle("filter-range-dragging", withinX && withinY);
		document.body.classList.toggle("filter-track-default", !withinX || !withinY);
	}

	function clearFilterTrackCursor()
	{
		if (!document.body) return;
		document.body.classList.remove("filter-range-dragging");
		document.body.classList.remove("filter-track-default");
	}

	function movePriceFilterHandleToPointer(event)
	{
		const context = activePriceFilterTrackContext;
		if (!context || !context.target || !context.rail || !context.config) return null;
		const value = getPriceFilterValueFromTrackPointer(event, context.rail, context.config);
		context.target.value = String(value);
		const result = updatePriceFilterRangeFromEvent({ target: context.target });
		if (!result) return null;
		syncPriceFilterPanelState(result.panel, result.config);
		return result;
	}

	function getNearestPriceFilterHandle(value, config, minInput, maxInput)
	{
		if (!config || !minInput || !maxInput) return null;
		const min = Number(minInput.value);
		const max = Number(maxInput.value);
		const safeMin = Number.isFinite(min) ? min : 0;
		const safeMax = Number.isFinite(max) ? max : config.max;
		if (value <= safeMin) return minInput;
		if (value >= safeMax) return maxInput;
		return Math.abs(value - safeMin) <= Math.abs(safeMax - value) ? minInput : maxInput;
	}

	function handlePriceFilterTrackPointerDown(event)
	{
		const rail = event.target && event.target.closest ? event.target.closest(".price-filter-slider-rail") : null;
		if (!rail) return;
		if (typeof event.button === "number" && event.button !== 0) return;
		const key = rail.getAttribute("data-price-filter-rail");
		const config = getPriceFilterConfigByKey(key);
		const panel = rail.closest("[data-price-filter-panel]");
		const minInput = panel ? panel.querySelector('.price-filter-range[data-price-filter-handle="min"]') : null;
		const maxInput = panel ? panel.querySelector('.price-filter-range[data-price-filter-handle="max"]') : null;
		if (!config || !panel || !minInput || !maxInput) return;
		const rangeTarget = event.target && event.target.closest ? event.target.closest(".price-filter-range") : null;
		if (rangeTarget && isPriceFilterPointerNearHandle(event, rail, config, minInput, maxInput)) return;
		event.preventDefault();
		event.stopPropagation();
		const value = getPriceFilterValueFromTrackPointer(event, rail, config);
			const target = getNearestPriceFilterHandle(value, config, minInput, maxInput);
			if (!target) return;
			activePriceFilterTrackContext = { rail, panel, config, target };
			setFilterTrackCursorForHandle(event, rail, target, config.max);
			try {
			rail.setPointerCapture(event.pointerId);
		} catch (_) {
			// Pointer capture is best-effort; click still moves the closest handle immediately.
		}
		movePriceFilterHandleToPointer(event);
	}

	function handlePriceFilterTrackPointerMove(event)
	{
		if (!activePriceFilterTrackContext) return;
		event.preventDefault();
		event.stopPropagation();
		movePriceFilterHandleToPointer(event);
		setFilterTrackCursorForHandle(event, activePriceFilterTrackContext.rail, activePriceFilterTrackContext.target, activePriceFilterTrackContext.config.max);
	}

	function handlePriceFilterTrackPointerEnd(event)
	{
		if (!activePriceFilterTrackContext) return;
			const rail = activePriceFilterTrackContext.rail;
			const keepAllDropdown = isPriceFilterPanelInsideAllDropdown(activePriceFilterTrackContext.panel);
			movePriceFilterHandleToPointer(event);
			activePriceFilterTrackContext = null;
			clearFilterTrackCursor();
			try {
			rail && rail.releasePointerCapture(event.pointerId);
		} catch (_) {
			// Ignore release failures from browsers that did not capture.
		}
		applyPriceFilterChange({ keepAllDropdown });
	}

	function bindPriceFilterControls(container = priceFilterOptions)
	{
		if (!container) return;
		if (container.dataset.priceFilterTrackBound !== "1") {
			container.dataset.priceFilterTrackBound = "1";
			container.addEventListener("pointerdown", handlePriceFilterTrackPointerDown);
			container.addEventListener("pointermove", handlePriceFilterTrackPointerMove);
			container.addEventListener("pointerup", handlePriceFilterTrackPointerEnd);
			container.addEventListener("pointercancel", handlePriceFilterTrackPointerEnd);
		}
		container.querySelectorAll(".price-filter-range").forEach(input => {
			if (input.dataset.priceFilterBound === "1") return;
			input.dataset.priceFilterBound = "1";
			input.addEventListener("input", handlePriceFilterRangeInput);
			input.addEventListener("change", handlePriceFilterRangeCommit);
			bindFilterRangeDragging(input);
		});
		container.querySelectorAll("[data-price-filter-reset]").forEach(btn => {
			if (btn.dataset.priceFilterBound === "1") return;
			btn.dataset.priceFilterBound = "1";
			btn.addEventListener("click", (e) => {
				e.preventDefault();
				e.stopPropagation();
				const key = btn.getAttribute("data-price-filter-reset");
				if (selectedPriceRanges && typeof selectedPriceRanges === "object") delete selectedPriceRanges[key];
				applyPriceFilterChange({ keepAllDropdown: isPriceFilterPanelInsideAllDropdown(btn) });
			});
		});
		container.querySelectorAll("[data-price-filter-edit]").forEach(btn => {
			if (btn.dataset.priceFilterBound === "1") return;
			btn.dataset.priceFilterBound = "1";
			btn.addEventListener("click", (e) => {
				e.preventDefault();
				e.stopPropagation();
				openPriceFilterManualModal(btn.getAttribute("data-price-filter-edit"), {
					keepAllDropdown: isPriceFilterPanelInsideAllDropdown(btn)
				});
			});
		});
	}

	function getPriceFilterConfigByKey(key)
	{
		return Object.values(PRICE_FILTER_CONFIG).find(config => config && config.key === key) || null;
	}

	function parsePriceManualInputValue(input)
	{
		const raw = String(input && input.value || "").replace(/[^0-9]/g, "");
		if (!raw) return null;
		const value = Number(raw);
		return Number.isFinite(value) ? value : null;
	}

	function setPriceManualInputValue(input, value)
	{
		if (!input) return;
		const num = Number(value);
		input.value = Number.isFinite(num) && num > 0 ? Math.round(num).toLocaleString("ko-KR") : "";
	}

	function formatPriceManualHint(value, config)
	{
		const num = Number(value);
		if (!Number.isFinite(num) || num <= 0) return "";
		return config && config.unit === "eok" ? formatPriceFilterManwon(num) : `${Math.round(num).toLocaleString("ko-KR")}만`;
	}

	function syncPriceManualHints()
	{
		const config = getPriceFilterConfigByKey(activePriceManualKey);
		const min = parsePriceManualInputValue(priceFilterManualMinInput);
		const max = parsePriceManualInputValue(priceFilterManualMaxInput);
		if (priceFilterManualMinHint) priceFilterManualMinHint.textContent = formatPriceManualHint(min, config);
		if (priceFilterManualMaxHint) priceFilterManualMaxHint.textContent = formatPriceManualHint(max, config);
	}

	function syncPriceManualClearButtons()
	{
		document.querySelectorAll("[data-price-filter-clear]").forEach(btn => {
			const target = btn.getAttribute("data-price-filter-clear");
			const input = target === "min" ? priceFilterManualMinInput : priceFilterManualMaxInput;
			const visible = !!(input && String(input.value || "").trim());
			btn.classList.toggle("is-visible", visible);
			btn.setAttribute("aria-hidden", visible ? "false" : "true");
			btn.tabIndex = visible ? 0 : -1;
		});
	}

	function validatePriceManualRange()
	{
		const min = parsePriceManualInputValue(priceFilterManualMinInput);
		const max = parsePriceManualInputValue(priceFilterManualMaxInput);
		const invalid = Number.isFinite(min) && Number.isFinite(max) && min > max;
		const minField = priceFilterManualMinInput ? priceFilterManualMinInput.closest(".price-filter-manual-field") : null;
		if (minField) minField.classList.toggle("is-invalid", invalid);
		if (priceFilterManualHints) priceFilterManualHints.classList.toggle("is-error", invalid);
		if (invalid) {
			if (priceFilterManualMinHint) priceFilterManualMinHint.textContent = "최대 가격보다 작아야 합니다.";
			if (priceFilterManualMaxHint) priceFilterManualMaxHint.textContent = "";
		}
		if (priceFilterManualApplyBtn) priceFilterManualApplyBtn.disabled = invalid;
		return !invalid;
	}

	function syncPriceManualState()
	{
		syncPriceManualHints();
		syncPriceManualClearButtons();
		validatePriceManualRange();
	}

	function openPriceFilterManualModal(key, options = {})
	{
		const config = getPriceFilterConfigByKey(key);
		if (!priceFilterManualModal || !config) return;
		activePriceManualKey = config.key;
		activePriceManualKeepAllDropdown = !!options.keepAllDropdown;
		const sliderRange = getPriceFilterRangeValues(config);
		const savedRange = getSelectedPriceRangeForKey(config.key);
		if (priceFilterManualTitle) priceFilterManualTitle.textContent = config.label;
		setPriceManualInputValue(priceFilterManualMinInput, Number.isFinite(savedRange.min) ? savedRange.min : (sliderRange.min > 0 ? sliderRange.min : ""));
		setPriceManualInputValue(priceFilterManualMaxInput, Number.isFinite(savedRange.max) ? savedRange.max : "");
		syncPriceManualState();
		priceFilterManualModal.classList.add("open");
		priceFilterManualModal.setAttribute("aria-hidden", "false");
		if (activePriceManualKeepAllDropdown) keepAllFilterMenuOpen();
		else keepMapFilterMenuOpen(priceFilterDropdown, priceFilterTrigger);
		setTimeout(() => priceFilterManualMinInput?.focus(), 0);
	}

	function closePriceFilterManualModal()
	{
		if (!priceFilterManualModal) return;
		if (priceFilterManualModal.contains(document.activeElement) && document.activeElement && typeof document.activeElement.blur === "function") {
			document.activeElement.blur();
		}
		priceFilterManualModal.classList.remove("open");
		priceFilterManualModal.setAttribute("aria-hidden", "true");
		activePriceManualKey = "";
		activePriceManualKeepAllDropdown = false;
	}

	function normalizePriceManualInput(input)
	{
		const value = parsePriceManualInputValue(input);
		setPriceManualInputValue(input, value);
		syncPriceManualState();
	}

	function applyPriceFilterManualInput()
	{
		const config = getPriceFilterConfigByKey(activePriceManualKey);
		if (!config) return;
		if (!validatePriceManualRange()) return;
		let min = parsePriceManualInputValue(priceFilterManualMinInput);
		let max = parsePriceManualInputValue(priceFilterManualMaxInput);
		const hasManualMin = Number.isFinite(min);
		const hasManualMax = Number.isFinite(max);
		min = hasManualMin ? Math.max(0, min) : 0;
		max = hasManualMax ? Math.max(0, max) : config.max;
		setPriceFilterRangeFromValues(config.key, min, max, {
			keepManualMin: hasManualMin,
			keepManualMax: hasManualMax
		});
		const keepAllDropdown = activePriceManualKeepAllDropdown;
		closePriceFilterManualModal();
		applyPriceFilterChange({ keepAllDropdown });
	}

	function getAreaFilterUnitLabel()
	{
		return selectedAreaUnit === "py" ? "평" : "㎡";
	}

	function getAreaFilterNextUnitLabel()
	{
		return selectedAreaUnit === "py" ? "㎡" : "평";
	}

	function getAreaFilterRangeUnitValues()
	{
		const unitMax = getAreaFilterUnitMax();
		const minValue = Number.isFinite(selectedAreaMinM2) ? areaFilterFromM2(selectedAreaMinM2) : 0;
		const maxValue = selectedAreaMaxTouched && Number.isFinite(selectedAreaMaxM2) && !isAreaFilterMaxUnbounded() ? areaFilterFromM2(selectedAreaMaxM2) : unitMax;
		return {
			min: Math.max(0, Math.min(unitMax, minValue)),
			max: Math.max(0, Math.min(unitMax, maxValue)),
			unitMax
		};
	}

	function syncAreaFilterScale()
	{
		if (!areaFilterScale) return;
		areaFilterScale.innerHTML = getAreaFilterScaleHtml();
	}

	function getAreaFilterScaleHtml()
	{
		const unit = getAreaFilterUnitLabel();
		const values = selectedAreaLandOnly
			? (selectedAreaUnit === "py" ? [100, 200, 300, 400] : [330, 660, 990, 1320])
			: (selectedAreaUnit === "py" ? [10, 20, 30, 40] : [33, 66, 99, 132]);
		const labels = [
			"최소",
			...values.map(value => `${value}${unit}`),
			"최대"
		];
		const lastIndex = Math.max(1, labels.length - 1);
		return labels
			.map((label, index) => `<span style="left:${(index / lastIndex) * 100}%;">${label}</span>`)
			.join("");
	}

	function getAllAreaFilterElements()
	{
		const root = allAreaFilterOptions;
		if (!root) return {};
		return {
			root,
			summary: root.querySelector("[data-all-area-filter-summary]"),
			unitText: root.querySelector("[data-all-area-filter-unit-text]"),
			resetBtn: root.querySelector("[data-all-area-filter-reset]"),
			rail: root.querySelector("[data-all-area-filter-rail]"),
			fill: root.querySelector("[data-all-area-filter-fill]"),
			minRange: root.querySelector('[data-all-area-filter-range="min"]'),
			maxRange: root.querySelector('[data-all-area-filter-range="max"]'),
			scale: root.querySelector("[data-all-area-filter-scale]"),
			exclusiveChk: root.querySelector('[data-all-area-filter-mode="exclusive"]'),
			landChk: root.querySelector('[data-all-area-filter-mode="land"]')
		};
	}

	function syncAreaFilterSliderElements(minRange, maxRange, fill)
	{
		if (!minRange || !maxRange) return;
		const { min, max, unitMax } = getAreaFilterRangeUnitValues();
		[minRange, maxRange].forEach(input => {
			input.min = "0";
			input.max = String(unitMax);
			input.step = "0.01";
		});
		minRange.value = String(min);
		maxRange.value = String(max);
		if (fill) {
			const left = unitMax > 0 ? (min / unitMax) * 100 : 0;
			const right = unitMax > 0 ? (max / unitMax) * 100 : 100;
			fill.style.left = `${left}%`;
			fill.style.width = `${Math.max(0, right - left)}%`;
		}
	}

	function syncAreaFilterSlider()
	{
		syncAreaFilterSliderElements(areaFilterMinRange, areaFilterMaxRange, areaFilterSliderFill);
	}

	function syncAllAreaFilterUI()
	{
		const els = getAllAreaFilterElements();
		if (!els.root) return;
		const hasActive = Number.isFinite(selectedAreaMinM2) || (selectedAreaMaxTouched && Number.isFinite(selectedAreaMaxM2) && !isAreaFilterMaxUnbounded());
		if (els.summary) els.summary.textContent = hasActive ? getAreaFilterRangeLabel("전체") : "전체";
		if (els.unitText) els.unitText.textContent = getAreaFilterNextUnitLabel();
		if (els.resetBtn) {
			els.resetBtn.hidden = !hasActive;
			els.resetBtn.classList.toggle("is-visible", hasActive);
		}
		if (els.scale) els.scale.innerHTML = getAreaFilterScaleHtml();
		if (els.exclusiveChk) els.exclusiveChk.checked = !!selectedAreaExclusiveOnly;
		if (els.landChk) els.landChk.checked = !!selectedAreaLandOnly;
		syncAreaFilterSliderElements(els.minRange, els.maxRange, els.fill);
	}

	function syncAreaFilterManualUnitLabels()
	{
		const unit = getAreaFilterUnitLabel();
		document.querySelectorAll("[data-area-filter-manual-unit]").forEach(el => {
			el.textContent = unit;
		});
		if (areaFilterManualUnitToggleText) areaFilterManualUnitToggleText.textContent = getAreaFilterNextUnitLabel();
	}

	function syncAreaFilterManualClearButtons()
	{
		document.querySelectorAll("[data-area-filter-clear]").forEach(btn => {
			const target = btn.getAttribute("data-area-filter-clear");
			const input = target === "min" ? areaFilterManualMinInput : areaFilterManualMaxInput;
			const visible = !!(input && String(input.value || "").trim());
			btn.classList.toggle("is-visible", visible);
			btn.setAttribute("aria-hidden", visible ? "false" : "true");
			btn.tabIndex = visible ? 0 : -1;
		});
	}

	function parseAreaFilterManualInputValue(input)
	{
		if (!input || input.value === "") return null;
		const value = Number(input.value);
		return Number.isFinite(value) ? value : null;
	}

	function validateAreaFilterManualRange()
	{
		const min = parseAreaFilterManualInputValue(areaFilterManualMinInput);
		const max = parseAreaFilterManualInputValue(areaFilterManualMaxInput);
		const invalid = Number.isFinite(min) && Number.isFinite(max) && min > max;
		const minField = areaFilterManualMinInput ? areaFilterManualMinInput.closest(".area-filter-manual-field") : null;
		if (minField) minField.classList.toggle("is-invalid", invalid);
		if (areaFilterManualMinError) areaFilterManualMinError.textContent = invalid ? "최대 면적보다 작아야 합니다." : "";
		if (areaFilterManualMaxError) areaFilterManualMaxError.textContent = "";
		if (areaFilterManualErrors) areaFilterManualErrors.classList.toggle("is-error", invalid);
		if (areaFilterManualApplyBtn) areaFilterManualApplyBtn.disabled = invalid;
		return !invalid;
	}

	function syncAreaFilterManualState()
	{
		syncAreaFilterManualClearButtons();
		validateAreaFilterManualRange();
	}

	function syncAreaFilterManualInputsFromState()
	{
		if (areaFilterManualMinInput) {
			const minValue = Number.isFinite(selectedAreaMinM2) ? areaFilterFromM2(selectedAreaMinM2) : null;
			areaFilterManualMinInput.value = Number.isFinite(minValue) ? String(Math.round(minValue)) : "";
		}
		if (areaFilterManualMaxInput) {
			const maxValue = selectedAreaMaxTouched && Number.isFinite(selectedAreaMaxM2) && !isAreaFilterMaxUnbounded() ? areaFilterFromM2(selectedAreaMaxM2) : null;
			areaFilterManualMaxInput.value = Number.isFinite(maxValue) ? String(Math.round(maxValue)) : "";
		}
		syncAreaFilterManualUnitLabels();
		syncAreaFilterManualState();
	}

	function syncAreaFilterUI(options = {})
	{
		if (!areaFilterDropdown) return;
		const shouldUpdateTrigger = options.updateTrigger !== false;
		const hasActive = Number.isFinite(selectedAreaMinM2) || (selectedAreaMaxTouched && Number.isFinite(selectedAreaMaxM2) && !isAreaFilterMaxUnbounded());
		const label = getAreaFilterRangeLabel("면적");
		if (shouldUpdateTrigger) {
			areaFilterDropdown.classList.toggle("has-active", hasActive);
			if (areaFilterLabel) areaFilterLabel.textContent = label;
		}
		if (areaFilterSummaryText) areaFilterSummaryText.textContent = hasActive ? getAreaFilterRangeLabel("전체") : "전체";
		if (areaFilterUnitToggleText) areaFilterUnitToggleText.textContent = getAreaFilterNextUnitLabel();
		if (areaFilterExclusiveChk) areaFilterExclusiveChk.checked = !!selectedAreaExclusiveOnly;
		if (areaFilterLandChk) areaFilterLandChk.checked = !!selectedAreaLandOnly;
		if (areaFilterResetBtn) {
			areaFilterResetBtn.hidden = !hasActive;
			areaFilterResetBtn.classList.toggle("is-visible", hasActive);
		}
		syncAreaFilterScale();
		syncAreaFilterSlider();
		syncAllAreaFilterUI();
		syncAreaFilterManualUnitLabels();
		if (typeof scheduleMapFilterScrollSync === "function") scheduleMapFilterScrollSync();
		if (areaFilterDropdown.classList.contains("open")) syncOpenMapFilterMenuPosition(areaFilterDropdown);
	}

	window.realjejuSyncAreaFilterUI = syncAreaFilterUI;

	function applyAreaFilterChange(options = {})
	{
		syncAreaFilterUI();
		if (options.keepAllDropdown) keepAllFilterMenuOpen();
		else keepMapFilterMenuOpen(areaFilterDropdown, areaFilterTrigger);
		state.initialRandomListActive = false;
		resetFilterSelectionState();
		scrollListToTop();
		applyFilter();
		if (options.keepAllDropdown) keepAllFilterMenuOpen();
		else keepMapFilterMenuOpen(areaFilterDropdown, areaFilterTrigger);
		syncLeftAllButtonToMapFilters();
	}

	function setAreaFilterRangeFromUnitValues(minUnitValue, maxUnitValue, options = {})
	{
		const unitMax = getAreaFilterUnitMax();
		const shouldUseMax = !!options.maxTouched;
		let min = Number(minUnitValue);
		let max = Number(maxUnitValue);
		if (!Number.isFinite(min)) min = 0;
		if (!Number.isFinite(max)) max = unitMax;
		min = Math.max(0, Math.min(unitMax, min));
		max = Math.max(0, Math.min(unitMax, max));
		if (min > max) [min, max] = [max, min];
		selectedAreaMinM2 = min <= 0 ? null : areaFilterToM2(min);
		selectedAreaMaxTouched = shouldUseMax && max < unitMax - 0.01;
		selectedAreaMaxM2 = selectedAreaMaxTouched ? areaFilterToM2(max) : AREA_FILTER_UNBOUNDED_MAX_M2;
		saveCurrentAreaFilterRange();
	}

	function getAreaFilterThumbGapUnitValue(unitMax, rail = areaFilterSliderRail)
	{
		const maxValue = Number(unitMax);
		const railWidth = rail
			? rail.getBoundingClientRect().width
			: 0;
		if (!Number.isFinite(maxValue) || maxValue <= 0 || !railWidth) return 1;
		return Math.max(0.01, (FILTER_RANGE_THUMB_GAP_PX / railWidth) * maxValue);
	}

	function updateAreaFilterRangeFromInputs(minRange, maxRange, event, rail = areaFilterSliderRail)
	{
		if (!minRange || !maxRange) return false;
		const unitMax = getAreaFilterUnitMax();
		const gap = getAreaFilterThumbGapUnitValue(unitMax, rail);
		const wasMaxTouched = selectedAreaMaxTouched;
		const maxTouched = !!(event && event.target === maxRange);
		let min = Number(minRange.value);
		let max = Number(maxRange.value);
		if (event && event.target === minRange) {
			min = Math.min(min, Math.max(0, max - gap));
			minRange.value = String(min);
		} else if (event && event.target === maxRange) {
			max = Math.max(max, Math.min(unitMax, min + gap));
			maxRange.value = String(max);
		} else if (min + gap > max) {
			max = Math.min(unitMax, min + gap);
			if (max >= unitMax) min = Math.max(0, max - gap);
			minRange.value = String(min);
			maxRange.value = String(max);
		}
		setAreaFilterRangeFromUnitValues(min, max, { maxTouched: maxTouched || wasMaxTouched });
		return true;
	}

	function updateAreaFilterRangeFromEvent(event)
	{
		return updateAreaFilterRangeFromInputs(areaFilterMinRange, areaFilterMaxRange, event, areaFilterSliderRail);
	}

	function handleAreaFilterRangeInput(event)
	{
		if (!updateAreaFilterRangeFromEvent(event)) return;
		syncAreaFilterUI({ updateTrigger: false });
		keepMapFilterMenuOpen(areaFilterDropdown, areaFilterTrigger);
	}

	function handleAreaFilterRangeCommit(event)
	{
		if (!updateAreaFilterRangeFromEvent(event)) return;
		applyAreaFilterChange();
	}

	function getAreaFilterValueFromTrackPointer(event)
	{
		if (!event || !areaFilterSliderRail) return 0;
		const unitMax = getAreaFilterUnitMax();
		const rect = areaFilterSliderRail.getBoundingClientRect();
		const width = Math.max(1, rect.width);
		const ratio = Math.max(0, Math.min(1, (event.clientX - rect.left) / width));
		return Math.max(0, Math.min(unitMax, ratio * unitMax));
	}

	function isAreaFilterPointerNearHandle(event)
	{
		if (!event || !areaFilterSliderRail || !areaFilterMinRange || !areaFilterMaxRange) return false;
		const unitMax = getAreaFilterUnitMax();
		const rect = areaFilterSliderRail.getBoundingClientRect();
		const width = Math.max(1, rect.width);
		const maxValue = Number.isFinite(unitMax) && unitMax > 0 ? unitMax : 1;
		const pointerX = event.clientX;
		const handleRadius = Math.max(18, FILTER_RANGE_THUMB_GAP_PX * 0.5);
		return [areaFilterMinRange, areaFilterMaxRange].some(input => {
			const value = Number(input.value);
			const safeValue = Number.isFinite(value) ? Math.max(0, Math.min(maxValue, value)) : 0;
			const handleX = rect.left + (safeValue / maxValue) * width;
			return Math.abs(pointerX - handleX) <= handleRadius;
		});
	}

	function getNearestAreaFilterHandle(value)
	{
		const unitMax = getAreaFilterUnitMax();
		const min = areaFilterMinRange ? Number(areaFilterMinRange.value) : 0;
		const max = areaFilterMaxRange ? Number(areaFilterMaxRange.value) : unitMax;
		const safeMin = Number.isFinite(min) ? min : 0;
		const safeMax = Number.isFinite(max) ? max : unitMax;
		if (value <= safeMin) return areaFilterMinRange;
		if (value >= safeMax) return areaFilterMaxRange;
		return Math.abs(value - safeMin) <= Math.abs(safeMax - value) ? areaFilterMinRange : areaFilterMaxRange;
	}

	let activeAreaFilterTrackHandle = null;

	function moveAreaFilterHandleToPointer(event)
	{
		if (!activeAreaFilterTrackHandle) return false;
		const value = getAreaFilterValueFromTrackPointer(event);
		activeAreaFilterTrackHandle.value = String(value);
		handleAreaFilterRangeInput({ target: activeAreaFilterTrackHandle });
		return true;
	}

	function handleAreaFilterTrackPointerDown(event)
	{
		if (!areaFilterSliderRail || !areaFilterMinRange || !areaFilterMaxRange) return;
		if (typeof event.button === "number" && event.button !== 0) return;
		const rangeTarget = event.target && event.target.closest ? event.target.closest(".area-filter-range") : null;
		if (rangeTarget && isAreaFilterPointerNearHandle(event)) return;
		event.preventDefault();
		event.stopPropagation();
		const value = getAreaFilterValueFromTrackPointer(event);
			const target = getNearestAreaFilterHandle(value);
			if (!target) return;
			activeAreaFilterTrackHandle = target;
			setFilterTrackCursorForHandle(event, areaFilterSliderRail, target, getAreaFilterUnitMax());
			try {
			areaFilterSliderRail.setPointerCapture(event.pointerId);
		} catch (_) {
			// Pointer capture is best-effort; the initial click still moves the closest handle.
		}
		moveAreaFilterHandleToPointer(event);
	}

	function handleAreaFilterTrackPointerMove(event)
	{
		if (!activeAreaFilterTrackHandle) return;
		event.preventDefault();
		event.stopPropagation();
		moveAreaFilterHandleToPointer(event);
		setFilterTrackCursorForHandle(event, areaFilterSliderRail, activeAreaFilterTrackHandle, getAreaFilterUnitMax());
	}

	function handleAreaFilterTrackPointerEnd(event)
	{
		if (!activeAreaFilterTrackHandle) return;
			const target = activeAreaFilterTrackHandle;
			moveAreaFilterHandleToPointer(event);
			activeAreaFilterTrackHandle = null;
			clearFilterTrackCursor();
			try {
			areaFilterSliderRail && areaFilterSliderRail.releasePointerCapture(event.pointerId);
		} catch (_) {
			// Ignore release failures from browsers that did not capture.
		}
		handleAreaFilterRangeCommit({ target });
	}

	function updateAllAreaFilterRangeFromEvent(event)
	{
		const els = getAllAreaFilterElements();
		return updateAreaFilterRangeFromInputs(els.minRange, els.maxRange, event, els.rail);
	}

	function handleAllAreaFilterRangeInput(event)
	{
		if (!updateAllAreaFilterRangeFromEvent(event)) return;
		syncAreaFilterUI({ updateTrigger: false });
		keepAllFilterMenuOpen();
	}

	function handleAllAreaFilterRangeCommit(event)
	{
		if (!updateAllAreaFilterRangeFromEvent(event)) return;
		applyAreaFilterChange({ keepAllDropdown: true });
	}

	function getAllAreaFilterValueFromTrackPointer(event, rail)
	{
		if (!event || !rail) return 0;
		const unitMax = getAreaFilterUnitMax();
		const rect = rail.getBoundingClientRect();
		const width = Math.max(1, rect.width);
		const ratio = Math.max(0, Math.min(1, (event.clientX - rect.left) / width));
		return Math.max(0, Math.min(unitMax, ratio * unitMax));
	}

	function isAllAreaFilterPointerNearHandle(event, rail, minRange, maxRange)
	{
		if (!event || !rail || !minRange || !maxRange) return false;
		const unitMax = getAreaFilterUnitMax();
		const rect = rail.getBoundingClientRect();
		const width = Math.max(1, rect.width);
		const maxValue = Number.isFinite(unitMax) && unitMax > 0 ? unitMax : 1;
		const pointerX = event.clientX;
		const handleRadius = Math.max(18, FILTER_RANGE_THUMB_GAP_PX * 0.5);
		return [minRange, maxRange].some(input => {
			const value = Number(input.value);
			const safeValue = Number.isFinite(value) ? Math.max(0, Math.min(maxValue, value)) : 0;
			const handleX = rect.left + (safeValue / maxValue) * width;
			return Math.abs(pointerX - handleX) <= handleRadius;
		});
	}

	function getNearestAllAreaFilterHandle(value, minRange, maxRange)
	{
		const unitMax = getAreaFilterUnitMax();
		const min = minRange ? Number(minRange.value) : 0;
		const max = maxRange ? Number(maxRange.value) : unitMax;
		const safeMin = Number.isFinite(min) ? min : 0;
		const safeMax = Number.isFinite(max) ? max : unitMax;
		if (value <= safeMin) return minRange;
		if (value >= safeMax) return maxRange;
		return Math.abs(value - safeMin) <= Math.abs(safeMax - value) ? minRange : maxRange;
	}

	let activeAllAreaFilterTrackContext = null;

	function moveAllAreaFilterHandleToPointer(event)
	{
		const context = activeAllAreaFilterTrackContext;
		if (!context || !context.target || !context.rail) return false;
		const value = getAllAreaFilterValueFromTrackPointer(event, context.rail);
		context.target.value = String(value);
		handleAllAreaFilterRangeInput({ target: context.target });
		return true;
	}

	function handleAllAreaFilterTrackPointerDown(event)
	{
		const rail = event.target && event.target.closest ? event.target.closest("[data-all-area-filter-rail]") : null;
		if (!rail) return;
		if (typeof event.button === "number" && event.button !== 0) return;
		const els = getAllAreaFilterElements();
		if (!els.minRange || !els.maxRange) return;
		const rangeTarget = event.target && event.target.closest ? event.target.closest(".area-filter-range") : null;
		if (rangeTarget && isAllAreaFilterPointerNearHandle(event, rail, els.minRange, els.maxRange)) return;
		event.preventDefault();
		event.stopPropagation();
		const value = getAllAreaFilterValueFromTrackPointer(event, rail);
		const target = getNearestAllAreaFilterHandle(value, els.minRange, els.maxRange);
		if (!target) return;
		activeAllAreaFilterTrackContext = { rail, target };
		setFilterTrackCursorForHandle(event, rail, target, getAreaFilterUnitMax());
		try {
			rail.setPointerCapture(event.pointerId);
		} catch (_) {
			// Pointer capture is best-effort; the initial click still moves the closest handle.
		}
		moveAllAreaFilterHandleToPointer(event);
	}

	function handleAllAreaFilterTrackPointerMove(event)
	{
		if (!activeAllAreaFilterTrackContext) return;
		event.preventDefault();
		event.stopPropagation();
		moveAllAreaFilterHandleToPointer(event);
		setFilterTrackCursorForHandle(event, activeAllAreaFilterTrackContext.rail, activeAllAreaFilterTrackContext.target, getAreaFilterUnitMax());
	}

	function handleAllAreaFilterTrackPointerEnd(event)
	{
		if (!activeAllAreaFilterTrackContext) return;
		const { rail, target } = activeAllAreaFilterTrackContext;
		moveAllAreaFilterHandleToPointer(event);
		activeAllAreaFilterTrackContext = null;
		clearFilterTrackCursor();
		try {
			rail && rail.releasePointerCapture(event.pointerId);
		} catch (_) {
			// Ignore release failures from browsers that did not capture.
		}
		handleAllAreaFilterRangeCommit({ target });
	}

	function setFilterRangeDragging(input, active)
	{
		if (!input || !document.body) return;
		input.classList.toggle("is-dragging", active);
		document.body.classList.toggle("filter-range-dragging", active);
	}

	function clearFilterRangeDragging()
	{
		if (document.body) {
			document.body.classList.remove("filter-range-dragging");
			document.body.classList.remove("filter-track-default");
		}
		document
			.querySelectorAll(".area-filter-range.is-dragging, .approval-year-filter-range.is-dragging, .price-filter-range.is-dragging")
			.forEach(input => input.classList.remove("is-dragging"));
	}

	function bindFilterRangeDragging(input)
	{
		if (!input) return;
		input.addEventListener("pointerdown", () => setFilterRangeDragging(input, true));
		input.addEventListener("mousedown", () => setFilterRangeDragging(input, true));
		input.addEventListener("touchstart", () => setFilterRangeDragging(input, true), { passive: true });
	}

	function toggleAreaFilterUnit(options = {})
	{
		const oldUnit = selectedAreaUnit;
		const modalOpen = !!(areaFilterManualModal && areaFilterManualModal.classList.contains("open"));
		const manualMinM2 = modalOpen && areaFilterManualMinInput && areaFilterManualMinInput.value !== ""
			? areaFilterToM2(areaFilterManualMinInput.value, oldUnit)
			: null;
		const manualMaxM2 = modalOpen && areaFilterManualMaxInput && areaFilterManualMaxInput.value !== ""
			? areaFilterToM2(areaFilterManualMaxInput.value, oldUnit)
			: null;
		const nextUnit = selectedAreaUnit === "m2" ? "py" : "m2";
		setGlobalAreaUnit(nextUnit);
		if (modalOpen) {
			if (areaFilterManualMinInput) {
				const value = Number.isFinite(manualMinM2) ? areaFilterFromM2(manualMinM2, selectedAreaUnit) : null;
				areaFilterManualMinInput.value = Number.isFinite(value) ? String(Math.round(value)) : "";
			}
			if (areaFilterManualMaxInput) {
				const value = Number.isFinite(manualMaxM2) ? areaFilterFromM2(manualMaxM2, selectedAreaUnit) : null;
				areaFilterManualMaxInput.value = Number.isFinite(value) ? String(Math.round(value)) : "";
			}
			syncAreaFilterManualUnitLabels();
			syncAreaFilterManualState();
		}
		if (options.keepAllDropdown) keepAllFilterMenuOpen();
		else keepMapFilterMenuOpen(areaFilterDropdown, areaFilterTrigger);
	}

	function bindAreaFilterUnitToggleButton(button)
	{
		if (!button || button.dataset.areaFilterUnitBound === "true") return;
		button.dataset.areaFilterUnitBound = "true";
		let handledByPointer = false;
		const handleToggle = (e, fromPointer = false) => {
			e.preventDefault();
			e.stopPropagation();
			if (fromPointer) handledByPointer = true;
			toggleAreaFilterUnit();
		};
		button.addEventListener("pointerdown", (e) => {
			if (typeof e.button === "number" && e.button !== 0) return;
			handleToggle(e, true);
		});
		button.addEventListener("click", (e) => {
			if (handledByPointer) {
				handledByPointer = false;
				e.preventDefault();
				e.stopPropagation();
				return;
			}
			handleToggle(e);
		});
	}

	let areaFilterManualSource = "area";

	function openAreaFilterManualModal(options = {})
	{
		if (!areaFilterManualModal) return;
		areaFilterManualSource = options.keepAllDropdown ? "all" : "area";
		syncAreaFilterManualInputsFromState();
		areaFilterManualModal.classList.add("open");
		areaFilterManualModal.setAttribute("aria-hidden", "false");
		setTimeout(() => areaFilterManualMinInput?.focus(), 0);
	}

	function closeAreaFilterManualModal()
	{
		if (!areaFilterManualModal) return;
		if (areaFilterManualModal.contains(document.activeElement) && document.activeElement && typeof document.activeElement.blur === "function") {
			document.activeElement.blur();
		}
		areaFilterManualModal.classList.remove("open");
		areaFilterManualModal.setAttribute("aria-hidden", "true");
	}

	function applyAreaFilterManualInput()
	{
		if (!validateAreaFilterManualRange()) return;
		const minM2 = areaFilterManualMinInput && areaFilterManualMinInput.value !== "" ? areaFilterToM2(areaFilterManualMinInput.value) : null;
		const maxM2 = areaFilterManualMaxInput && areaFilterManualMaxInput.value !== "" ? areaFilterToM2(areaFilterManualMaxInput.value) : null;
		selectedAreaMinM2 = Number.isFinite(minM2) ? minM2 : null;
		selectedAreaMaxTouched = Number.isFinite(maxM2);
		selectedAreaMaxM2 = selectedAreaMaxTouched ? maxM2 : AREA_FILTER_UNBOUNDED_MAX_M2;
		saveCurrentAreaFilterRange();
		const keepAllDropdown = areaFilterManualSource === "all";
		closeAreaFilterManualModal();
		areaFilterManualSource = "area";
		applyAreaFilterChange({ keepAllDropdown });
	}

