function keepMapFilterMenuOpen(dropdown, trigger)
	{
		if (!dropdown || !trigger) return;
		dropdown.classList.add("open");
		trigger.setAttribute("aria-expanded", "true");
		if (typeof closeEducationFacilityFilterPanel === "function") closeEducationFacilityFilterPanel();
		if (typeof closeConvenienceFacilityFilterPanel === "function") closeConvenienceFacilityFilterPanel();
		if (typeof closeDevelopmentFacilityFilterPanel === "function") closeDevelopmentFacilityFilterPanel();
		if (typeof closeBrokerOfficeFilterPanel === "function") closeBrokerOfficeFilterPanel();
		syncOpenMapFilterMenuPosition(dropdown);
	}

	function getAllApprovalYearFilterElements()
	{
		const root = allApprovalYearFilterOptions;
		if (!root) return {};
		return {
			root,
			summary: root.querySelector("[data-all-approval-year-summary]"),
			resetBtn: root.querySelector("[data-all-approval-year-reset]"),
			rail: root.querySelector("[data-all-approval-year-rail]"),
			fill: root.querySelector("[data-all-approval-year-fill]"),
			minRange: root.querySelector('[data-all-approval-year-range="min"]'),
			maxRange: root.querySelector('[data-all-approval-year-range="max"]')
		};
	}

	function syncApprovalYearSliderElements(minRange, maxRange, fill, minValue, maxValue)
	{
		if (minRange) minRange.value = String(minValue);
		if (maxRange) maxRange.value = String(maxValue);
		if (fill) {
			const left = (minValue / APPROVAL_YEAR_FILTER_MAX_AGE) * 100;
			const right = (maxValue / APPROVAL_YEAR_FILTER_MAX_AGE) * 100;
			fill.style.left = `${left}%`;
			fill.style.width = `${Math.max(0, right - left)}%`;
		}
	}

	function syncApprovalYearFilterUI()
	{
		if (!approvalYearFilterDropdown) return;
		const hasMin = Number.isFinite(selectedApprovalYearMinAge);
		const hasMax = Number.isFinite(selectedApprovalYearMaxAge);
		const hasActive = hasMin || hasMax;
		let label = "사용승인일";
		let summary = "전체";
		if (hasMin && hasMax) {
			label = `${selectedApprovalYearMinAge}년~${selectedApprovalYearMaxAge}년`;
			summary = label;
		} else if (hasMin) {
			label = `${selectedApprovalYearMinAge}년 이상`;
			summary = label;
		} else if (hasMax) {
			label = `${selectedApprovalYearMaxAge}년 이하`;
			summary = label;
		}

		if (approvalYearFilterLabel) approvalYearFilterLabel.textContent = label;
		if (approvalYearFilterSummaryText) approvalYearFilterSummaryText.textContent = summary;
		approvalYearFilterDropdown.classList.toggle("has-active", hasActive);
		if (approvalYearFilterResetBtn) {
			approvalYearFilterResetBtn.classList.toggle("is-visible", hasActive);
			approvalYearFilterResetBtn.setAttribute("aria-hidden", hasActive ? "false" : "true");
			approvalYearFilterResetBtn.tabIndex = hasActive ? 0 : -1;
		}

		const minValue = hasMin ? selectedApprovalYearMinAge : 0;
		const maxValue = hasMax ? selectedApprovalYearMaxAge : APPROVAL_YEAR_FILTER_MAX_AGE;
		syncApprovalYearSliderElements(approvalYearFilterMinRange, approvalYearFilterMaxRange, approvalYearFilterSliderFill, minValue, maxValue);

		const allApproval = getAllApprovalYearFilterElements();
		if (allApproval.root) {
			if (allApproval.summary) allApproval.summary.textContent = summary;
			if (allApproval.resetBtn) {
				allApproval.resetBtn.hidden = !hasActive;
				allApproval.resetBtn.classList.toggle("is-visible", hasActive);
				allApproval.resetBtn.setAttribute("aria-hidden", hasActive ? "false" : "true");
				allApproval.resetBtn.tabIndex = hasActive ? 0 : -1;
			}
			syncApprovalYearSliderElements(allApproval.minRange, allApproval.maxRange, allApproval.fill, minValue, maxValue);
		}
	}

	if (typeof window !== "undefined") {
		window.realjejuSyncApprovalYearFilterUI = syncApprovalYearFilterUI;
	}

	function applyApprovalYearFilterChange(options = {})
	{
		syncApprovalYearFilterUI();
		if (options.keepAllDropdown) keepAllFilterMenuOpen();
		else keepMapFilterMenuOpen(approvalYearFilterDropdown, approvalYearFilterTrigger);
		state.initialRandomListActive = false;
		resetFilterSelectionState();
		scrollListToTop();
		applyFilter();
		if (options.keepAllDropdown) keepAllFilterMenuOpen();
		else keepMapFilterMenuOpen(approvalYearFilterDropdown, approvalYearFilterTrigger);
		syncLeftAllButtonToMapFilters();
	}

	function getApprovalYearFilterThumbGapAgeForRail(rail)
	{
		const railWidth = rail ? rail.getBoundingClientRect().width : 0;
		if (!railWidth) return 1;
		const rawGap = (FILTER_RANGE_THUMB_GAP_PX / railWidth) * APPROVAL_YEAR_FILTER_MAX_AGE;
		return Math.max(1, Math.round(rawGap));
	}

	function getApprovalYearFilterThumbGapAge()
	{
		return getApprovalYearFilterThumbGapAgeForRail(approvalYearFilterSliderRail);
	}

	function handleApprovalYearRangeInput(event)
	{
		if (!approvalYearFilterMinRange || !approvalYearFilterMaxRange) return;
		const gap = getApprovalYearFilterThumbGapAge();
		let min = Number(approvalYearFilterMinRange.value);
		let max = Number(approvalYearFilterMaxRange.value);
		if (!Number.isFinite(min)) min = 0;
		if (!Number.isFinite(max)) max = APPROVAL_YEAR_FILTER_MAX_AGE;
		min = Math.max(0, Math.min(APPROVAL_YEAR_FILTER_MAX_AGE, Math.round(min)));
		max = Math.max(0, Math.min(APPROVAL_YEAR_FILTER_MAX_AGE, Math.round(max)));
		if (event && event.target === approvalYearFilterMinRange) {
			min = Math.min(min, Math.max(0, max - gap));
		} else if (event && event.target === approvalYearFilterMaxRange) {
			max = Math.max(max, Math.min(APPROVAL_YEAR_FILTER_MAX_AGE, min + gap));
		} else if (min + gap > max) {
			max = Math.min(APPROVAL_YEAR_FILTER_MAX_AGE, min + gap);
			if (max >= APPROVAL_YEAR_FILTER_MAX_AGE) min = Math.max(0, max - gap);
		}
		approvalYearFilterMinRange.value = String(min);
		approvalYearFilterMaxRange.value = String(max);
		selectedApprovalYearMinAge = min <= 0 ? null : min;
		selectedApprovalYearMaxAge = max >= APPROVAL_YEAR_FILTER_MAX_AGE ? null : max;
		applyApprovalYearFilterChange();
	}

	function updateApprovalYearRangeFromInputs(minRange, maxRange, event, rail)
	{
		if (!minRange || !maxRange) return false;
		const gap = getApprovalYearFilterThumbGapAgeForRail(rail || approvalYearFilterSliderRail);
		let min = Number(minRange.value);
		let max = Number(maxRange.value);
		if (!Number.isFinite(min)) min = 0;
		if (!Number.isFinite(max)) max = APPROVAL_YEAR_FILTER_MAX_AGE;
		min = Math.max(0, Math.min(APPROVAL_YEAR_FILTER_MAX_AGE, Math.round(min)));
		max = Math.max(0, Math.min(APPROVAL_YEAR_FILTER_MAX_AGE, Math.round(max)));
		if (event && event.target === minRange) {
			min = Math.min(min, Math.max(0, max - gap));
		} else if (event && event.target === maxRange) {
			max = Math.max(max, Math.min(APPROVAL_YEAR_FILTER_MAX_AGE, min + gap));
		} else if (min + gap > max) {
			max = Math.min(APPROVAL_YEAR_FILTER_MAX_AGE, min + gap);
			if (max >= APPROVAL_YEAR_FILTER_MAX_AGE) min = Math.max(0, max - gap);
		}
		minRange.value = String(min);
		maxRange.value = String(max);
		selectedApprovalYearMinAge = min <= 0 ? null : min;
		selectedApprovalYearMaxAge = max >= APPROVAL_YEAR_FILTER_MAX_AGE ? null : max;
		syncApprovalYearFilterUI();
		return true;
	}

	function handleAllApprovalYearRangeInput(event)
	{
		const els = getAllApprovalYearFilterElements();
		if (!els.root) return;
		updateApprovalYearRangeFromInputs(els.minRange, els.maxRange, event, els.rail);
		keepAllFilterMenuOpen();
	}

	function handleAllApprovalYearRangeCommit(event)
	{
		const els = getAllApprovalYearFilterElements();
		if (!els.root) return;
		updateApprovalYearRangeFromInputs(els.minRange, els.maxRange, event, els.rail);
		applyApprovalYearFilterChange({ keepAllDropdown: true });
	}

	let activeApprovalYearTrackHandle = null;

	function getApprovalYearTrackValueFromPointer(event)
	{
		if (!approvalYearFilterSliderRail) return 0;
		const rect = approvalYearFilterSliderRail.getBoundingClientRect();
		const width = Math.max(1, rect.width);
		const ratio = Math.max(0, Math.min(1, (event.clientX - rect.left) / width));
		return Math.max(0, Math.min(APPROVAL_YEAR_FILTER_MAX_AGE, Math.round(ratio * APPROVAL_YEAR_FILTER_MAX_AGE)));
	}

	function isApprovalYearPointerNearHandle(event)
	{
		if (!event || !approvalYearFilterSliderRail || !approvalYearFilterMinRange || !approvalYearFilterMaxRange) return false;
		const rect = approvalYearFilterSliderRail.getBoundingClientRect();
		const width = Math.max(1, rect.width);
		const maxValue = APPROVAL_YEAR_FILTER_MAX_AGE > 0 ? APPROVAL_YEAR_FILTER_MAX_AGE : 1;
		const pointerX = event.clientX;
		const handleRadius = Math.max(18, FILTER_RANGE_THUMB_GAP_PX * 0.5);
		return [approvalYearFilterMinRange, approvalYearFilterMaxRange].some(input => {
			const value = Number(input.value);
			const safeValue = Number.isFinite(value) ? Math.max(0, Math.min(maxValue, value)) : 0;
			const handleX = rect.left + (safeValue / maxValue) * width;
			return Math.abs(pointerX - handleX) <= handleRadius;
		});
	}

	function getApprovalYearRangeValues()
	{
		const min = approvalYearFilterMinRange ? Number(approvalYearFilterMinRange.value) : 0;
		const max = approvalYearFilterMaxRange ? Number(approvalYearFilterMaxRange.value) : APPROVAL_YEAR_FILTER_MAX_AGE;
		return {
			min: Number.isFinite(min) ? min : 0,
			max: Number.isFinite(max) ? max : APPROVAL_YEAR_FILTER_MAX_AGE
		};
	}

	function getNearestApprovalYearHandle(value)
	{
		const { min, max } = getApprovalYearRangeValues();
		if (value <= min) return "min";
		if (value >= max) return "max";
		return Math.abs(value - min) <= Math.abs(max - value) ? "min" : "max";
	}

	function moveApprovalYearHandleToPointer(event)
	{
		if (!activeApprovalYearTrackHandle || !approvalYearFilterMinRange || !approvalYearFilterMaxRange) return;
		const value = getApprovalYearTrackValueFromPointer(event);
		const target = activeApprovalYearTrackHandle === "min" ? approvalYearFilterMinRange : approvalYearFilterMaxRange;
		target.value = String(value);
		handleApprovalYearRangeInput({ target });
	}

	function handleApprovalYearTrackPointerDown(event)
	{
		if (!approvalYearFilterSliderRail || !approvalYearFilterMinRange || !approvalYearFilterMaxRange) return;
		if (typeof event.button === "number" && event.button !== 0) return;
		const rangeTarget = event.target && event.target.closest ? event.target.closest(".approval-year-filter-range") : null;
		if (rangeTarget && isApprovalYearPointerNearHandle(event)) return;
		event.preventDefault();
			event.stopPropagation();
			const value = getApprovalYearTrackValueFromPointer(event);
			activeApprovalYearTrackHandle = getNearestApprovalYearHandle(value);
				setFilterTrackCursorForHandle(
					event,
					approvalYearFilterSliderRail,
					activeApprovalYearTrackHandle === "min" ? approvalYearFilterMinRange : approvalYearFilterMaxRange,
					APPROVAL_YEAR_FILTER_MAX_AGE
				);
			try {
			approvalYearFilterSliderRail.setPointerCapture(event.pointerId);
		} catch (_) {
			// Pointer capture can fail on older embedded browsers; dragging still works while inside the rail.
		}
		moveApprovalYearHandleToPointer(event);
	}

	function handleApprovalYearTrackPointerMove(event)
	{
		if (!activeApprovalYearTrackHandle) return;
		event.preventDefault();
		event.stopPropagation();
		moveApprovalYearHandleToPointer(event);
		setFilterTrackCursorForHandle(
			event,
			approvalYearFilterSliderRail,
			activeApprovalYearTrackHandle === "min" ? approvalYearFilterMinRange : approvalYearFilterMaxRange,
			APPROVAL_YEAR_FILTER_MAX_AGE
		);
	}

	function handleApprovalYearTrackPointerEnd(event)
		{
			if (!activeApprovalYearTrackHandle) return;
			activeApprovalYearTrackHandle = null;
			clearFilterTrackCursor();
			try {
			approvalYearFilterSliderRail && approvalYearFilterSliderRail.releasePointerCapture(event.pointerId);
		} catch (_) {}
	}

	let activeAllApprovalYearTrackContext = null;

	function getApprovalYearTrackValueFromPointerForRail(event, rail)
	{
		if (!event || !rail) return 0;
		const rect = rail.getBoundingClientRect();
		const width = Math.max(1, rect.width);
		const ratio = Math.max(0, Math.min(1, (event.clientX - rect.left) / width));
		return Math.max(0, Math.min(APPROVAL_YEAR_FILTER_MAX_AGE, Math.round(ratio * APPROVAL_YEAR_FILTER_MAX_AGE)));
	}

	function isApprovalYearPointerNearHandleForInputs(event, rail, minRange, maxRange)
	{
		if (!event || !rail || !minRange || !maxRange) return false;
		const rect = rail.getBoundingClientRect();
		const width = Math.max(1, rect.width);
		const maxValue = APPROVAL_YEAR_FILTER_MAX_AGE > 0 ? APPROVAL_YEAR_FILTER_MAX_AGE : 1;
		const pointerX = event.clientX;
		const handleRadius = Math.max(18, FILTER_RANGE_THUMB_GAP_PX * 0.5);
		return [minRange, maxRange].some(input => {
			const value = Number(input.value);
			const safeValue = Number.isFinite(value) ? Math.max(0, Math.min(maxValue, value)) : 0;
			const handleX = rect.left + (safeValue / maxValue) * width;
			return Math.abs(pointerX - handleX) <= handleRadius;
		});
	}

	function getNearestApprovalYearHandleForInputs(value, minRange, maxRange)
	{
		const min = minRange ? Number(minRange.value) : 0;
		const max = maxRange ? Number(maxRange.value) : APPROVAL_YEAR_FILTER_MAX_AGE;
		const safeMin = Number.isFinite(min) ? min : 0;
		const safeMax = Number.isFinite(max) ? max : APPROVAL_YEAR_FILTER_MAX_AGE;
		if (value <= safeMin) return minRange;
		if (value >= safeMax) return maxRange;
		return Math.abs(value - safeMin) <= Math.abs(safeMax - value) ? minRange : maxRange;
	}

	function moveAllApprovalYearHandleToPointer(event)
	{
		const context = activeAllApprovalYearTrackContext;
		if (!context || !context.target || !context.rail || !context.minRange || !context.maxRange) return;
		const value = getApprovalYearTrackValueFromPointerForRail(event, context.rail);
		context.target.value = String(value);
		updateApprovalYearRangeFromInputs(context.minRange, context.maxRange, { target: context.target }, context.rail);
	}

	function handleAllApprovalYearTrackPointerDown(event)
	{
		const els = getAllApprovalYearFilterElements();
		if (!els.root || !els.rail || !els.minRange || !els.maxRange) return;
		if (typeof event.button === "number" && event.button !== 0) return;
		const rangeTarget = event.target && event.target.closest ? event.target.closest(".approval-year-filter-range") : null;
		if (rangeTarget && isApprovalYearPointerNearHandleForInputs(event, els.rail, els.minRange, els.maxRange)) return;
		event.preventDefault();
		event.stopPropagation();
		const value = getApprovalYearTrackValueFromPointerForRail(event, els.rail);
		const target = getNearestApprovalYearHandleForInputs(value, els.minRange, els.maxRange);
		if (!target) return;
		activeAllApprovalYearTrackContext = { rail: els.rail, minRange: els.minRange, maxRange: els.maxRange, target };
		setFilterTrackCursorForHandle(event, els.rail, target, APPROVAL_YEAR_FILTER_MAX_AGE);
		try {
			els.rail.setPointerCapture(event.pointerId);
		} catch (_) {}
		moveAllApprovalYearHandleToPointer(event);
	}

	function handleAllApprovalYearTrackPointerMove(event)
	{
		if (!activeAllApprovalYearTrackContext) return;
		event.preventDefault();
		event.stopPropagation();
		moveAllApprovalYearHandleToPointer(event);
		setFilterTrackCursorForHandle(event, activeAllApprovalYearTrackContext.rail, activeAllApprovalYearTrackContext.target, APPROVAL_YEAR_FILTER_MAX_AGE);
	}

	function handleAllApprovalYearTrackPointerEnd(event)
	{
		if (!activeAllApprovalYearTrackContext) return;
		const rail = activeAllApprovalYearTrackContext.rail;
		moveAllApprovalYearHandleToPointer(event);
		activeAllApprovalYearTrackContext = null;
		clearFilterTrackCursor();
		try {
			rail && rail.releasePointerCapture(event.pointerId);
		} catch (_) {}
		applyApprovalYearFilterChange({ keepAllDropdown: true });
	}

