		if (selectedFullOptionOnly) activeLabels.push("풀옵션");
		if (selectedOceanViewOnly) activeLabels.push("오션뷰");
		if (selectedPetOnly) activeLabels.push("반려동물가능");

		const hasActive = activeLabels.length > 0;
