		if (extraParkingChk) extraParkingChk.checked = !!selectedParkingOnly;
		if (extraPetChk) extraPetChk.checked = !!selectedPetOnly;
		if (extraCityGasChk) extraCityGasChk.checked = !!selectedCityGasOnly;
