function getDetailShareUrl()
{
	if (activeDetailSharePayload && activeDetailSharePayload.url) {
		return String(activeDetailSharePayload.url);
	}
	if (currentDetailItem && currentDetailItem.id != null) {
		return getDetailUrlById(currentDetailItem.id).href;
	}
	if (currentDetailItem && currentDetailItem.link && currentDetailItem.link !== "#") {
		try {
			return new URL(currentDetailItem.link, location.href).href;
		} catch (err) {
			return currentDetailItem.link;
		}
	}
	return location.href;
}

function getDetailShareTitle()
{
	if (activeDetailSharePayload && activeDetailSharePayload.title) {
		return String(activeDetailSharePayload.title);
	}
	return currentDetailItem && currentDetailItem.title
	? currentDetailItem.title
	: "제주 프리미엄 부동산";
}

function getDetailShareText()
{
	if (activeDetailSharePayload && activeDetailSharePayload.text) {
		return String(activeDetailSharePayload.text);
	}
	const parts = [];
	const title = getDetailShareTitle();
	const deal = currentDetailItem?.dealType || currentDetailItem?.deal || "";
	const price = currentDetailItem?.priceText || currentDetailItem?.price || "";
	const address = currentDetailItem?.address || currentDetailItem?.roadAddress || "";

	parts.push(`[REALJEJU.APP] ${title}`);
	if (deal || price) {
		parts.push([deal, price].filter(Boolean).join(" "));
	}
	if (address) {
		parts.push(address);
	}
	parts.push(getDetailShareUrl());
	return parts.filter(Boolean).join("\n");
}

function getDetailShareDescription()
{
	if (activeDetailSharePayload && activeDetailSharePayload.description) {
		return String(activeDetailSharePayload.description);
	}
	const deal = currentDetailItem?.dealType || currentDetailItem?.deal || "";
	const price = currentDetailItem?.priceText || currentDetailItem?.price || "";
	const address = currentDetailItem?.address || currentDetailItem?.roadAddress || "";
	return [[deal, price].filter(Boolean).join(" "), address].filter(Boolean).join(" · ") || "REALJEJU.APP 매물 정보";
}

function getDetailShareImageUrl()
{
	if (activeDetailSharePayload && activeDetailSharePayload.imageUrl) {
		return String(activeDetailSharePayload.imageUrl);
	}
	const image = Array.isArray(currentDetailItem?.images) && currentDetailItem.images.length
		? currentDetailItem.images[0]
		: currentDetailItem?.image;
	if (!image) return "";
	try {
		const url = new URL(image, location.href);
		return /^https?:$/i.test(url.protocol) ? url.href : "";
	} catch (err) {
		return "";
	}
}

function getDetailShareButtonTitle()
{
	if (activeDetailSharePayload && activeDetailSharePayload.buttonTitle) {
		return String(activeDetailSharePayload.buttonTitle);
	}
	return "매물 보기";
}

function ensureKakaoShareReady()
{
	if (!window.Kakao) return false;
	try {
		if (typeof window.Kakao.isInitialized === "function" && !window.Kakao.isInitialized()) {
			window.Kakao.init(REALJEJU_KAKAO_JS_KEY);
		}
		return !!(window.Kakao.Share && typeof window.Kakao.Share.sendDefault === "function");
	} catch (err) {
		console.error("카카오 공유 초기화 실패:", err);
		return false;
	}
}

function showShareCopiedFeedback(success)
{
	if (!detailShareFeedback) return;
	detailShareFeedback.textContent = success ? "복사됨" : "실패";
	setTimeout(() => {
		detailShareFeedback.textContent = "";
	}, 1200);
}

window.shareDetailCopy = async function (event) {
	if (event) {
		event.preventDefault();
		event.stopPropagation();
	}
	const ok = await copyTextWithFallback(getDetailShareUrl());
	showShareCopiedFeedback(ok);
};

window.shareDetailKakao = async function (event) {
	if (event) {
		event.preventDefault();
		event.stopPropagation();
	}

	const shareUrl = getDetailShareUrl();
	try {
		if (!window.Kakao && typeof window.realjejuPreloadKakaoShare === "function") {
			await window.realjejuPreloadKakaoShare();
		}
		if (/^https?:\/\//i.test(shareUrl) && ensureKakaoShareReady()) {
			const title = getDetailShareTitle();
			const description = getDetailShareDescription();
			const imageUrl = getDetailShareImageUrl();
			const buttonTitle = getDetailShareButtonTitle();
			const link = {
				mobileWebUrl: shareUrl,
				webUrl: shareUrl
			};

			window.Kakao.Share.sendDefault({
				objectType: "feed",
				content: {
					title,
					description,
					imageUrl: imageUrl || "https://제주도부동산.닷컴/img/landingpage_1.jpg",
					link
				},
				buttons: [
					{
						title: buttonTitle,
						link
					}
				]
			});
			if (typeof closeShareMenu === "function") closeShareMenu();
			return;
		}

		if (navigator.share) {
			await navigator.share({
				title: getDetailShareTitle(),
				text: getDetailShareDescription(),
				url: shareUrl
			});
			if (typeof closeShareMenu === "function") closeShareMenu();
			return;
		}
	} catch (err) {
		console.error("카카오톡 공유 실패:", err);
	}

	const ok = await copyTextWithFallback(shareUrl);
	showShareCopiedFeedback(ok);
	if (typeof closeShareMenu === "function") closeShareMenu();
};

window.shareDetailNative = async function (event) {
	if (event) {
		event.preventDefault();
		event.stopPropagation();
	}
	try {
		if (navigator.share) {
			await navigator.share({
				title: getDetailShareTitle(),
				text: getDetailShareText(),
				url: getDetailShareUrl()
			});
			if (typeof closeShareMenu === "function") closeShareMenu();
			return;
		}
	} catch (err) {
		console.error("공유 실패:", err);
	}
	const ok = await copyTextWithFallback(getDetailShareText());
	showShareCopiedFeedback(ok);
	if (typeof closeShareMenu === "function") closeShareMenu();
};

window.shareDetailSms = function (event) {
	if (event) {
		event.preventDefault();
		event.stopPropagation();
	}
	const body = encodeURIComponent(getDetailShareText());
	const smsUrl = /iPhone|iPad|iPod/.test(navigator.userAgent) ? `sms:&body=${body}` : `sms:?body=${body}`;
	if (typeof closeShareMenu === "function") closeShareMenu();
	location.href = smsUrl;
};

function setMapRegionFromCurrentLocation(lat, lng)
{
	const requestSeq = ++mapCenterRegionRequestSeq;
	resolveMapCenterRegionMeta(lat, lng).then((meta) => {
		if (requestSeq !== mapCenterRegionRequestSeq || !meta) return;
		mapRegionFilterState.mode = "list";
		setMapCenterRegionLabel(meta);
	});
}

function moveMapToCurrentLocation()
{
	if (!state.map || !window.kakao || !kakao.maps) return;
	if (!navigator.geolocation) {
		alert("이 브라우저에서는 현위치를 사용할 수 없습니다.");
		return;
	}

	navigator.geolocation.getCurrentPosition(
	(position) => {
		if (!state.map) return;

		const lat = Number(position.coords && position.coords.latitude);
		const lng = Number(position.coords && position.coords.longitude);

		if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
			alert("현위치를 가져오지 못했습니다.");
			return;
		}

		const currentLatLng = new kakao.maps.LatLng(lat, lng);
		setMapRegionFromCurrentLocation(lat, lng);
		state.map.setCenter(currentLatLng);
		state.map.setLevel(GEOLOCATION_MAP_LEVEL, { animate: { duration: 300 } });
	},
	() => {
		alert("현위치를 가져오지 못했습니다. 브라우저 위치 권한을 확인해 주세요.");
	},
	{
		enableHighAccuracy: false,
		timeout: 8000,
		maximumAge: 0
	}
	);
}

function initCustomZoomButtons()
{
	const currentLocationBtn = document.getElementById("currentLocationBtn");
	if (!currentLocationBtn) return;

	currentLocationBtn.addEventListener("click", function (e) {
		e.preventDefault();
		e.stopPropagation();
		moveMapToCurrentLocation();
	});
}

function shouldLoadInitialPropertyMapDataForCurrentRoute()
{
	const pathname = String(
		window.realjejuInitialNormalizedRoutePath
		|| window.location.pathname
		|| "/"
	).replace(/\/{2,}/g, "/").replace(/\/+$/, "") || "/";
	return /^\/properties(?:\/|$)/i.test(pathname)
		|| /^\/admin\/properties(?:\/|$)/i.test(pathname);
}

function shouldPrefetchLandingPropertyViewportForCurrentRoute()
{
	const pathname = String(
		window.realjejuInitialNormalizedRoutePath
		|| window.location.pathname
		|| "/"
	).replace(/\/{2,}/g, "/").replace(/\/+$/, "") || "/";
	return pathname === "/";
}

window.realjejuFinishAppBootstrap = async function ()
{
	// 4.924부터는 이전 버전의 전체 매물 IndexedDB 배열을 첫 화면에 적용하지 않는다.
	const initialPropertyCachePromise = Promise.resolve(false);
	if (isEvChargerServiceRouteActive()) {
		await activateEvChargerServiceMap();
	}
	initCustomZoomButtons();
	// 6.140: the 298KB event binder no longer blocks the first map/data paint.
	// Capture-phase interaction initializes it before the following click/input event, and idle is the fallback.
	const initializeAppEvents = () => {
		const rootElement = document.documentElement;
		if (rootElement.dataset.realjejuAppEventsInitialized === "true") return;
		rootElement.dataset.realjejuAppEventsInitialized = "true";
		try {
			initEvents();
		} catch (error) {
			delete rootElement.dataset.realjejuAppEventsInitialized;
			throw error;
		}
	};
	const initializeAppEventsSafely = () => {
		try {
			initializeAppEvents();
		} catch (error) {
			console.error("[realjeju] event initialization failed", error);
		}
	};
	document.addEventListener("pointerdown", initializeAppEventsSafely, { capture: true, once: true });
	document.addEventListener("keydown", initializeAppEventsSafely, { capture: true, once: true });
	document.addEventListener("focusin", initializeAppEventsSafely, { capture: true, once: true });
	const queueEventInitialization = () => {
		if (typeof window.requestIdleCallback === "function") {
			window.requestIdleCallback(initializeAppEventsSafely, { timeout: 350 });
		} else {
			window.setTimeout(initializeAppEventsSafely, 0);
		}
	};
	if (document.visibilityState === "hidden" || typeof window.requestAnimationFrame !== "function") {
		window.setTimeout(initializeAppEventsSafely, 0);
	} else {
		window.requestAnimationFrame(queueEventInitialization);
	}
	selectedDeal = selectedDeal instanceof Set ? selectedDeal : new Set();
	selectedType = selectedType instanceof Set ? selectedType : new Set();
	ensureTypeFilterHasSelection();
	syncFeatureButtons();
	if (shouldPrefetchLandingPropertyViewportForCurrentRoute()) {
		scheduleLandingPropertyViewportPrefetch();
	}
	await initialPropertyCachePromise;
};

window.realjejuStartInitialMapData = function ()
{
	scheduleInitialMapDataAfterFirstPaint();
};

function scheduleInitialMapDataAfterFirstPaint()
{
	if (initialMapDataScheduled) return;
	initialMapDataScheduled = true;

	const run = () => {
		loadInitialMapData().catch((error) => {
			console.error("초기 지도 데이터 지연 처리 실패:", error);
		});
	};
	const queueAfterPaint = () => {
		if (typeof window.requestIdleCallback === "function") {
			window.requestIdleCallback(run, { timeout: 250 });
		} else {
			window.setTimeout(run, 0);
		}
	};

	if (document.visibilityState === "hidden" || typeof window.requestAnimationFrame !== "function") {
		queueAfterPaint();
		return;
	}

	window.requestAnimationFrame(() => {
		window.requestAnimationFrame(queueAfterPaint);
	});
}

function loadInitialMapData()
{
	if (initialMapDataPromise) return initialMapDataPromise;

	initialMapDataPromise = (async () => {
		const shouldLoadPropertyMapData = shouldLoadInitialPropertyMapDataForCurrentRoute();
		const shouldLoadLandingRecommendations = shouldPrefetchLandingPropertyViewportForCurrentRoute();

		if (shouldLoadPropertyMapData || shouldLoadLandingRecommendations) {
			loadRecommendData();
		}
		syncFeatureButtons();

		try {
			if (shouldLoadPropertyMapData) await loadProperties();
			syncFeatureButtons();
		} catch (err) {
			console.error("초기 지도 데이터 처리 실패:", err);
			syncFeatureButtons();
		} finally {
			window.realjejuMapDataReady = true;
			if (window.realjejuRouter && typeof window.realjejuRouter.onMapDataReady === "function") {
				await window.realjejuRouter.onMapDataReady();
			} else {
				await openDetailFromUrl({ replaceHistory: true });
			}
		}
	})();

	return initialMapDataPromise;
}
